import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export enum ConnectionStatus {
  IDLE = 'IDLE',
  CONNECTING = 'CONNECTING',
  CONNECTED = 'CONNECTED',
  ERROR = 'ERROR'
}

export interface Message {
  id: string;
  role: 'user' | 'model';
  text: string;
  timestamp: Date;
}

export interface AppConfig {
  model: string;
  temperature: number;
  systemInstruction: string;
}

import { GoogleGenAI } from "@google/genai";

// Initialization of the Gemini client
// Assume process.env.API_KEY is provided and valid
const getClient = () => {
  return new GoogleGenAI({ apiKey: process.env.API_KEY });
};

export const sendMessage = async (prompt: string, modelName: string = 'gemini-3-flash-preview') => {
  const ai = getClient();
  try {
    const response = await ai.models.generateContent({
      model: modelName,
      contents: prompt,
    });
    return response.text || "No response text received.";
  } catch (error) {
    console.error("Gemini API Error:", error);
    throw error;
  }
};

export const testConnection = async () => {
  const ai = getClient();
  try {
    // A simple prompt to verify API connectivity
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: 'Ping',
    });
    return !!response.text;
  } catch (error) {
    return false;
  }
};

