import React, { useState, useEffect, useRef } from 'react';
import Layout from './components/Layout';
import { sendMessage, testConnection } from './services/geminiService';
import { Message, ConnectionStatus } from './types';

const App: React.FC = () => {
  const [messages, setMessages] = useState<Message[]>([]);
  const [input, setInput] = useState('');
  const [status, setStatus] = useState<ConnectionStatus>(ConnectionStatus.IDLE);
  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const init = async () => {
      setStatus(ConnectionStatus.CONNECTING);
      const isConnected = await testConnection();
      setStatus(isConnected ? ConnectionStatus.CONNECTED : ConnectionStatus.ERROR);
    };
    init();
  }, []);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [messages]);

  const handleSend = async () => {
    if (!input.trim()) return;

    const userMsg: Message = {
      id: Date.now().toString(),
      role: 'user',
      text: input,
      timestamp: new Date(),
    };

    setMessages(prev => [...prev, userMsg]);
    setInput('');

    try {
      const response = await sendMessage(input);
      const modelMsg: Message = {
        id: (Date.now() + 1).toString(),
        role: 'model',
        text: response,
        timestamp: new Date(),
      };
      setMessages(prev => [...prev, modelMsg]);
    } catch (err) {
      const errorMsg: Message = {
        id: (Date.now() + 1).toString(),
        role: 'model',
        text: "Error: Failed to fetch response from Gemini. Please check your console for details.",
        timestamp: new Date(),
      };
      setMessages(prev => [...prev, errorMsg]);
    }
  };

  const sidebarContent = (
    <div className="space-y-6">
      <div>
        <h3 className="text-xs font-semibold text-slate-500 uppercase tracking-wider mb-3">Settings</h3>
        <div className="space-y-2">
          <div className="p-3 bg-slate-800/50 rounded-lg border border-slate-700/50">
            <p className="text-xs text-slate-400 mb-1">Active Model</p>
            <p className="text-sm font-medium">gemini-3-flash-preview</p>
          </div>
        </div>
      </div>
      <div>
        <h3 className="text-xs font-semibold text-slate-500 uppercase tracking-wider mb-3">History</h3>
        <div className="text-sm text-slate-500 italic">No recent sessions</div>
      </div>
    </div>
  );

  return (
    <Layout sidebarContent={sidebarContent}>
      <div className="flex flex-col h-[calc(100vh-12rem)]">
        {/* Intro */}
        {messages.length === 0 && (
          <div className="flex-1 flex flex-col items-center justify-center text-center space-y-6 animate-in fade-in slide-in-from-bottom-4 duration-1000">
            <div className="w-16 h-16 bg-blue-500/10 rounded-2xl flex items-center justify-center border border-blue-500/20 shadow-xl shadow-blue-500/5">
              <svg className="w-8 h-8 text-blue-400" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 10V3L4 14h7v7l9-11h-7z" />
              </svg>
            </div>
            <div>
              <h2 className="text-3xl font-bold mb-2">Blank Gemini Canvas</h2>
              <p className="text-slate-400 max-w-md mx-auto">
                Your high-performance starting point for building sophisticated AI experiences. 
                Type a prompt below to start interacting with Gemini.
              </p>
            </div>
            <div className="grid grid-cols-1 md:grid-cols-3 gap-4 w-full max-w-2xl mt-8">
              {['Analyze this code', 'Write a story', 'Explain quantum physics'].map((prompt) => (
                <button 
                  key={prompt}
                  onClick={() => setInput(prompt)}
                  className="p-4 bg-slate-900 border border-slate-800 rounded-xl text-sm text-slate-300 hover:border-blue-500/50 hover:bg-slate-800 transition-all text-left"
                >
                  {prompt}
                </button>
              ))}
            </div>
          </div>
        )}

        {/* Messages */}
        <div ref={scrollRef} className="flex-1 overflow-y-auto space-y-6 pb-8">
          {messages.map((msg) => (
            <div 
              key={msg.id} 
              className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}
            >
              <div 
                className={`max-w-[85%] p-4 rounded-2xl shadow-sm ${
                  msg.role === 'user' 
                    ? 'bg-blue-600 text-white rounded-tr-none' 
                    : 'bg-slate-900 border border-slate-800 text-slate-200 rounded-tl-none'
                }`}
              >
                <div className="text-sm leading-relaxed whitespace-pre-wrap">
                  {msg.text}
                </div>
                <div className={`text-[10px] mt-2 opacity-50 ${msg.role === 'user' ? 'text-right' : 'text-left'}`}>
                  {msg.timestamp.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                </div>
              </div>
            </div>
          ))}
        </div>

        {/* Input area */}
        <div className="mt-auto pt-6 border-t border-slate-800 bg-slate-950">
          <div className="relative group">
            <textarea
              value={input}
              onChange={(e) => setInput(e.target.value)}
              onKeyDown={(e) => {
                if (e.key === 'Enter' && !e.shiftKey) {
                  e.preventDefault();
                  handleSend();
                }
              }}
              placeholder="Ask anything..."
              className="w-full bg-slate-900 border border-slate-800 rounded-2xl py-4 pl-4 pr-16 focus:outline-none focus:ring-2 focus:ring-blue-500/50 focus:border-blue-500/50 transition-all min-h-[60px] max-h-[200px] resize-none"
              rows={1}
            />
            <button 
              onClick={handleSend}
              disabled={!input.trim()}
              className="absolute right-3 bottom-3 p-2 bg-blue-600 hover:bg-blue-500 disabled:bg-slate-800 disabled:text-slate-600 text-white rounded-xl transition-all shadow-lg"
            >
              <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 19l9 2-9-18-9 18 9-2zm0 0v-8" />
              </svg>
            </button>
          </div>
          <p className="text-center text-[10px] text-slate-600 mt-3">
            AI can make mistakes. Consider checking important information.
          </p>
        </div>
      </div>
    </Layout>
  );
};

export default App;

{
  "name": "Faraid Malayalam - Islamic Inheritance Assistant",
  "description": "A specialized tool for managing and preparing Islamic inheritance data based on Shafi'i Fiqh, featuring Malayalam support and an elegant Islamic-inspired UI.",
  "requestFramePermissions": [
    "camera",
    "microphone"
  ]
}

export enum ConnectionStatus {
  IDLE = 'IDLE',
  CONNECTING = 'CONNECTING',
  CONNECTED = 'CONNECTED',
  ERROR = 'ERROR'
}

export interface Message {
  id: string;
  role: 'user' | 'model';
  text: string;
  timestamp: Date;
}

export interface EstateInfo {
  totalAssets: number;
  funeralExpenses: number;
  debts: number;
  willAmount: number;
}

export type HeirType = 
  | 'Spouse' 
  | 'Father' 
  | 'Mother' 
  | 'Son' 
  | 'Daughter' 
  | 'Grandson' 
  | 'Granddaughter' 
  | 'PaternalGrandfather' 
  | 'MaternalGrandmother'
  | 'PaternalGrandmother'
  | 'FullBrother'
  | 'FullSister'
  | 'ConsanguineBrother'
  | 'ConsanguineSister'
  | 'UterineBrother'
  | 'UterineSister'
  | 'Nephew'
  | 'PaternalUncle';

export interface Heir {
  id: string;
  type: HeirType;
  count: number;
}

export enum AppStep {
  ESTATE = 'ESTATE',
  DECEASED_INFO = 'DECEASED_INFO',
  HEIRS = 'HEIRS',
  SUMMARY = 'SUMMARY'
}

import { GoogleGenAI } from "@google/genai";

const getClient = () => {
  return new GoogleGenAI({ apiKey: process.env.API_KEY });
};

const SYSTEM_INSTRUCTION = `
You are the "Islamic Inheritance Assistant (Faraid Malayalam)" Counselor. 
Your goal is to guide the user through the process of listing assets and heirs for Islamic inheritance according to Shafi'i Fiqh (commonly followed in Kerala).
Respond in a mix of Malayalam and English (Manglish/Malayalam script) as appropriate for a Kerala audience.
Be respectful, compassionate, and precise with Islamic terminology (e.g., Faraid, Asaba, Zawil Furud).
Do not perform final mathematical calculations of shares unless specifically asked after all data is collected, but you can explain the rules for specific heirs.
If the user asks about a specific relative, explain their general eligibility.
Keep responses concise and supportive.
`;

export const sendFaraidMessage = async (prompt: string, context?: string) => {
  const ai = getClient();
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: context ? `Context: ${context}\n\nUser: ${prompt}` : prompt,
      config: {
        systemInstruction: SYSTEM_INSTRUCTION,
      }
    });
    return response.text || "ക്ഷമിക്കണം, എനിക്ക് മറുപടി നൽകാൻ സാധിച്ചില്ല. (Sorry, I couldn't respond.)";
  } catch (error) {
    console.error("Gemini API Error:", error);
    throw error;
  }
};

export const testConnection = async () => {
  const ai = getClient();
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: 'Assalamu Alaikum',
    });
    return !!response.text;
  } catch (error) {
    return false;
  }
};

