import React, { useState, useEffect, useRef } from 'react';
import Layout from './components/Layout';
import { sendFaraidMessage, testConnection } from './services/geminiService';
import { Message, ConnectionStatus, EstateInfo, Heir, AppStep, HeirType } from './types';

const App: React.FC = () => {
  const [step, setStep] = useState<AppStep>(AppStep.ESTATE);
  const [messages, setMessages] = useState<Message[]>([]);
  const [input, setInput] = useState('');
  const [status, setStatus] = useState<ConnectionStatus>(ConnectionStatus.IDLE);

  // Faraid Specific State
  const [estate, setEstate] = useState<EstateInfo>({
    totalAssets: 0,
    funeralExpenses: 0,
    debts: 0,
    willAmount: 0,
  });
  const [deceasedGender, setDeceasedGender] = useState<'Male' | 'Female' | null>(null);
  const [heirs, setHeirs] = useState<Heir[]>([]);

  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const init = async () => {
      setStatus(ConnectionStatus.CONNECTING);
      const isConnected = await testConnection();
      setStatus(isConnected ? ConnectionStatus.CONNECTED : ConnectionStatus.ERROR);

      // Initial System Message
      const welcomeMsg: Message = {
        id: 'welcome',
        role: 'model',
        text: `Assalamu Alaikum wa Rahmatullah! 👋\n\nWelcome to the Islamic Inheritance Assistant (Faraid Malayalam).\nഇത് ഒരു ഇസ്ലാമിക് ശരീഅത്ത് അടിസ്ഥാനമാക്കിയുള്ള അവകാശവകാ സഹായിയാണ്.\n\nനമുക്ക് തുടങ്ങാം! ആദ്യം ആസ്തി വിവരങ്ങൾ (Estate Information) രേഖപ്പെടുത്താം.`,
        timestamp: new Date(),
      };
      setMessages([welcomeMsg]);
    };
    init();
  }, []);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [messages]);

  const handleChat = async () => {
    if (!input.trim()) return;
    const userMsg: Message = { id: Date.now().toString(), role: 'user', text: input, timestamp: new Date() };
    setMessages(prev => [...prev, userMsg]);
    setInput('');

    try {
      const context = `Current Step: ${step}. Estate: ${JSON.stringify(estate)}. Deceased: ${deceasedGender}. Heirs: ${JSON.stringify(heirs)}`;
      const response = await sendFaraidMessage(input, context);
      const modelMsg: Message = { id: (Date.now() + 1).toString(), role: 'model', text: response, timestamp: new Date() };
      setMessages(prev => [...prev, modelMsg]);
    } catch (err) {
      setMessages(prev => [...prev, { id: 'err', role: 'model', text: "Error connecting to AI.", timestamp: new Date() }]);
    }
  };

  const addHeir = (type: HeirType) => {
    setHeirs(prev => {
      const existing = prev.find(h => h.type === type);
      if (existing) {
        return prev.map(h => h.type === type ? { ...h, count: h.count + 1 } : h);
      }
      return [...prev, { id: Date.now().toString(), type, count: 1 }];
    });
  };

  const removeHeir = (id: string) => {
    setHeirs(prev => prev.filter(h => h.id !== id));
  };

  const netEstate = estate.totalAssets - estate.funeralExpenses - estate.debts - estate.willAmount;

  const stepNumbers = { [AppStep.ESTATE]: '1', [AppStep.DECEASED_INFO]: '2', [AppStep.HEIRS]: '3', [AppStep.SUMMARY]: '4' };

  const sidebarContent = (
    <div className="space-y-8">
      <div>
        <h3 className="text-xs font-semibold text-emerald-500/60 uppercase tracking-widest mb-4 malayalam">നിലവിലെ വിവരങ്ങൾ</h3>
        <div className="space-y-3">
          <div className="p-4 bg-emerald-950/30 rounded-xl border border-emerald-900/20 backdrop-blur-sm">
            <p className="text-[10px] text-slate-500 uppercase font-bold mb-1">Net Estate (മിച്ചം ഉള്ളത്)</p>
            <p className="text-xl font-bold text-emerald-400">₹{netEstate.toLocaleString()}</p>
          </div>
          {deceasedGender && (
            <div className="p-3 bg-slate-900/50 rounded-lg border border-slate-800">
              <p className="text-xs text-slate-500 malayalam">മരണപ്പെട്ട വ്യക്തി</p>
              <p className="text-sm font-medium">{deceasedGender === 'Male' ? 'പുരുഷൻ (Male)' : 'സ്ത്രീ (Female)'}</p>
            </div>
          )}
        </div>
      </div>

      <div>
        <h3 className="text-xs font-semibold text-emerald-500/60 uppercase tracking-widest mb-4 malayalam">അവകാശികൾ ({heirs.reduce((acc, h) => acc + h.count, 0)})</h3>
        <div className="space-y-2">
          {heirs.length === 0 ? (
            <p className="text-xs text-slate-600 italic">അവകാശികളെ ചേർത്തിട്ടില്ല</p>
          ) : (
            heirs.map(h => (
              <div key={h.id} className="flex justify-between items-center p-2 bg-slate-800/30 rounded border border-slate-800/50">
                <span className="text-xs">{h.type} {h.count > 1 && `(x${h.count})`}</span>
                <button onClick={() => removeHeir(h.id)} className="text-red-400/50 hover:text-red-400">
                  <svg className="w-3 h-3" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path d="M6 18L18 6M6 6l12 12" /></svg>
                </button>
              </div>
            ))
          )}
        </div>
      </div>
    </div>
  );

  return (
    <Layout sidebarContent={sidebarContent} currentStep={stepNumbers[step]}>
      <div className="space-y-10 animate-in fade-in duration-500">

        {/* Step 1: Estate Info */}
        {step === AppStep.ESTATE && (
          <div className="space-y-6">
            <div className="border-l-4 border-emerald-500 pl-4">
              <h2 className="text-2xl font-bold malayalam">Step 1: ആസ്തി വിവരങ്ങൾ</h2>
              <p className="text-slate-400 text-sm">Enter the financial details of the deceased's estate.</p>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-6 bg-slate-900/40 p-6 rounded-2xl border border-slate-800/50">
              <div className="space-y-2">
                <label className="text-xs font-bold text-slate-500 uppercase malayalam">മൊത്തം ആസ്തി (Total Assets)</label>
                <input 
                  type="number" 
                  value={estate.totalAssets || ''} 
                  onChange={e => setEstate({...estate, totalAssets: Number(e.target.value)})}
                  className="w-full bg-slate-950 border border-slate-800 rounded-xl p-3 focus:border-emerald-500 focus:ring-1 focus:ring-emerald-500 transition-all"
                  placeholder="0"
                />
              </div>
              <div className="space-y-2">
                <label className="text-xs font-bold text-slate-500 uppercase malayalam">സംസ്കാര ചിലവ് (Funeral)</label>
                <input 
                  type="number" 
                  value={estate.funeralExpenses || ''} 
                  onChange={e => setEstate({...estate, funeralExpenses: Number(e.target.value)})}
                  className="w-full bg-slate-950 border border-slate-800 rounded-xl p-3 focus:border-emerald-500 focus:ring-1 focus:ring-emerald-500 transition-all"
                  placeholder="0"
                />
              </div>
              <div className="space-y-2">
                <label className="text-xs font-bold text-slate-500 uppercase malayalam">കടങ്ങൾ (Debts)</label>
                <input 
                  type="number" 
                  value={estate.debts || ''} 
                  onChange={e => setEstate({...estate, debts: Number(e.target.value)})}
                  className="w-full bg-slate-950 border border-slate-800 rounded-xl p-3 focus:border-emerald-500 focus:ring-1 focus:ring-emerald-500 transition-all"
                  placeholder="0"
                />
              </div>
              <div className="space-y-2">
                <label className="text-xs font-bold text-slate-500 uppercase malayalam">വസിയത്ത് (Will Amount ≤ 1/3)</label>
                <input 
                  type="number" 
                  value={estate.willAmount || ''} 
                  onChange={e => setEstate({...estate, willAmount: Number(e.target.value)})}
                  className="w-full bg-slate-950 border border-slate-800 rounded-xl p-3 focus:border-emerald-500 focus:ring-1 focus:ring-emerald-500 transition-all"
                  placeholder="0"
                />
              </div>
            </div>

            <div className="flex justify-end">
              <button 
                onClick={() => setStep(AppStep.DECEASED_INFO)}
                className="bg-emerald-600 hover:bg-emerald-500 text-white px-8 py-3 rounded-xl font-bold transition-all shadow-lg shadow-emerald-900/20 malayalam"
              >
                അടുത്ത ഘട്ടം (Next Step) →
              </button>
            </div>
          </div>
        )}

        {/* Step 2: Deceased Info */}
        {step === AppStep.DECEASED_INFO && (
          <div className="space-y-6 animate-in slide-in-from-right-4 duration-500">
            <div className="border-l-4 border-emerald-500 pl-4">
              <h2 className="text-2xl font-bold malayalam">Step 2: മരണപ്പെട്ട വ്യക്തിയുടെ വിവരങ്ങൾ</h2>
              <p className="text-slate-400 text-sm">Select the gender of the deceased person.</p>
            </div>

            <div className="grid grid-cols-2 gap-6">
              <button 
                onClick={() => setDeceasedGender('Male')}
                className={`p-8 rounded-2xl border-2 transition-all flex flex-col items-center gap-4 ${deceasedGender === 'Male' ? 'bg-emerald-600/20 border-emerald-500' : 'bg-slate-900/50 border-slate-800 hover:border-slate-700'}`}
              >
                <div className="w-16 h-16 rounded-full bg-blue-500/20 flex items-center justify-center text-blue-400">
                   <svg className="w-8 h-8" fill="currentColor" viewBox="0 0 24 24"><path d="M12 2C6.48 2 2 6.48 2 12s4.48 10 10 10 10-4.48 10-10S17.52 2 12 2zm0 3c1.66 0 3 1.34 3 3s-1.34 3-3 3-3-1.34-3-3 1.34-3 3-3zm0 14.2c-2.5 0-4.71-1.28-6-3.22.03-1.99 4-3.08 6-3.08s5.97 1.09 6 3.08c-1.29 1.94-3.5 3.22-6 3.22z" /></svg>
                </div>
                <span className="font-bold malayalam">പുരുഷൻ (Male)</span>
              </button>
              <button 
                onClick={() => setDeceasedGender('Female')}
                className={`p-8 rounded-2xl border-2 transition-all flex flex-col items-center gap-4 ${deceasedGender === 'Female' ? 'bg-emerald-600/20 border-emerald-500' : 'bg-slate-900/50 border-slate-800 hover:border-slate-700'}`}
              >
                <div className="w-16 h-16 rounded-full bg-pink-500/20 flex items-center justify-center text-pink-400">
                   <svg className="w-8 h-8" fill="currentColor" viewBox="0 0 24 24"><path d="M12 2C6.48 2 2 6.48 2 12s4.48 10 10 10 10-4.48 10-10S17.52 2 12 2zm0 3c1.66 0 3 1.34 3 3s-1.34 3-3 3-3-1.34-3-3 1.34-3 3-3zm0 14.2c-2.5 0-4.71-1.28-6-3.22.03-1.99 4-3.08 6-3.08s5.97 1.09 6 3.08c-1.29 1.94-3.5 3.22-6 3.22z" /></svg>
                </div>
                <span className="font-bold malayalam">സ്ത്രീ (Female)</span>
              </button>
            </div>

            <div className="flex justify-between pt-6">
               <button onClick={() => setStep(AppStep.ESTATE)} className="text-slate-400 hover:text-white malayalam">← പുറകോട്ട്</button>
               <button 
                disabled={!deceasedGender}
                onClick={() => setStep(AppStep.HEIRS)}
                className="bg-emerald-600 hover:bg-emerald-500 disabled:opacity-50 text-white px-8 py-3 rounded-xl font-bold transition-all malayalam"
              >
                അടുത്ത ഘട്ടം (Next Step) →
              </button>
            </div>
          </div>
        )}

        {/* Step 3: Heirs */}
        {step === AppStep.HEIRS && (
          <div className="space-y-6 animate-in slide-in-from-right-4 duration-500">
            <div className="border-l-4 border-emerald-500 pl-4">
              <h2 className="text-2xl font-bold malayalam">Step 3: അവകാശികൾ (Heirs)</h2>
              <p className="text-slate-400 text-sm">Select the surviving relatives of the deceased.</p>
            </div>

            <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 gap-3 bg-slate-900/20 p-4 rounded-2xl border border-slate-800/30">
              {(['Spouse', 'Father', 'Mother', 'Son', 'Daughter', 'FullBrother', 'FullSister', 'ConsanguineBrother', 'Nephew'] as HeirType[]).map(type => (
                <button 
                  key={type}
                  onClick={() => addHeir(type)}
                  className="p-3 bg-slate-900 border border-slate-800 hover:border-emerald-500/50 hover:bg-emerald-950/20 rounded-xl text-xs font-medium text-slate-300 transition-all text-center"
                >
                  + {type}
                </button>
              ))}
            </div>

            <div className="bg-slate-900/40 p-6 rounded-2xl border border-slate-800/50">
              <h4 className="text-sm font-bold text-slate-500 mb-4 uppercase malayalam">ചേർക്കപ്പെട്ടവർ (Selected)</h4>
              <div className="flex flex-wrap gap-3">
                {heirs.length === 0 ? (
                   <p className="text-sm text-slate-600 italic malayalam">ലിസ്റ്റ് ശൂന്യമാണ്</p>
                ) : (
                  heirs.map(h => (
                    <div key={h.id} className="flex items-center gap-2 bg-emerald-900/20 border border-emerald-800/30 px-3 py-1.5 rounded-full">
                       <span className="text-xs font-bold text-emerald-400">{h.type}</span>
                       <span className="text-xs text-slate-400">x{h.count}</span>
                       <button onClick={() => removeHeir(h.id)} className="text-slate-500 hover:text-red-400">
                          <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path d="M6 18L18 6M6 6l12 12" /></svg>
                       </button>
                    </div>
                  ))
                )}
              </div>
            </div>

            <div className="flex justify-between pt-6">
               <button onClick={() => setStep(AppStep.DECEASED_INFO)} className="text-slate-400 hover:text-white malayalam">← പുറകോട്ട്</button>
               <button 
                onClick={() => setStep(AppStep.SUMMARY)}
                className="bg-emerald-600 hover:bg-emerald-500 text-white px-8 py-3 rounded-xl font-bold transition-all malayalam"
              >
                ഫിനിഷ് (Finish) →
              </button>
            </div>
          </div>
        )}

        {/* Step 4: Summary / Chat */}
        {step === AppStep.SUMMARY && (
           <div className="space-y-6 animate-in slide-in-from-bottom-4 duration-500">
             <div className="bg-emerald-600/10 border border-emerald-500/20 p-6 rounded-2xl flex items-center justify-between">
                <div>
                   <h3 className="text-xl font-bold malayalam text-emerald-400">ഡാറ്റാ കളക്ഷൻ പൂർത്തിയായി!</h3>
                   <p className="text-sm text-slate-400">You can now discuss the shares with the AI Assistant.</p>
                </div>
                <button onClick={() => setStep(AppStep.ESTATE)} className="text-xs text-emerald-500 font-bold border border-emerald-500/30 px-3 py-1 rounded-lg hover:bg-emerald-500/10 malayalam">എഡിറ്റ് ചെയ്യൂ (Edit)</button>
             </div>

             <div ref={scrollRef} className="h-[400px] overflow-y-auto space-y-4 pr-2 custom-scrollbar">
                {messages.map((msg, i) => (
                  <div key={i} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}>
                     <div className={`max-w-[85%] p-4 rounded-2xl ${msg.role === 'user' ? 'bg-emerald-600 text-white rounded-tr-none' : 'bg-slate-900 border border-slate-800 text-slate-200 rounded-tl-none'}`}>
                        <p className="text-sm leading-relaxed whitespace-pre-wrap malayalam">{msg.text}</p>
                     </div>
                  </div>
                ))}
             </div>

             <div className="relative">
                <textarea 
                  value={input}
                  onChange={e => setInput(e.target.value)}
                  onKeyDown={e => e.key === 'Enter' && !e.shiftKey && (e.preventDefault(), handleChat())}
                  placeholder="അവകാശങ്ങളെ കുറിച്ച് ചോദിക്കൂ (Ask about shares...)"
                  className="w-full bg-slate-900 border border-slate-800 rounded-2xl py-4 pl-4 pr-16 focus:outline-none focus:ring-1 focus:ring-emerald-500 transition-all min-h-[60px] max-h-[150px] resize-none"
                  rows={1}
                />
                <button 
                  onClick={handleChat}
                  className="absolute right-3 bottom-3 p-2 bg-emerald-600 text-white rounded-xl shadow-lg hover:bg-emerald-500 transition-all"
                >
                   <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 19l9 2-9-18-9 18 9-2zm0 0v-8" /></svg>
                </button>
             </div>
           </div>
        )}
      </div>
    </Layout>
  );
};

export default App;

export enum ConnectionStatus {
  IDLE = 'IDLE',
  CONNECTING = 'CONNECTING',
  CONNECTED = 'CONNECTED',
  ERROR = 'ERROR'
}

export interface Message {
  id: string;
  role: 'user' | 'model';
  text: string;
  timestamp: Date;
}

export interface EstateInfo {
  totalAssets: number;
  funeralExpenses: number;
  debts: number;
  willAmount: number;
}

export type HeirType = 
  | 'Husband'
  | 'Wife'
  | 'Father' 
  | 'Mother' 
  | 'Son' 
  | 'Daughter' 
  | 'Grandson' 
  | 'Granddaughter' 
  | 'PaternalGrandfather' 
  | 'MaternalGrandmother'
  | 'PaternalGrandmother'
  | 'FullBrother'
  | 'FullSister'
  | 'ConsanguineBrother'
  | 'ConsanguineSister'
  | 'UterineBrother'
  | 'UterineSister'
  | 'Nephew'
  | 'PaternalUncle';

export interface Heir {
  id: string;
  type: HeirType;
  count: number;
}

export enum AppStep {
  ESTATE = 'ESTATE',
  DECEASED_INFO = 'DECEASED_INFO',
  HEIRS = 'HEIRS',
  SUMMARY = 'SUMMARY'
}

import React, { useState, useEffect, useRef } from 'react';
import Layout from './components/Layout';
import { sendFaraidMessage, testConnection } from './services/geminiService';
import { Message, ConnectionStatus, EstateInfo, Heir, AppStep, HeirType } from './types';

const App: React.FC = () => {
  const [step, setStep] = useState<AppStep>(AppStep.ESTATE);
  const [messages, setMessages] = useState<Message[]>([]);
  const [input, setInput] = useState('');
  const [status, setStatus] = useState<ConnectionStatus>(ConnectionStatus.IDLE);

  const [estate, setEstate] = useState<EstateInfo>({
    totalAssets: 0,
    funeralExpenses: 0,
    debts: 0,
    willAmount: 0,
  });
  const [deceasedGender, setDeceasedGender] = useState<'Male' | 'Female' | null>(null);
  const [heirs, setHeirs] = useState<Heir[]>([]);

  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const init = async () => {
      setStatus(ConnectionStatus.CONNECTING);
      const isConnected = await testConnection();
      setStatus(isConnected ? ConnectionStatus.CONNECTED : ConnectionStatus.ERROR);

      const welcomeMsg: Message = {
        id: 'welcome',
        role: 'model',
        text: `Assalamu Alaikum wa Rahmatullah! 👋\n\nWelcome to the Islamic Inheritance Assistant (Faraid Malayalam).\nഇത് ഒരു ഇസ്ലാമിക് ശരീഅത്ത് അടിസ്ഥാനമാക്കിയുള്ള അവകാശവകാ സഹായിയാണ്.\n\nനമുക്ക് തുടങ്ങാം! ആദ്യം ആസ്തി വിവരങ്ങൾ (Estate Information) രേഖപ്പെടുത്താം.`,
        timestamp: new Date(),
      };
      setMessages([welcomeMsg]);
    };
    init();
  }, []);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [messages]);

  const handleChat = async () => {
    if (!input.trim()) return;
    const userMsg: Message = { id: Date.now().toString(), role: 'user', text: input, timestamp: new Date() };
    setMessages(prev => [...prev, userMsg]);
    setInput('');

    try {
      const context = `Current Step: ${step}. Estate: ${JSON.stringify(estate)}. Deceased: ${deceasedGender}. Heirs: ${JSON.stringify(heirs)}`;
      const response = await sendFaraidMessage(input, context);
      const modelMsg: Message = { id: (Date.now() + 1).toString(), role: 'model', text: response, timestamp: new Date() };
      setMessages(prev => [...prev, modelMsg]);
    } catch (err) {
      setMessages(prev => [...prev, { id: 'err', role: 'model', text: "Error connecting to AI.", timestamp: new Date() }]);
    }
  };

  const addHeir = (type: HeirType) => {
    setHeirs(prev => {
      const existing = prev.find(h => h.type === type);
      if (existing) {
        return prev.map(h => h.type === type ? { ...h, count: h.count + 1 } : h);
      }
      return [...prev, { id: Date.now().toString(), type, count: 1 }];
    });
  };

  const updateHeirCount = (id: string, delta: number) => {
    setHeirs(prev => prev.map(h => {
      if (h.id === id) {
        const newCount = Math.max(1, h.count + delta);
        return { ...h, count: newCount };
      }
      return h;
    }));
  };

  const removeHeir = (id: string) => {
    setHeirs(prev => prev.filter(h => h.id !== id));
  };

  const netEstate = estate.totalAssets - estate.funeralExpenses - estate.debts - estate.willAmount;
  const stepNumbers = { [AppStep.ESTATE]: '1', [AppStep.DECEASED_INFO]: '2', [AppStep.HEIRS]: '3', [AppStep.SUMMARY]: '4' };

  // Categories for Heirs
  const primaryHeirs: HeirType[] = deceasedGender === 'Male' 
    ? ['Wife', 'Father', 'Mother', 'Son', 'Daughter'] 
    : ['Husband', 'Father', 'Mother', 'Son', 'Daughter'];

  const secondaryHeirs: HeirType[] = [
    'PaternalGrandfather', 'MaternalGrandmother', 'PaternalGrandmother', 
    'FullBrother', 'FullSister', 'ConsanguineBrother', 'ConsanguineSister',
    'UterineBrother', 'UterineSister', 'Nephew', 'PaternalUncle'
  ];

  const sidebarContent = (
    <div className="space-y-8">
      <div>
        <h3 className="text-xs font-semibold text-emerald-500/60 uppercase tracking-widest mb-4 malayalam">നിലവിലെ വിവരങ്ങൾ</h3>
        <div className="space-y-3">
          <div className="p-4 bg-emerald-950/30 rounded-xl border border-emerald-900/20 backdrop-blur-sm">
            <p className="text-[10px] text-slate-500 uppercase font-bold mb-1">Net Estate (മിച്ചം ഉള്ളത്)</p>
            <p className="text-xl font-bold text-emerald-400">₹{netEstate.toLocaleString()}</p>
          </div>
          {deceasedGender && (
            <div className="p-3 bg-slate-900/50 rounded-lg border border-slate-800">
              <p className="text-xs text-slate-500 malayalam">മരണപ്പെട്ട വ്യക്തി</p>
              <p className="text-sm font-medium">{deceasedGender === 'Male' ? 'പുരുഷൻ (Male)' : 'സ്ത്രീ (Female)'}</p>
            </div>
          )}
        </div>
      </div>

      <div>
        <h3 className="text-xs font-semibold text-emerald-500/60 uppercase tracking-widest mb-4 malayalam">അവകാശികൾ ({heirs.reduce((acc, h) => acc + h.count, 0)})</h3>
        <div className="space-y-2">
          {heirs.length === 0 ? (
            <p className="text-xs text-slate-600 italic malayalam">അവകാശികളെ ചേർത്തിട്ടില്ല</p>
          ) : (
            heirs.map(h => (
              <div key={h.id} className="flex justify-between items-center p-2 bg-slate-800/30 rounded border border-slate-800/50 group">
                <span className="text-xs">{h.type} <span className="text-emerald-500 font-bold ml-1">x{h.count}</span></span>
                <button onClick={() => removeHeir(h.id)} className="text-red-400/50 hover:text-red-400 transition-colors">
                  <svg className="w-3 h-3" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path d="M6 18L18 6M6 6l12 12" /></svg>
                </button>
              </div>
            ))
          )}
        </div>
      </div>
    </div>
  );

  return (
    <Layout sidebarContent={sidebarContent} currentStep={stepNumbers[step]}>
      <div className="space-y-10 animate-in fade-in duration-500">

        {/* Step 1: Estate Info */}
        {step === AppStep.ESTATE && (
          <div className="space-y-6">
            <div className="border-l-4 border-emerald-500 pl-4">
              <h2 className="text-2xl font-bold malayalam">Step 1: ആസ്തി വിവരങ്ങൾ</h2>
              <p className="text-slate-400 text-sm">Enter the financial details of the deceased's estate.</p>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-6 bg-slate-900/40 p-6 rounded-2xl border border-slate-800/50">
              <div className="space-y-2">
                <label className="text-xs font-bold text-slate-500 uppercase malayalam">മൊത്തം ആസ്തി (Total Assets)</label>
                <input 
                  type="number" 
                  value={estate.totalAssets || ''} 
                  onChange={e => setEstate({...estate, totalAssets: Number(e.target.value)})}
                  className="w-full bg-slate-950 border border-slate-800 rounded-xl p-3 focus:border-emerald-500 focus:ring-1 focus:ring-emerald-500 transition-all"
                  placeholder="0"
                />
              </div>
              <div className="space-y-2">
                <label className="text-xs font-bold text-slate-500 uppercase malayalam">സംസ്കാര ചിലവ് (Funeral)</label>
                <input 
                  type="number" 
                  value={estate.funeralExpenses || ''} 
                  onChange={e => setEstate({...estate, funeralExpenses: Number(e.target.value)})}
                  className="w-full bg-slate-950 border border-slate-800 rounded-xl p-3 focus:border-emerald-500 focus:ring-1 focus:ring-emerald-500 transition-all"
                  placeholder="0"
                />
              </div>
              <div className="space-y-2">
                <label className="text-xs font-bold text-slate-500 uppercase malayalam">കടങ്ങൾ (Debts)</label>
                <input 
                  type="number" 
                  value={estate.debts || ''} 
                  onChange={e => setEstate({...estate, debts: Number(e.target.value)})}
                  className="w-full bg-slate-950 border border-slate-800 rounded-xl p-3 focus:border-emerald-500 focus:ring-1 focus:ring-emerald-500 transition-all"
                  placeholder="0"
                />
              </div>
              <div className="space-y-2">
                <label className="text-xs font-bold text-slate-500 uppercase malayalam">വസിയത്ത് (Will Amount ≤ 1/3)</label>
                <input 
                  type="number" 
                  value={estate.willAmount || ''} 
                  onChange={e => setEstate({...estate, willAmount: Number(e.target.value)})}
                  className="w-full bg-slate-950 border border-slate-800 rounded-xl p-3 focus:border-emerald-500 focus:ring-1 focus:ring-emerald-500 transition-all"
                  placeholder="0"
                />
              </div>
            </div>

            <div className="flex justify-end">
              <button 
                onClick={() => setStep(AppStep.DECEASED_INFO)}
                className="bg-emerald-600 hover:bg-emerald-500 text-white px-8 py-3 rounded-xl font-bold transition-all shadow-lg shadow-emerald-900/20 malayalam"
              >
                അടുത്ത ഘട്ടം (Next Step) →
              </button>
            </div>
          </div>
        )}

        {/* Step 2: Deceased Info */}
        {step === AppStep.DECEASED_INFO && (
          <div className="space-y-6 animate-in slide-in-from-right-4 duration-500">
            <div className="border-l-4 border-emerald-500 pl-4">
              <h2 className="text-2xl font-bold malayalam">Step 2: മരണപ്പെട്ട വ്യക്തിയുടെ വിവരങ്ങൾ</h2>
              <p className="text-slate-400 text-sm">Select the gender of the deceased person.</p>
            </div>

            <div className="grid grid-cols-2 gap-6">
              <button 
                onClick={() => setDeceasedGender('Male')}
                className={`p-8 rounded-2xl border-2 transition-all flex flex-col items-center gap-4 ${deceasedGender === 'Male' ? 'bg-emerald-600/20 border-emerald-500' : 'bg-slate-900/50 border-slate-800 hover:border-slate-700'}`}
              >
                <div className="w-16 h-16 rounded-full bg-blue-500/20 flex items-center justify-center text-blue-400">
                   <svg className="w-8 h-8" fill="currentColor" viewBox="0 0 24 24"><path d="M12 2C6.48 2 2 6.48 2 12s4.48 10 10 10 10-4.48 10-10S17.52 2 12 2zm0 3c1.66 0 3 1.34 3 3s-1.34 3-3 3-3-1.34-3-3 1.34-3 3-3zm0 14.2c-2.5 0-4.71-1.28-6-3.22.03-1.99 4-3.08 6-3.08s5.97 1.09 6 3.08c-1.29 1.94-3.5 3.22-6 3.22z" /></svg>
                </div>
                <span className="font-bold malayalam">പുരുഷൻ (Male)</span>
              </button>
              <button 
                onClick={() => setDeceasedGender('Female')}
                className={`p-8 rounded-2xl border-2 transition-all flex flex-col items-center gap-4 ${deceasedGender === 'Female' ? 'bg-emerald-600/20 border-emerald-500' : 'bg-slate-900/50 border-slate-800 hover:border-slate-700'}`}
              >
                <div className="w-16 h-16 rounded-full bg-pink-500/20 flex items-center justify-center text-pink-400">
                   <svg className="w-8 h-8" fill="currentColor" viewBox="0 0 24 24"><path d="M12 2C6.48 2 2 6.48 2 12s4.48 10 10 10 10-4.48 10-10S17.52 2 12 2zm0 3c1.66 0 3 1.34 3 3s-1.34 3-3 3-3-1.34-3-3 1.34-3 3-3zm0 14.2c-2.5 0-4.71-1.28-6-3.22.03-1.99 4-3.08 6-3.08s5.97 1.09 6 3.08c-1.29 1.94-3.5 3.22-6 3.22z" /></svg>
                </div>
                <span className="font-bold malayalam">സ്ത്രീ (Female)</span>
              </button>
            </div>

            <div className="flex justify-between pt-6">
               <button onClick={() => setStep(AppStep.ESTATE)} className="text-slate-400 hover:text-white malayalam">← പുറകോട്ട്</button>
               <button 
                disabled={!deceasedGender}
                onClick={() => setStep(AppStep.HEIRS)}
                className="bg-emerald-600 hover:bg-emerald-500 disabled:opacity-50 text-white px-8 py-3 rounded-xl font-bold transition-all malayalam"
              >
                അടുത്ത ഘട്ടം (Next Step) →
              </button>
            </div>
          </div>
        )}

        {/* Step 3: Heirs */}
        {step === AppStep.HEIRS && (
          <div className="space-y-6 animate-in slide-in-from-right-4 duration-500">
            <div className="border-l-4 border-emerald-500 pl-4">
              <h2 className="text-2xl font-bold malayalam">Step 3: അവകാശികൾ (Heirs)</h2>
              <p className="text-slate-400 text-sm">Select the surviving relatives of the deceased at the time of death.</p>
            </div>

            <div className="bg-emerald-600/5 border border-emerald-500/20 p-4 rounded-xl space-y-2">
              <h4 className="text-xs font-bold text-emerald-400 uppercase tracking-widest malayalam">📌 നിയമങ്ങൾ (Rules):</h4>
              <ul className="text-xs text-slate-400 space-y-1 malayalam">
                <li>• മരിക്കുന്ന സമയത്ത് ജീവിച്ചിരിക്കുന്നവർ മാത്രം.</li>
                <li>• ഗർഭസ്ഥ ശിശുക്കളെ ഇപ്പോൾ ചേർക്കേണ്ടതില്ല.</li>
                <li>• ഓരോരുത്തരുടേയും എണ്ണം (Count) രേഖപ്പെടുത്തുക.</li>
              </ul>
            </div>

            <div className="space-y-8">
              {/* Primary Heirs Section */}
              <div>
                <h3 className="text-sm font-bold text-slate-500 mb-4 uppercase malayalam border-b border-slate-800 pb-2">👤 പ്രധാന ബന്ധുക്കൾ (Primary)</h3>
                <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 gap-3">
                  {primaryHeirs.map(type => (
                    <button 
                      key={type}
                      onClick={() => addHeir(type)}
                      className="p-3 bg-slate-900 border border-slate-800 hover:border-emerald-500/50 hover:bg-emerald-950/20 rounded-xl text-xs font-medium text-slate-300 transition-all text-center flex flex-col items-center gap-1"
                    >
                      <span className="text-emerald-500 text-lg">+</span>
                      <span>{type}</span>
                    </button>
                  ))}
                </div>
              </div>

              {/* Other Heirs Section */}
              <div>
                <h3 className="text-sm font-bold text-slate-500 mb-4 uppercase malayalam border-b border-slate-800 pb-2">👥 മറ്റ് ബന്ധുക്കൾ (Others)</h3>
                <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 gap-3">
                  {secondaryHeirs.map(type => (
                    <button 
                      key={type}
                      onClick={() => addHeir(type)}
                      className="p-3 bg-slate-900/50 border border-slate-800/50 hover:border-emerald-500/50 hover:bg-emerald-950/20 rounded-xl text-xs font-medium text-slate-400 transition-all text-center flex flex-col items-center gap-1"
                    >
                      <span className="text-emerald-500/50 text-lg">+</span>
                      <span>{type}</span>
                    </button>
                  ))}
                </div>
              </div>
            </div>

            {/* Selected Heirs with Count Controls */}
            {heirs.length > 0 && (
              <div className="bg-slate-900/40 p-6 rounded-2xl border border-slate-800/50 space-y-4">
                <h4 className="text-sm font-bold text-slate-500 uppercase malayalam">ചേർക്കപ്പെട്ടവർ (Selected List)</h4>
                <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
                  {heirs.map(h => (
                    <div key={h.id} className="flex items-center justify-between bg-emerald-950/20 border border-emerald-800/30 px-4 py-3 rounded-xl">
                       <div className="flex flex-col">
                         <span className="text-xs font-bold text-emerald-400">{h.type}</span>
                       </div>
                       <div className="flex items-center gap-3">
                         <button 
                           onClick={() => updateHeirCount(h.id, -1)}
                           className="w-6 h-6 rounded bg-slate-800 flex items-center justify-center hover:bg-slate-700 transition-colors"
                         >-</button>
                         <span className="text-sm font-bold w-4 text-center">{h.count}</span>
                         <button 
                           onClick={() => updateHeirCount(h.id, 1)}
                           className="w-6 h-6 rounded bg-slate-800 flex items-center justify-center hover:bg-slate-700 transition-colors"
                         >+</button>
                         <button onClick={() => removeHeir(h.id)} className="ml-2 text-slate-500 hover:text-red-400 transition-colors">
                            <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" /></svg>
                         </button>
                       </div>
                    </div>
                  ))}
                </div>
              </div>
            )}

            <div className="flex justify-between pt-6">
               <button onClick={() => setStep(AppStep.DECEASED_INFO)} className="text-slate-400 hover:text-white malayalam">← പുറകോട്ട്</button>
               <button 
                onClick={() => setStep(AppStep.SUMMARY)}
                className="bg-emerald-600 hover:bg-emerald-500 text-white px-8 py-3 rounded-xl font-bold transition-all shadow-xl shadow-emerald-900/20 malayalam"
              >
                ഫിനിഷ് (Finish) →
              </button>
            </div>
          </div>
        )}

        {/* Step 4: Summary / Chat */}
        {step === AppStep.SUMMARY && (
           <div className="space-y-6 animate-in slide-in-from-bottom-4 duration-500">
             <div className="bg-emerald-600/10 border border-emerald-500/20 p-6 rounded-2xl flex items-center justify-between">
                <div>
                   <h3 className="text-xl font-bold malayalam text-emerald-400">ഡാറ്റാ കളക്ഷൻ പൂർത്തിയായി!</h3>
                   <p className="text-sm text-slate-400">You can now discuss the shares with the AI Assistant.</p>
