                <button onClick={() => setStep(AppStep.ESTATE)} className="text-xs text-emerald-500 font-bold border border-emerald-500/30 px-4 py-2 rounded-lg hover:bg-emerald-500/10 transition-colors malayalam">എഡിറ്റ് ചെയ്യൂ (Edit)</button>
             </div>

             <div className="bg-slate-900/40 border border-slate-800/50 p-6 rounded-2xl space-y-4">
               <h4 className="text-sm font-bold text-slate-500 uppercase malayalam">Summary of Information:</h4>
               <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
                  <div className="p-3 bg-slate-950 rounded-lg border border-slate-800">
                    <p className="text-[10px] text-slate-500 uppercase">Net Estate</p>
                    <p className="text-sm font-bold text-emerald-400">₹{netEstate.toLocaleString()}</p>
                  </div>
                  <div className="p-3 bg-slate-950 rounded-lg border border-slate-800">
                    <p className="text-[10px] text-slate-500 uppercase">Gender</p>
                    <p className="text-sm font-bold">{deceasedGender}</p>
                  </div>
                  <div className="p-3 bg-slate-950 rounded-lg border border-slate-800">
                    <p className="text-[10px] text-slate-500 uppercase">Total Heirs</p>
                    <p className="text-sm font-bold">{heirs.reduce((acc, h) => acc + h.count, 0)}</p>
                  </div>
               </div>
             </div>

             <div ref={scrollRef} className="h-[400px] overflow-y-auto space-y-4 pr-2 custom-scrollbar">
                {messages.map((msg, i) => (
                  <div key={i} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}>
                     <div className={`max-w-[85%] p-4 rounded-2xl ${msg.role === 'user' ? 'bg-emerald-600 text-white rounded-tr-none' : 'bg-slate-900 border border-slate-800 text-slate-200 rounded-tl-none shadow-sm'}`}>
                        <p className="text-sm leading-relaxed whitespace-pre-wrap malayalam">{msg.text}</p>
                     </div>
                  </div>
                ))}
             </div>

             <div className="relative">
                <textarea 
                  value={input}
                  onChange={e => setInput(e.target.value)}
                  onKeyDown={e => e.key === 'Enter' && !e.shiftKey && (e.preventDefault(), handleChat())}
                  placeholder="അവകാശങ്ങളെ കുറിച്ച് ചോദിക്കൂ (Ask about shares...)"
                  className="w-full bg-slate-900 border border-slate-800 rounded-2xl py-4 pl-4 pr-16 focus:outline-none focus:ring-1 focus:ring-emerald-500 transition-all min-h-[60px] max-h-[150px] resize-none shadow-inner"
                  rows={1}
                />
                <button 
                  onClick={handleChat}
                  className="absolute right-3 bottom-3 p-2 bg-emerald-600 text-white rounded-xl shadow-lg hover:bg-emerald-500 transition-all active:scale-95"
                >
                   <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 19l9 2-9-18-9 18 9-2zm0 0v-8" /></svg>
                </button>
             </div>
           </div>
        )}
      </div>
    </Layout>
  );
};

