  | 'Husband'
  | 'Wife'
  | 'Father' 
  | 'Mother' 
  | 'Son' 
  | 'Daughter' 
  | 'Grandson' 
  | 'Granddaughter' 
  | 'PaternalGrandfather' 
  | 'MaternalGrandmother'
  | 'PaternalGrandmother'
  | 'FullBrother'
  | 'FullSister'
  | 'ConsanguineBrother'
  | 'ConsanguineSister'
  | 'UterineBrother'
  | 'UterineSister'
  | 'Nephew'
  | 'PaternalUncle';

