import React, { useState, useEffect, useRef } from 'react';
import Layout from './components/Layout';
import { sendFaraidMessage, testConnection } from './services/geminiService';
import { Message, ConnectionStatus, EstateInfo, Heir, AppStep, HeirType, ViewMode, KnowledgePage } from './types';

const App: React.FC = () => {
  const [viewMode, setViewMode] = useState<ViewMode>('calculator');
  const [knowledgePage, setKnowledgePage] = useState<KnowledgePage>(KnowledgePage.WELCOME);
  const [step, setStep] = useState<AppStep>(AppStep.ESTATE);
  const [messages, setMessages] = useState<Message[]>([]);
  const [input, setInput] = useState('');
  const [status, setStatus] = useState<ConnectionStatus>(ConnectionStatus.IDLE);

  const [estate, setEstate] = useState<EstateInfo>({
    totalAssets: 0,
    funeralExpenses: 0,
    debts: 0,
    willAmount: 0,
  });
  const [deceasedGender, setDeceasedGender] = useState<'Male' | 'Female' | null>(null);
  const [heirs, setHeirs] = useState<Heir[]>([]);

  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const init = async () => {
      setStatus(ConnectionStatus.CONNECTING);
      const isConnected = await testConnection();
      setStatus(isConnected ? ConnectionStatus.CONNECTED : ConnectionStatus.ERROR);

      const welcomeMsg: Message = {
        id: 'welcome',
        role: 'model',
        text: `Assalamu Alaikum wa Rahmatullah! 👋\n\nWelcome to the Islamic Inheritance Assistant (Faraid Malayalam).\nഇത് ഒരു ഇസ്ലാമിക് ശരീഅത്ത് അടിസ്ഥാനമാക്കിയുള്ള അവകാശവകാ സഹായിയാണ്.\n\nനമുക്ക് തുടങ്ങാം! ആദ്യം ആസ്തി വിവരങ്ങൾ (Estate Information) രേഖപ്പെടുത്താം.`,
        timestamp: new Date(),
      };
      setMessages([welcomeMsg]);
    };
    init();
  }, []);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [messages, viewMode]);

  const handleChat = async () => {
    if (!input.trim()) return;
    const userMsg: Message = { id: Date.now().toString(), role: 'user', text: input, timestamp: new Date() };
    setMessages(prev => [...prev, userMsg]);
    setInput('');

    try {
      const context = `Current Step: ${step}. Estate: ${JSON.stringify(estate)}. Deceased: ${deceasedGender}. Heirs: ${JSON.stringify(heirs)}`;
      const response = await sendFaraidMessage(input, context);
      const modelMsg: Message = { id: (Date.now() + 1).toString(), role: 'model', text: response, timestamp: new Date() };
      setMessages(prev => [...prev, modelMsg]);
    } catch (err) {
      setMessages(prev => [...prev, { id: 'err', role: 'model', text: "Error connecting to AI.", timestamp: new Date() }]);
    }
  };

  const addHeir = (type: HeirType) => {
    setHeirs(prev => {
      const existing = prev.find(h => h.type === type);
      if (existing) {
        return prev.map(h => h.type === type ? { ...h, count: h.count + 1 } : h);
      }
      return [...prev, { id: Date.now().toString(), type, count: 1 }];
    });
  };

  const updateHeirCount = (id: string, delta: number) => {
    setHeirs(prev => prev.map(h => {
      if (h.id === id) {
        const newCount = Math.max(1, h.count + delta);
        return { ...h, count: newCount };
      }
      return h;
    }));
  };

  const removeHeir = (id: string) => {
    setHeirs(prev => prev.filter(h => h.id !== id));
  };

  const netEstate = estate.totalAssets - estate.funeralExpenses - estate.debts - estate.willAmount;
  const stepNumbers = { [AppStep.ESTATE]: '1', [AppStep.DECEASED_INFO]: '2', [AppStep.HEIRS]: '3', [AppStep.SUMMARY]: '4' };

  const primaryHeirs: HeirType[] = deceasedGender === 'Male' 
    ? ['Wife', 'Father', 'Mother', 'Son', 'Daughter'] 
    : ['Husband', 'Father', 'Mother', 'Son', 'Daughter'];

  const secondaryHeirs: HeirType[] = [
    'PaternalGrandfather', 'MaternalGrandmother', 'PaternalGrandmother', 
    'FullBrother', 'FullSister', 'ConsanguineBrother', 'ConsanguineSister',
    'UterineBrother', 'UterineSister', 'Nephew', 'PaternalUncle'
  ];

  const sidebarContent = viewMode === 'calculator' ? (
    <div className="space-y-8">
      <div>
        <h3 className="text-xs font-bold text-gray-400 uppercase tracking-widest mb-4 malayalam">നിലവിലെ വിവരങ്ങൾ</h3>
        <div className="space-y-3">
          <div className="p-4 bg-emerald-50 rounded-xl border border-emerald-100">
            <p className="text-[10px] text-[#059669] uppercase font-bold mb-1">Net Estate (മിച്ചം ഉള്ളത്)</p>
            <p className="text-xl font-bold text-[#1F2937]">₹{netEstate.toLocaleString()}</p>
          </div>
          {deceasedGender && (
