                  <div>
                    <h3 className="text-sm font-bold text-[#D4AF37] mb-6 uppercase malayalam border-b border-gray-100 pb-3">👥 മറ്റ് ബന്ധുക്കൾ (Others)</h3>
                    <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 gap-4">
                      {secondaryHeirs.map(type => (
                        <button 
                          key={type}
                          onClick={() => addHeir(type)}
                          className="p-4 bg-white border border-gray-100 hover:border-[#059669] hover:bg-emerald-50 rounded-2xl text-xs font-medium text-gray-500 transition-all text-center flex flex-col items-center gap-2 shadow-sm"
