                    <h4 className="text-sm font-bold text-gray-400 uppercase malayalam">ചേർക്കപ്പെട്ടവർ (Selected List)</h4>
                    <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                      {heirs.map(h => (
                        <div key={h.id} className="flex items-center justify-between bg-gray-50 border border-gray-100 px-6 py-4 rounded-2xl">
                           <div className="flex flex-col">
                             <span className="text-xs font-bold text-gray-800">{h.type}</span>
                           </div>
                           <div className="flex items-center gap-3">
                             <button onClick={() => updateHeirCount(h.id, -1)} className="w-8 h-8 rounded-lg bg-white border border-gray-200 flex items-center justify-center hover:bg-emerald-50 hover:text-[#059669] transition-colors font-bold shadow-sm">-</button>
                             <span className="text-sm font-bold w-6 text-center text-[#1F2937]">{h.count}</span>
                             <button onClick={() => updateHeirCount(h.id, 1)} className="w-8 h-8 rounded-lg bg-white border border-gray-200 flex items-center justify-center hover:bg-emerald-50 hover:text-[#059669] transition-colors font-bold shadow-sm">+</button>
                             <button onClick={() => removeHeir(h.id)} className="ml-3 text-red-400 hover:text-red-600 transition-colors">
                                <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" /></svg>
                             </button>
                           </div>
                        </div>
                      ))}
                    </div>
                  </div>
                )}

                <div className="flex justify-between pt-6">
                   <button onClick={() => setStep(AppStep.DECEASED_INFO)} className="text-gray-400 hover:text-[#059669] font-medium malayalam">← പുറകോട്ട്</button>
                   <button 
                    onClick={() => setStep(AppStep.SUMMARY)}
                    className="bg-[#059669] hover:bg-[#047857] text-white px-10 py-4 rounded-xl font-bold transition-all shadow-lg malayalam"
                  >
                    ഫിനിഷ് (Finish) →
                  </button>
                </div>
              </div>
            )}

            {step === AppStep.SUMMARY && (
               <div className="space-y-6 animate-in slide-in-from-bottom-4 duration-500">
                 <div className="bg-emerald-50 border border-emerald-100 p-8 rounded-[2rem] flex items-center justify-between">
                    <div>
                       <h3 className="text-xl font-bold malayalam text-[#059669]">ഡാറ്റാ കളക്ഷൻ പൂർത്തിയായി!</h3>
                       <p className="text-sm text-gray-600">You can now discuss the shares with the AI Assistant.</p>
                    </div>
                    <button onClick={() => setStep(AppStep.ESTATE)} className="text-xs text-[#D4AF37] font-bold border border-[#D4AF37] px-5 py-2 rounded-xl hover:bg-[#D4AF37] hover:text-white transition-all malayalam">എഡിറ്റ് ചെയ്യൂ (Edit)</button>
                 </div>

                 <div className="bg-white border border-gray-100 p-8 rounded-[2rem] space-y-6 shadow-sm">
                   <h4 className="text-sm font-bold text-gray-400 uppercase malayalam">Summary of Information:</h4>
                   <div className="grid grid-cols-2 md:grid-cols-4 gap-6">
                      <div className="p-4 bg-gray-50 rounded-xl border border-gray-100">
                        <p className="text-[10px] text-gray-400 uppercase font-bold">Net Estate</p>
                        <p className="text-sm font-bold text-[#059669]">₹{netEstate.toLocaleString()}</p>
                      </div>
                      <div className="p-4 bg-gray-50 rounded-xl border border-gray-100">
                        <p className="text-[10px] text-gray-400 uppercase font-bold">Gender</p>
                        <p className="text-sm font-bold text-gray-800">{deceasedGender}</p>
                      </div>
                      <div className="p-4 bg-gray-50 rounded-xl border border-gray-100">
                        <p className="text-[10px] text-gray-400 uppercase font-bold">Total Heirs</p>
                        <p className="text-sm font-bold text-gray-800">{heirs.reduce((acc, h) => acc + h.count, 0)}</p>
                      </div>
                   </div>
                 </div>

                 <div ref={scrollRef} className="h-[400px] overflow-y-auto space-y-4 pr-3 custom-scrollbar bg-white p-6 rounded-[2rem] border border-gray-100 shadow-sm">
                    {messages.map((msg, i) => (
                      <div key={i} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}>
                         <div className={`max-w-[85%] p-5 rounded-2xl ${msg.role === 'user' ? 'bg-[#059669] text-white rounded-tr-none shadow-md' : 'bg-gray-50 border border-gray-100 text-[#1F2937] rounded-tl-none shadow-sm'}`}>
                            <p className="text-sm leading-relaxed whitespace-pre-wrap malayalam">{msg.text}</p>
                         </div>
                      </div>
                    ))}
                 </div>

                 <div className="relative group">
                    <textarea 
                      value={input}
                      onChange={e => setInput(e.target.value)}
                      onKeyDown={e => e.key === 'Enter' && !e.shiftKey && (e.preventDefault(), handleChat())}
                      placeholder="അവകാശങ്ങളെ കുറിച്ച് ചോദിക്കൂ (Ask about shares...)"
                      className="w-full bg-white border border-gray-200 rounded-[2rem] py-5 pl-6 pr-16 focus:outline-none focus:ring-1 focus:ring-[#059669] transition-all min-h-[70px] max-h-[150px] resize-none shadow-sm group-hover:shadow-md"
                      rows={1}
                    />
                    <button 
                      onClick={handleChat}
                      className="absolute right-4 bottom-4 p-3 bg-[#059669] text-white rounded-2xl shadow-lg hover:bg-[#047857] transition-all active:scale-95"
                    >
                       <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 19l9 2-9-18-9 18 9-2zm0 0v-8" /></svg>
                    </button>
                 </div>
               </div>
            )}
          </div>
        )}
      </div>
    </Layout>
  );
};

export default App;

import React, { useState, useEffect, useRef } from 'react';
import Layout from './components/Layout';
import { sendFaraidMessage, testConnection } from './services/geminiService';
import { Message, ConnectionStatus, EstateInfo, Heir, AppStep, HeirType, ViewMode } from './types';

const App: React.FC = () => {
  const [hasStarted, setHasStarted] = useState(false);
  const [onboardingPage, setOnboardingPage] = useState(1);
  const [viewMode, setViewMode] = useState<ViewMode>('calculator');
  const [step, setStep] = useState<AppStep>(AppStep.ESTATE);
  const [messages, setMessages] = useState<Message[]>([]);
  const [input, setInput] = useState('');
  const [status, setStatus] = useState<ConnectionStatus>(ConnectionStatus.IDLE);

  const [estate, setEstate] = useState<EstateInfo>({
    totalAssets: 0,
    funeralExpenses: 0,
    debts: 0,
    willAmount: 0,
  });
  const [deceasedGender, setDeceasedGender] = useState<'Male' | 'Female' | null>(null);
  const [heirs, setHeirs] = useState<Heir[]>([]);

  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const init = async () => {
      setStatus(ConnectionStatus.CONNECTING);
      const isConnected = await testConnection();
      setStatus(isConnected ? ConnectionStatus.CONNECTED : ConnectionStatus.ERROR);

      const welcomeMsg: Message = {
        id: 'welcome',
        role: 'model',
        text: `Assalamu Alaikum wa Rahmatullah! 👋\n\nWelcome to the Islamic Inheritance Assistant (Faraid Malayalam).\nഇത് ഒരു ഇസ്ലാമിക് ശരീഅത്ത് അടിസ്ഥാനമാക്കിയുള്ള അവകാശവകാ സഹായിയാണ്.\n\nനമുക്ക് തുടങ്ങാം! ആദ്യം ആസ്തി വിവരങ്ങൾ (Estate Information) രേഖപ്പെടുത്താം.`,
        timestamp: new Date(),
      };
      setMessages([welcomeMsg]);
    };
    init();
  }, []);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [messages, viewMode, hasStarted]);

  const handleChat = async () => {
    if (!input.trim()) return;
    const userMsg: Message = { id: Date.now().toString(), role: 'user', text: input, timestamp: new Date() };
    setMessages(prev => [...prev, userMsg]);
    setInput('');

    try {
      const context = `Current Step: ${step}. Estate: ${JSON.stringify(estate)}. Deceased: ${deceasedGender}. Heirs: ${JSON.stringify(heirs)}`;
      const response = await sendFaraidMessage(input, context);
      const modelMsg: Message = { id: (Date.now() + 1).toString(), role: 'model', text: response, timestamp: new Date() };
      setMessages(prev => [...prev, modelMsg]);
    } catch (err) {
      setMessages(prev => [...prev, { id: 'err', role: 'model', text: "Error connecting to AI.", timestamp: new Date() }]);
    }
  };

  const addHeir = (type: HeirType) => {
    setHeirs(prev => {
      const existing = prev.find(h => h.type === type);
      if (existing) {
        return prev.map(h => h.type === type ? { ...h, count: h.count + 1 } : h);
      }
      return [...prev, { id: Date.now().toString(), type, count: 1 }];
    });
  };

  const updateHeirCount = (id: string, delta: number) => {
    setHeirs(prev => prev.map(h => {
      if (h.id === id) {
        const newCount = Math.max(1, h.count + delta);
        return { ...h, count: newCount };
      }
      return h;
    }));
  };

  const removeHeir = (id: string) => {
    setHeirs(prev => prev.filter(h => h.id !== id));
  };

  const netEstate = estate.totalAssets - estate.funeralExpenses - estate.debts - estate.willAmount;
  const stepNumbers = { [AppStep.ESTATE]: '1', [AppStep.DECEASED_INFO]: '2', [AppStep.HEIRS]: '3', [AppStep.SUMMARY]: '4' };

  const primaryHeirs: HeirType[] = deceasedGender === 'Male' 
    ? ['Wife', 'Father', 'Mother', 'Son', 'Daughter'] 
    : ['Husband', 'Father', 'Mother', 'Son', 'Daughter'];

  const secondaryHeirs: HeirType[] = [
    'PaternalGrandfather', 'MaternalGrandmother', 'PaternalGrandmother', 
    'FullBrother', 'FullSister', 'ConsanguineBrother', 'ConsanguineSister',
    'UterineBrother', 'UterineSister', 'Nephew', 'PaternalUncle'
  ];

  if (!hasStarted) {
    const renderOnboardingPage = () => {
      switch (onboardingPage) {
        case 1:
          return (
            <div className="flex flex-col items-center justify-center h-full text-center space-y-8 animate-in fade-in zoom-in duration-700">
              <div className="w-24 h-24 bg-emerald-50 rounded-[2.5rem] flex items-center justify-center border border-emerald-100 shadow-sm">
                <svg className="w-12 h-12 text-[#059669]" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1.5} d="M19 21V5a2 2 0 00-2-2H7a2 2 0 00-2 2v16m14 0h2m-2 0h-5m-9 0H3m2 0h5M9 7h1m-1 4h1m4-4h1m-1 4h1m-5 10v-5a1 1 0 011-1h2a1 1 0 011 1v5m-4 0h4" />
                </svg>
              </div>
              <h1 className="text-4xl font-bold text-[#D4AF37] malayalam">സ്വാഗതം</h1>
              <p className="text-xl text-[#1F2937] leading-relaxed malayalam max-w-lg px-4">
                അസ്സലാമു അലൈക്കും. ഇസ്‌ലാമിക ശരീഅത്ത് നിയമപ്രകാരം അനന്തരാവകാശം എളുപ്പത്തിൽ കണക്കാക്കാൻ സഹായിക്കുന്ന ആപ്ലിക്കേഷനിലേക്ക് സ്വാഗതം.
              </p>
            </div>
          );
        case 2:
          return (
            <div className="flex flex-col items-center justify-center h-full text-center space-y-8 animate-in slide-in-from-right-8 duration-700">
              <div className="w-20 h-20 bg-emerald-50 rounded-full flex items-center justify-center border border-emerald-100">
                <svg className="w-10 h-10 text-[#059669]" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 5H7a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2V7a2 2 0 00-2-2h-2M9 5a2 2 0 002 2h2a2 2 0 002-2M9 5a2 2 0 012-2h2a2 2 0 012 2" />
                </svg>
              </div>
              <h2 className="text-2xl font-bold text-[#D4AF37] malayalam">അപ്ലിക്കേഷനെ കുറിച്ച്</h2>
              <p className="text-lg text-[#1F2937] leading-relaxed malayalam max-w-lg px-6">
                മരണപ്പെട്ട വ്യക്തിയുടെ ആകെ ആസ്തി, കടങ്ങൾ എന്നിവ രേഖപ്പെടുത്താനും അവകാശികളെ തിരഞ്ഞെടുക്കാനും വിശ്വസ്തതയോടും സുതാര്യതയോടും കൂടി ഈ ടൂൾ സഹായിക്കുന്നു.
              </p>
            </div>
          );
        case 3:
          return (
            <div className="flex flex-col items-center justify-center h-full text-center space-y-6 animate-in slide-in-from-right-8 duration-700 px-4">
              <h2 className="text-2xl font-bold text-[#D4AF37] malayalam">ഖുർആനിക തെളിവുകൾ</h2>
              <div className="w-full space-y-4 max-w-md">
                <div className="bg-emerald-50 p-6 rounded-2xl border border-emerald-100 shadow-sm">
                  <p className="text-xl font-serif text-[#059669] leading-loose text-right font-bold" dir="rtl">
                    يُوصِيكُمُ ٱللَّهُ فِيٓ أَوْلَـٰدِكُمْ...
                  </p>
                  <p className="text-[#1F2937] text-sm malayalam leading-relaxed mt-2">
