                    >
                       <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 19l9 2-9-18-9 18 9-2zm0 0v-8" /></svg>
                    </button>
                 </div>
               </div>
            )}
          </div>
        )}
      </div>
    </Layout>
  );
};

export default App;

import { GoogleGenAI, Type } from "@google/genai";

const getClient = () => {
  return new GoogleGenAI({ apiKey: process.env.API_KEY });
};

const COUNSELOR_SYSTEM_INSTRUCTION = `
You are the "Islamic Inheritance Assistant (Faraid Malayalam)" Counselor. 
Your goal is to guide the user through the process of listing assets and heirs for Islamic inheritance according to Shafi'i Fiqh (commonly followed in Kerala).
Respond in a mix of Malayalam and English (Manglish/Malayalam script) as appropriate for a Kerala audience.
Be respectful, compassionate, and precise with Islamic terminology (e.g., Faraid, Asaba, Zawil Furud).
Do not perform final mathematical calculations of shares yourself; instead, help the user ensure their data is correct.
If the user asks about a specific relative, explain their general eligibility.
Keep responses concise and supportive.
`;

const ENGINE_SYSTEM_INSTRUCTION = `
ROLE: Islamic Faraid (Inheritance) Knowledge Engine.
TASK: Calculate Islamic inheritance shares based on Quran and classical fiqh rules without giving fatwa.

INHERITANCE LOGIC RULES:
A. Husband: If children exist -> 1/4, Else -> 1/2
B. Wife/Wives: If children exist -> 1/8, Else -> 1/4 (collectively)
C. Father: If children exist -> 1/6 + residuary if no son, Else -> residuary
D. Mother: If children or 2+ siblings exist -> 1/6, Else -> 1/3
E. Grandfather: Present only if father absent. Same rules as father.
F. Grandmother: Present only if mother absent. Share = 1/6.
G. Sons & Daughters: If only daughters & no sons: 1 daughter -> 1/2, 2+ daughters -> 2/3 collectively. If sons exist -> residuary with ratio male = 2x female.
H. Maternal Siblings: If no ascendants or descendants: 1 sibling -> 1/6, 2+ siblings -> 1/3 collectively.
I. Full Siblings: Residuary if no son, no father. Male = 2x female.

EXCLUSION RULES (BLOCKING):
- Father present -> siblings & grandfather excluded
- Mother present -> maternal grandmother excluded
- Sons present -> siblings excluded
- Grandfather present -> paternal uncles excluded

SAFETY & BEHAVIOR:
- Never issue fatwa or say "Allah knows best".
- Never ask user to consult scholars.
- Only apply established faraid rules.
- Return "validation": "invalid" if rules are violated or unknown.
- Do not convert fractions to % unless asked.
- Output MUST be valid JSON.
`;

export const sendFaraidMessage = async (prompt: string, context?: string) => {
  const ai = getClient();
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: context ? `Context: ${context}\n\nUser: ${prompt}` : prompt,
      config: {
        systemInstruction: COUNSELOR_SYSTEM_INSTRUCTION,
      }
    });
    return response.text || "ക്ഷമിക്കണം, എനിക്ക് മറുപടി നൽകാൻ സാധിച്ചില്ല. (Sorry, I couldn't respond.)";
  } catch (error) {
    console.error("Gemini API Error:", error);
    throw error;
  }
};

export const calculateInheritance = async (input: any) => {
  const ai = getClient();
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-preview',
      contents: JSON.stringify(input),
      config: {
        systemInstruction: ENGINE_SYSTEM_INSTRUCTION,
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            eligible_heirs: { type: Type.ARRAY, items: { type: Type.STRING } },
            excluded_heirs: { type: Type.ARRAY, items: { type: Type.STRING } },
            shares: { 
              type: Type.OBJECT,
              description: "Key-value pairs of heir type and their fraction share",
              properties: {},
              additionalProperties: { type: Type.STRING }
            },
            fraction_math: { type: Type.STRING },
            distribution_notes: { type: Type.STRING },
            validation: { type: Type.STRING, description: "valid|invalid" },
            reason: { type: Type.STRING, description: "If invalid, why?" }
          },
          required: ["eligible_heirs", "excluded_heirs", "shares", "fraction_math", "distribution_notes", "validation"]
        }
      }
    });

    const result = JSON.parse(response.text || "{}");
    return result;
  } catch (error) {
    console.error("Calculation Engine Error:", error);
    return { validation: "invalid", reason: "Error connecting to calculation engine." };
  }
};

export const testConnection = async () => {
  const ai = getClient();
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: 'Assalamu Alaikum',
    });
    return !!response.text;
  } catch (error) {
    return false;
  }
};

import React, { useState, useEffect, useRef } from 'react';
import Layout from './components/Layout';
import { sendFaraidMessage, testConnection, calculateInheritance } from './services/geminiService';
import { Message, ConnectionStatus, EstateInfo, Heir, AppStep, HeirType, ViewMode } from './types';

interface CalculationResult {
  eligible_heirs: string[];
  excluded_heirs: string[];
  shares: Record<string, string>;
  fraction_math: string;
  distribution_notes: string;
  validation: 'valid' | 'invalid';
  reason?: string;
}

const App: React.FC = () => {
  const [hasStarted, setHasStarted] = useState(false);
  const [onboardingPage, setOnboardingPage] = useState(1);
  const [viewMode, setViewMode] = useState<ViewMode>('calculator');
  const [step, setStep] = useState<AppStep>(AppStep.ESTATE);
  const [messages, setMessages] = useState<Message[]>([]);
  const [input, setInput] = useState('');
  const [status, setStatus] = useState<ConnectionStatus>(ConnectionStatus.IDLE);
  const [isCalculating, setIsCalculating] = useState(false);
  const [calcResult, setCalcResult] = useState<CalculationResult | null>(null);

  const [estate, setEstate] = useState<EstateInfo>({
    totalAssets: 0,
    funeralExpenses: 0,
    debts: 0,
    willAmount: 0,
  });
  const [deceasedGender, setDeceasedGender] = useState<'Male' | 'Female' | null>(null);
  const [heirs, setHeirs] = useState<Heir[]>([]);

  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const init = async () => {
      setStatus(ConnectionStatus.CONNECTING);
      const isConnected = await testConnection();
      setStatus(isConnected ? ConnectionStatus.CONNECTED : ConnectionStatus.ERROR);

      const welcomeMsg: Message = {
        id: 'welcome',
        role: 'model',
        text: `Assalamu Alaikum wa Rahmatullah! 👋\n\nWelcome to the Islamic Inheritance Assistant (Faraid Malayalam).\nഇത് ഒരു ഇസ്ലാമിക് ശരീഅത്ത് അടിസ്ഥാനമാക്കിയുള്ള അവകാശവകാ സഹായിയാണ്.\n\nനമുക്ക് തുടങ്ങാം! ആദ്യം ആസ്തി വിവരങ്ങൾ (Estate Information) രേഖപ്പെടുത്താം.`,
        timestamp: new Date(),
      };
      setMessages([welcomeMsg]);
    };
    init();
  }, []);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [messages, viewMode, hasStarted]);

  const handleChat = async () => {
    if (!input.trim()) return;
    const userMsg: Message = { id: Date.now().toString(), role: 'user', text: input, timestamp: new Date() };
    setMessages(prev => [...prev, userMsg]);
    setInput('');

    try {
      const context = `Current Step: ${step}. Estate: ${JSON.stringify(estate)}. Deceased: ${deceasedGender}. Heirs: ${JSON.stringify(heirs)}`;
      const response = await sendFaraidMessage(input, context);
      const modelMsg: Message = { id: (Date.now() + 1).toString(), role: 'model', text: response, timestamp: new Date() };
      setMessages(prev => [...prev, modelMsg]);
    } catch (err) {
      setMessages(prev => [...prev, { id: 'err', role: 'model', text: "Error connecting to AI.", timestamp: new Date() }]);
    }
  };

  const performCalculation = async () => {
    setIsCalculating(true);
    setCalcResult(null);

    const getCount = (type: HeirType) => heirs.find(h => h.type === type)?.count || 0;

    const engineInput = {
      gender: deceasedGender?.toLowerCase(),
      husband: getCount('Husband') > 0 ? 1 : 0,
      wives: getCount('Wife'),
      sons: getCount('Son'),
      daughters: getCount('Daughter'),
      father: getCount('Father') > 0 ? 1 : 0,
      mother: getCount('Mother') > 0 ? 1 : 0,
      grandfather: getCount('PaternalGrandfather') > 0 ? 1 : 0,
      grandmother: (getCount('MaternalGrandmother') > 0 || getCount('PaternalGrandmother') > 0) ? 1 : 0,
      brothers: getCount('FullBrother'),
      sisters: getCount('FullSister'),
      maternal_brothers: getCount('UterineBrother'),
      maternal_sisters: getCount('UterineSister')
    };

    const result = await calculateInheritance(engineInput);
    setCalcResult(result);
    setIsCalculating(false);
  };

  const addHeir = (type: HeirType) => {
    setHeirs(prev => {
      const existing = prev.find(h => h.type === type);
      if (existing) {
        return prev.map(h => h.type === type ? { ...h, count: h.count + 1 } : h);
      }
      return [...prev, { id: Date.now().toString(), type, count: 1 }];
    });
  };

  const updateHeirCount = (id: string, delta: number) => {
    setHeirs(prev => prev.map(h => {
      if (h.id === id) {
        const newCount = Math.max(1, h.count + delta);
        return { ...h, count: newCount };
      }
      return h;
    }));
  };

  const removeHeir = (id: string) => {
    setHeirs(prev => prev.filter(h => h.id !== id));
  };

  const netEstate = estate.totalAssets - estate.funeralExpenses - estate.debts - estate.willAmount;
  const stepNumbers = { [AppStep.ESTATE]: '1', [AppStep.DECEASED_INFO]: '2', [AppStep.HEIRS]: '3', [AppStep.SUMMARY]: '4' };

  const primaryHeirs: HeirType[] = deceasedGender === 'Male' 
    ? ['Wife', 'Father', 'Mother', 'Son', 'Daughter'] 
    : ['Husband', 'Father', 'Mother', 'Son', 'Daughter'];

  const secondaryHeirs: HeirType[] = [
    'PaternalGrandfather', 'MaternalGrandmother', 'PaternalGrandmother', 
    'FullBrother', 'FullSister', 'ConsanguineBrother', 'ConsanguineSister',
    'UterineBrother', 'UterineSister', 'Nephew', 'PaternalUncle'
  ];

  if (!hasStarted) {
    const renderOnboardingPage = () => {
      switch (onboardingPage) {
        case 1:
          return (
            <div className="flex flex-col items-center justify-center text-center space-y-8 animate-in fade-in duration-500 max-w-lg mx-auto">
              <div className="w-24 h-24 bg-emerald-50 rounded-[2.5rem] flex items-center justify-center border border-emerald-100 shadow-sm mb-4">
                <svg className="w-12 h-12 text-[#059669]" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1.5} d="M19 21V5a2 2 0 00-2-2H7a2 2 0 00-2 2v16m14 0h2m-2 0h-5m-9 0H3m2 0h5M9 7h1m-1 4h1m4-4h1m-1 4h1m-5 10v-5a1 1 0 011-1h2a1 1 0 011 1v5m-4 0h4" />
                </svg>
              </div>
              <h1 className="text-4xl font-bold text-[#D4AF37] malayalam">സ്വാഗതം</h1>
              <p className="text-xl text-[#1F2937] malayalam px-4">അസ്സലാമു അലൈക്കും. ഇസ്‌ലാമിക ശരീഅത്ത് നിയമപ്രകാരം അനന്തരാവകാശം എളുപ്പത്തിൽ കണക്കാക്കാൻ സഹായിക്കുന്ന ആപ്ലിക്കേഷനിലേക്ക് സ്വാഗതം.</p>
            </div>
          );
        case 2:
