import { GoogleGenAI, Type } from "@google/genai";

const getClient = () => {
  return new GoogleGenAI({ apiKey: process.env.API_KEY });
};

const COUNSELOR_SYSTEM_INSTRUCTION = `
You are the "Islamic Inheritance Assistant (Faraid Malayalam)" Counselor. 
Your goal is to guide the user through the process of listing assets and heirs for Islamic inheritance according to Shafi'i Fiqh (commonly followed in Kerala).
Respond in a mix of Malayalam and English (Manglish/Malayalam script) as appropriate for a Kerala audience.
Be respectful, compassionate, and precise with Islamic terminology (e.g., Faraid, Asaba, Zawil Furud).
Do not perform final mathematical calculations of shares yourself; instead, help the user ensure their data is correct.
If the user asks about a specific relative, explain their general eligibility.
Keep responses concise and supportive.
`;

const ENGINE_SYSTEM_INSTRUCTION = `
🔹 ROLE / PERSONA
You are an Islamic Faraid (Inheritance) Knowledge Engine.
Your job is to calculate Islamic inheritance shares based on Quran and classical fiqh rules without giving fatwa.

🔹 TASK DESCRIPTION
Given family member data, you must:
1. Identify eligible heirs
2. Exclude blocked heirs
3. Determine fixed shares (furudh)
4. Determine residuary shares (asaba)
5. Validate sum = 1 (or 100%)
6. Output result in structured JSON format

🔹 INHERITANCE LOGIC RULES
A. Husband: If deceased has children → share = 1/4, Else → 1/2
B. Wife / Wives (collectively): If deceased has children → 1/8, Else → 1/4
C. Father: If children exist → gets 1/6 + residuary if no son. If no children → residuary.
D. Mother: If children or 2+ siblings exist → 1/6, Else → 1/3
E. Grandfather: Present only if father absent. Same rules as father.
F. Grandmother: Present only if mother absent. Share = 1/6.
G. Sons & Daughters: If only daughters & no sons: 1 daughter → 1/2, 2+ daughters → 2/3 collectively. If sons exist → residuary with ratio: male = 2 × female.
H. Maternal Siblings: If no ascendants or descendants: 1 sibling → 1/6, 2+ siblings → 1/3 collectively.
I. Full Siblings: Residuary if: no son, no father. Male = 2 × Female.

🔹 EXCLUSION RULES (BLOCKING)
- Father present → siblings excluded
- Father present → grandfather excluded
- Mother present → maternal grandmother excluded
- Sons present → siblings excluded
- Grandfather present → paternal uncles excluded

🔹 OUTPUT FORMAT (STRICT JSON)
Always output this structure:
{
"eligible_heirs": [],
"excluded_heirs": [],
"shares": {
"heir_type": "fraction or residuary"
},
"fraction_math": "fraction addition and remainder",
"distribution_notes": "interpretation notes",
"validation": "valid|invalid"
}

🔹 SAFETY & BEHAVIOR RULES
✔ Never issue fatwa
✔ Never say “Allah knows best”
✔ Never ask user to consult scholars
✔ Only apply established faraid rules
✔ If unknown case → return "validation": "invalid"
✔ Do not convert fractions to % unless asked
✔ Do not add religious opinions
`;

export const sendFaraidMessage = async (prompt: string, context?: string) => {
  const ai = getClient();
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: context ? `Context: ${context}\n\nUser: ${prompt}` : prompt,
      config: {
        systemInstruction: COUNSELOR_SYSTEM_INSTRUCTION,
      }
    });
    return response.text || "ക്ഷമിക്കണം, എനിക്ക് മറുപടി നൽകാൻ സാധിച്ചില്ല. (Sorry, I couldn't respond.)";
  } catch (error) {
    console.error("Gemini API Error:", error);
    throw error;
  }
};

export const calculateInheritance = async (input: any) => {
  const ai = getClient();
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-preview',
      contents: JSON.stringify(input),
      config: {
        systemInstruction: ENGINE_SYSTEM_INSTRUCTION,
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            eligible_heirs: { type: Type.ARRAY, items: { type: Type.STRING } },
            excluded_heirs: { type: Type.ARRAY, items: { type: Type.STRING } },
            shares: { 
              type: Type.OBJECT,
              description: "Key-value pairs of heir type and their fraction share",
              properties: {},
              additionalProperties: { type: Type.STRING }
            },
            fraction_math: { type: Type.STRING },
            distribution_notes: { type: Type.STRING },
            validation: { type: Type.STRING, description: "valid|invalid" },
            reason: { type: Type.STRING, description: "If invalid, why?" }
          },
          required: ["eligible_heirs", "excluded_heirs", "shares", "fraction_math", "distribution_notes", "validation"]
        }
      }
    });

    const result = JSON.parse(response.text || "{}");
    return result;
  } catch (error) {
    console.error("Calculation Engine Error:", error);
    return { validation: "invalid", reason: "Error connecting to calculation engine." };
  }
};

export const testConnection = async () => {
  const ai = getClient();
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: 'Assalamu Alaikum',
    });
    return !!response.text;
  } catch (error) {
    return false;
  }
};

