  const [isCalculating, setIsCalculating] = useState(false);
  const [calcResult, setCalcResult] = useState<CalculationResult | null>(null);

  const [estate, setEstate] = useState<EstateInfo>({
    totalAssets: 0,
    funeralExpenses: 0,
    debts: 0,
    willAmount: 0,
  });
  const [deceasedGender, setDeceasedGender] = useState<'Male' | 'Female' | null>(null);
  const [heirs, setHeirs] = useState<Heir[]>([]);

  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const init = async () => {
      setStatus(ConnectionStatus.CONNECTING);
      const isConnected = await testConnection();
      setStatus(isConnected ? ConnectionStatus.CONNECTED : ConnectionStatus.ERROR);

      const welcomeMsg: Message = {
        id: 'welcome',
        role: 'model',
        text: `Assalamu Alaikum wa Rahmatullah! 👋\n\nWelcome to the Islamic Inheritance Assistant (Faraid Malayalam).\nഇത് ഒരു ഇസ്ലാമിക് ശരീഅത്ത് അടിസ്ഥാനമാക്കിയുള്ള അവകാശവകാ സഹായിയാണ്.`,
        timestamp: new Date(),
      };
      setMessages([welcomeMsg]);
    };
    init();
  }, []);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [messages, viewMode, hasStarted]);

  const handleChat = async () => {
    if (!input.trim()) return;
    const userMsg: Message = { id: Date.now().toString(), role: 'user', text: input, timestamp: new Date() };
    setMessages(prev => [...prev, userMsg]);
    setInput('');

    try {
      const context = `Current Step: ${step}. Estate: ${JSON.stringify(estate)}. Deceased: ${deceasedGender}. Heirs: ${JSON.stringify(heirs)}`;
      const response = await sendFaraidMessage(input, context);
      const modelMsg: Message = { id: (Date.now() + 1).toString(), role: 'model', text: response, timestamp: new Date() };
      setMessages(prev => [...prev, modelMsg]);
    } catch (err) {
      setMessages(prev => [...prev, { id: 'err', role: 'model', text: "Error connecting to AI.", timestamp: new Date() }]);
    }
  };

  const performCalculation = async () => {
    setIsCalculating(true);
    setCalcResult(null);

    const getCount = (type: HeirType) => heirs.find(h => h.type === type)?.count || 0;

    // Strict input mapping matching the user's requested JSON structure
    const engineInput = {
      gender: deceasedGender === 'Male' ? 'male' : 'female',
      husband: getCount('Husband') > 0 ? 1 : 0,
      wives: getCount('Wife'),
      sons: getCount('Son'),
      daughters: getCount('Daughter'),
      father: getCount('Father') > 0 ? 1 : 0,
      mother: getCount('Mother') > 0 ? 1 : 0,
      grandfather: getCount('PaternalGrandfather') > 0 ? 1 : 0,
      grandmother: (getCount('MaternalGrandmother') > 0 || getCount('PaternalGrandmother') > 0) ? 1 : 0,
      brothers: getCount('FullBrother'),
      sisters: getCount('FullSister'),
      maternal_brothers: getCount('UterineBrother'),
      maternal_sisters: getCount('UterineSister')
    };

    const result = await calculateInheritance(engineInput);
    setCalcResult(result);
    setIsCalculating(false);
  };

  const addHeir = (type: HeirType) => {
    setHeirs(prev => {
      const existing = prev.find(h => h.type === type);
      if (existing) {
        return prev.map(h => h.type === type ? { ...h, count: h.count + 1 } : h);
      }
      return [...prev, { id: Date.now().toString(), type, count: 1 }];
    });
  };

  const updateHeirCount = (id: string, delta: number) => {
    setHeirs(prev => prev.map(h => {
      if (h.id === id) {
        const newCount = Math.max(1, h.count + delta);
        return { ...h, count: newCount };
      }
      return h;
    }));
  };

  const removeHeir = (id: string) => {
    setHeirs(prev => prev.filter(h => h.id !== id));
  };

  const netEstate = estate.totalAssets - estate.funeralExpenses - estate.debts - estate.willAmount;
  const stepNumbers = { [AppStep.ESTATE]: '1', [AppStep.DECEASED_INFO]: '2', [AppStep.HEIRS]: '3', [AppStep.SUMMARY]: '4' };

  const primaryHeirs: HeirType[] = deceasedGender === 'Male' 
    ? ['Wife', 'Father', 'Mother', 'Son', 'Daughter'] 
    : ['Husband', 'Father', 'Mother', 'Son', 'Daughter'];

  const secondaryHeirs: HeirType[] = [
    'PaternalGrandfather', 'MaternalGrandmother', 'PaternalGrandmother', 
    'FullBrother', 'FullSister', 'ConsanguineBrother', 'ConsanguineSister',
    'UterineBrother', 'UterineSister', 'Nephew', 'PaternalUncle'
  ];

  if (!hasStarted) {
    const renderOnboardingPage = () => {
      switch (onboardingPage) {
        case 1:
          return (
            <div className="flex flex-col items-center justify-center text-center space-y-8 max-w-lg mx-auto h-full px-6">
              <div className="w-24 h-24 bg-emerald-50 rounded-[2.5rem] flex items-center justify-center border border-emerald-100 shadow-sm mb-4">
                <svg className="w-12 h-12 text-[#059669]" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1.5} d="M19 21V5a2 2 0 00-2-2H7a2 2 0 00-2 2v16m14 0h2m-2 0h-5m-9 0H3m2 0h5M9 7h1m-1 4h1m4-4h1m-1 4h1m-5 10v-5a1 1 0 011-1h2a1 1 0 011 1v5m-4 0h4" />
                </svg>
              </div>
              <h1 className="text-4xl font-bold text-[#D4AF37] malayalam">സ്വാഗതം</h1>
              <p className="text-xl text-[#1F2937] malayalam px-4 leading-relaxed">
                അസ്സലാമു അലൈക്കും. ഇസ്‌ലാമിക ശരീഅത്ത് നിയമപ്രകാരം അനന്തരാവകാശം എളുപ്പത്തിൽ കണക്കാക്കാൻ സഹായിക്കുന്ന ആപ്ലിക്കേഷനിലേക്ക് സ്വാഗതം.
              </p>
            </div>
          );
        case 2:
          return (
            <div className="flex flex-col items-center justify-center text-center space-y-8 max-w-lg mx-auto h-full px-6">
              <div className="w-20 h-20 bg-emerald-50 rounded-full flex items-center justify-center border border-emerald-100 mb-4">
                <svg className="w-10 h-10 text-[#059669]" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 5H7a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2V7a2 2 0 00-2-2h-2M9 5a2 2 0 002 2h2a2 2 0 002-2M9 5a2 2 0 012-2h2a2 2 0 012 2" />
                </svg>
              </div>
              <h2 className="text-2xl font-bold text-[#D4AF37] malayalam">അപ്ലിക്കേഷനെ കുറിച്ച്</h2>
              <p className="text-lg text-[#1F2937] malayalam px-6 leading-relaxed">
                മരണപ്പെട്ട വ്യക്തിയുടെ ആകെ ആസ്തി, കടങ്ങൾ എന്നിവ രേഖപ്പെടുത്താനും അവകാശികളെ തിരഞ്ഞെടുക്കാനും വിശ്വസ്തതയോടും സുതാര്യതയോടും കൂടി ഈ ടൂൾ സഹായിക്കുന്നു.
              </p>
            </div>
          );
        case 3:
          return (
            <div className="flex flex-col items-center justify-center text-center space-y-6 px-4 w-full max-w-md mx-auto h-full">
              <h2 className="text-2xl font-bold text-[#D4AF37] malayalam mb-2">ഖുർആനിക തെളിവുകൾ</h2>
              <div className="w-full space-y-4">
                <div className="bg-emerald-50 p-6 rounded-2xl border border-emerald-100 shadow-sm">
                  <p className="text-2xl font-serif text-[#059669] leading-loose text-right font-bold" dir="rtl">يُوصِيكُمُ ٱللَّهُ فِيٓ أَوْلَـٰدِكُمْ...</p>
                  <p className="text-[#1F2937] text-sm malayalam leading-relaxed mt-4">
                    "നിങ്ങളുടെ മക്കളുടെ കാര്യത്തിൽ അല്ലാഹു നിങ്ങൾക്ക് നിർദ്ദേശം നൽകുന്നു..." (സൂറത്തുന്നിസാ: 11)
                  </p>
                </div>
                <div className="bg-emerald-50 p-6 rounded-2xl border border-emerald-100 shadow-sm">
                  <p className="text-2xl font-serif text-[#059669] leading-loose text-right font-bold" dir="rtl">تِلْكَ حُدُودُ ٱللَّهِ</p>
                  <p className="text-[#1F2937] text-sm malayalam leading-relaxed mt-4">
                    "ഈ നിയമങ്ങൾ അല്ലാഹു നിശ്ചയിച്ച അതിരുകളാണ്." (സൂറത്തുന്നിസാ: 13)
                  </p>
                </div>
              </div>
            </div>
          );
        case 4:
          return (
            <div className="flex flex-col items-center justify-center text-center space-y-8 px-4 w-full max-w-md mx-auto h-full">
              <h2 className="text-2xl font-bold text-[#D4AF37] malayalam mb-2">ഹദീസും പ്രാധാന്യവും</h2>
              <div className="bg-amber-50 p-8 rounded-[2rem] border border-amber-100 shadow-sm w-full">
                <p className="text-2xl font-serif text-[#854d0e] leading-loose text-right font-bold" dir="rtl">إِنَّ اللهَ قَدْ أَعْطَى കُلَّ ذِي حَقٍّ حَقَّهُ</p>
                <p className="text-[#1F2937] text-md malayalam leading-relaxed mt-4 font-medium">
                  "നിശ്ചയമായും അല്ലാഹു ഓരോ അവകാശിക്കും അർഹമായ ഓഹരി നൽകിയിരിക്കുന്നു."
                </p>
              </div>
              <p className="text-md text-[#1F2937] malayalam font-semibold leading-relaxed">
                അല്ലാഹുവിന്റെ നിയമങ്ങൾ പാലിച്ച് തർക്കങ്ങൾ ഒഴിവാക്കുക എന്നത് പരലോക വിജയത്തിന് പ്രധാനമാണ്.
              </p>
            </div>
          );
        default:
          return null;
      }
    };

    return (
      <div className="fixed inset-0 bg-[#F7F7F5] z-50 flex flex-col h-screen overflow-hidden">
        <div className="flex-1 flex items-center justify-center px-6 overflow-hidden">
          {renderOnboardingPage()}
        </div>

        <div className="shrink-0 flex flex-col items-center pb-12 pt-4 bg-white border-t border-gray-50">
          <div className="w-full max-w-xs px-6">
            {onboardingPage < 4 ? (
              <button 
                onClick={() => setOnboardingPage(onboardingPage + 1)}
                className="w-full bg-[#059669] hover:bg-[#047857] text-white text-lg py-5 rounded-2xl font-bold transition-all malayalam flex items-center justify-center gap-2 shadow-lg active:scale-95"
              >
                Next ➜
              </button>
            ) : (
              <button 
                onClick={() => setHasStarted(true)}
                className="w-full bg-[#059669] hover:bg-[#047857] text-white text-lg py-5 rounded-2xl font-bold transition-all shadow-xl malayalam flex items-center justify-center gap-2 active:scale-95"
              >
                Start Calculation ➜
              </button>
            )}
          </div>
        </div>
      </div>
    );
  }

  const sidebarContent = (
    <div className="space-y-8">
      <div>
        <h3 className="text-xs font-bold text-gray-400 uppercase tracking-widest mb-4 malayalam">നിലവിലെ വിവരങ്ങൾ</h3>
        <div className="space-y-3">
          <div className="p-4 bg-emerald-50 rounded-xl border border-emerald-100">
            <p className="text-[10px] text-[#059669] uppercase font-bold mb-1">Net Estate (മിച്ചം ഉള്ളത്)</p>
            <p className="text-xl font-bold text-[#1F2937]">₹{netEstate.toLocaleString()}</p>
          </div>
          {deceasedGender && (
            <div className="p-3 bg-white rounded-lg border border-gray-100 shadow-sm">
              <p className="text-xs text-gray-500 malayalam">മരണപ്പെട്ട വ്യക്തി</p>
              <p className="text-sm font-medium text-[#1F2937]">{deceasedGender === 'Male' ? 'പുരുഷൻ (Male)' : 'സ്ത്രീ (Female)'}</p>
            </div>
          )}
        </div>
      </div>

      <div>
        <h3 className="text-xs font-bold text-gray-400 uppercase tracking-widest mb-4 malayalam">അവകാശികൾ ({heirs.reduce((acc, h) => acc + h.count, 0)})</h3>
        <div className="space-y-2">
          {heirs.length === 0 ? (
            <p className="text-xs text-gray-400 italic malayalam">അവകാശികളെ ചേർത്തിട്ടില്ല</p>
          ) : (
            heirs.map(h => (
              <div key={h.id} className="flex justify-between items-center p-2 bg-white rounded border border-gray-100 group shadow-sm">
                <span className="text-xs text-gray-700">{h.type} <span className="text-[#059669] font-bold ml-1">x{h.count}</span></span>
                <button onClick={() => removeHeir(h.id)} className="text-red-400 hover:text-red-600 transition-colors">
                  <svg className="w-3 h-3" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path d="M6 18L18 6M6 6l12 12" /></svg>
                </button>
              </div>
            ))
          )}
        </div>
      </div>
    </div>
  );

  return (
    <Layout sidebarContent={sidebarContent} currentStep={stepNumbers[step]} viewMode={viewMode} onViewModeChange={setViewMode}>
      <div className="space-y-10 animate-in fade-in duration-500">

        {viewMode === 'knowledge' ? (
          <div className="space-y-8 max-w-2xl mx-auto py-10">
            <div className="animate-in fade-in slide-in-from-right-4 duration-700 bg-white p-8 md:p-12 rounded-[2rem] shadow-sm border border-gray-100">
                <h2 className="text-2xl font-bold mb-6 malayalam border-b border-gray-50 pb-4 text-[#D4AF37]">ഫറായിദ് വിവരശേഖരം</h2>
                <p className="text-lg leading-relaxed text-[#1F2937] malayalam">നിങ്ങൾ കണക്കുകൂട്ടൽ ആരംഭിച്ചു കഴിഞ്ഞു. ഏതെങ്കിലും ഘട്ടത്തിൽ സഹായം ആവശ്യമുണ്ടെങ്കിൽ എഐ കൗൺസിലറോട് ചോദിക്കാവുന്നതാണ്.</p>
                <div className="flex justify-start mt-10">
                  <button onClick={() => setViewMode('calculator')} className="bg-[#059669] hover:bg-[#047857] text-white px-8 py-3 rounded-xl font-bold transition-all shadow-lg malayalam">കാൽക്കുലേറ്ററിലേക്ക് തിരികെ പോകാം</button>
                </div>
              </div>
          </div>
        ) : (
          <div className="space-y-10">
            {step === AppStep.ESTATE && (
              <div className="space-y-6 animate-in fade-in slide-in-from-left-4 duration-500">
                <div className="border-l-4 border-[#D4AF37] pl-4">
                  <h2 className="text-2xl font-bold malayalam text-[#1F2937]">Step 1: ആസ്തി വിവരങ്ങൾ</h2>
                  <p className="text-gray-500 text-sm">Enter the financial details of the deceased's estate.</p>
                </div>

                <div className="grid grid-cols-1 md:grid-cols-2 gap-6 bg-white p-8 rounded-[2rem] shadow-sm border border-gray-100">
                  <div className="space-y-2">
                    <label className="text-xs font-bold text-gray-400 uppercase malayalam">മൊത്തം ആസ്തി (Total Assets)</label>
                    <input 
                      type="number" 
                      value={estate.totalAssets || ''} 
                      onChange={e => setEstate({...estate, totalAssets: Number(e.target.value)})}
                      className="w-full bg-gray-50 border border-gray-100 rounded-xl p-4 focus:border-[#059669] focus:ring-1 focus:ring-[#059669] transition-all text-[#1F2937]"
                      placeholder="0"
                    />
                  </div>
                  <div className="space-y-2">
                    <label className="text-xs font-bold text-gray-400 uppercase malayalam">സംസ്കാര ചിലവ് (Funeral)</label>
                    <input 
                      type="number" 
                      value={estate.funeralExpenses || ''} 
                      onChange={e => setEstate({...estate, funeralExpenses: Number(e.target.value)})}
                      className="w-full bg-gray-50 border border-gray-100 rounded-xl p-4 focus:border-[#059669] focus:ring-1 focus:ring-[#059669] transition-all text-[#1F2937]"
                      placeholder="0"
                    />
                  </div>
                  <div className="space-y-2">
                    <label className="text-xs font-bold text-gray-400 uppercase malayalam">കടങ്ങൾ (Debts)</label>
                    <input 
                      type="number" 
                      value={estate.debts || ''} 
                      onChange={e => setEstate({...estate, debts: Number(e.target.value)})}
                      className="w-full bg-gray-50 border border-gray-100 rounded-xl p-4 focus:border-[#059669] focus:ring-1 focus:ring-[#059669] transition-all text-[#1F2937]"
                      placeholder="0"
                    />
                  </div>
                  <div className="space-y-2">
                    <label className="text-xs font-bold text-gray-400 uppercase malayalam">വസിയത്ത് (Will Amount ≤ 1/3)</label>
                    <input 
                      type="number" 
                      value={estate.willAmount || ''} 
                      onChange={e => setEstate({...estate, willAmount: Number(e.target.value)})}
                      className="w-full bg-gray-50 border border-gray-100 rounded-xl p-4 focus:border-[#059669] focus:ring-1 focus:ring-[#059669] transition-all text-[#1F2937]"
                      placeholder="0"
                    />
                  </div>
                </div>
                <div className="flex justify-end">
                  <button onClick={() => setStep(AppStep.DECEASED_INFO)} className="bg-[#059669] hover:bg-[#047857] text-white px-10 py-4 rounded-xl font-bold shadow-lg malayalam">അടുത്ത ഘട്ടം (Next Step) →</button>
                </div>
              </div>
            )}

            {step === AppStep.DECEASED_INFO && (
              <div className="space-y-6 animate-in slide-in-from-right-4 duration-500">
                <div className="border-l-4 border-[#D4AF37] pl-4">
                  <h2 className="text-2xl font-bold malayalam text-[#1F2937]">Step 2: മരണപ്പെട്ട വ്യക്തിയുടെ വിവരങ്ങൾ</h2>
                  <p className="text-gray-500 text-sm">Select the gender of the deceased person.</p>
                </div>
                <div className="grid grid-cols-2 gap-6">
                  <button onClick={() => setDeceasedGender('Male')} className={`p-10 rounded-[2rem] border-2 transition-all flex flex-col items-center gap-4 ${deceasedGender === 'Male' ? 'bg-emerald-50 border-[#059669]' : 'bg-white border-gray-100'}`}>
                    <div className="w-20 h-20 rounded-full bg-blue-50 flex items-center justify-center text-blue-500 shadow-sm"><svg className="w-10 h-10" fill="currentColor" viewBox="0 0 24 24"><path d="M12 2C6.48 2 2 6.48 2 12s4.48 10 10 10 10-4.48 10-10S17.52 2 12 2zm0 3c1.66 0 3 1.34 3 3s-1.34 3-3 3-3-1.34-3-3 1.34-3 3-3zm0 14.2c-2.5 0-4.71-1.28-6-3.22.03-1.99 4-3.08 6-3.08s5.97 1.09 6 3.08c-1.29 1.94-3.5 3.22-6 3.22z" /></svg></div>
                    <span className="font-bold malayalam">പുരുഷൻ (Male)</span>
                  </button>
                  <button onClick={() => setDeceasedGender('Female')} className={`p-10 rounded-[2rem] border-2 transition-all flex flex-col items-center gap-4 ${deceasedGender === 'Female' ? 'bg-pink-50 border-[#059669]' : 'bg-white border-gray-100'}`}>
                    <div className="w-20 h-20 rounded-full bg-pink-50 flex items-center justify-center text-pink-500 shadow-sm"><svg className="w-10 h-10" fill="currentColor" viewBox="0 0 24 24"><path d="M12 2C6.48 2 2 6.48 2 12s4.48 10 10 10 10-4.48 10-10S17.52 2 12 2zm0 3c1.66 0 3 1.34 3 3s-1.34 3-3 3-3-1.34-3-3 1.34-3 3-3zm0 14.2c-2.5 0-4.71-1.28-6-3.22.03-1.99 4-3.08 6-3.08s5.97 1.09 6 3.08c-1.29 1.94-3.5 3.22-6 3.22z" /></svg></div>
                    <span className="font-bold malayalam">സ്ത്രീ (Female)</span>
                  </button>
                </div>
                <div className="flex justify-between">
                   <button onClick={() => setStep(AppStep.ESTATE)} className="text-gray-400 malayalam">← പുറകോട്ട്</button>
                   <button disabled={!deceasedGender} onClick={() => setStep(AppStep.HEIRS)} className="bg-[#059669] disabled:bg-gray-200 text-white px-10 py-4 rounded-xl font-bold shadow-lg malayalam">അടുത്ത ഘട്ടം (Next Step) →</button>
                </div>
              </div>
            )}

            {step === AppStep.HEIRS && (
