                </div>
                <div className="flex justify-end">
                  <button onClick={() => setStep(AppStep.DECEASED_INFO)} className="bg-[#059669] hover:bg-[#047857] text-white px-10 py-4 rounded-xl font-bold shadow-lg malayalam">അടുത്ത ഘട്ടം (Next Step) →</button>
