                    <div className="bg-white w-full max-w-2xl max-h-[90vh] rounded-[2.5rem] shadow-2xl flex flex-col overflow-hidden animate-in zoom-in-95 duration-300">
                      <header className="p-8 border-b border-gray-100 flex items-center justify-between shrink-0">
                        <div>
                          <h3 className="text-2xl font-bold text-gray-800 malayalam">അവകാശിയെ ചേർക്കുക</h3>
                          <p className="text-gray-400 text-sm">Select a relative to add to the list.</p>
                        </div>
                        <button onClick={() => setIsAddHeirModalOpen(false)} className="p-2 hover:bg-gray-50 rounded-full text-gray-400">
                          <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" /></svg>
                        </button>
                      </header>

                      <div className="p-8 shrink-0">
                        <div className="relative">
                          <input 
                            type="text" 
                            placeholder="Search relatives..." 
                            value={heirSearchQuery}
                            onChange={(e) => setHeirSearchQuery(e.target.value)}
                            className="w-full bg-gray-50 border border-gray-100 rounded-2xl py-4 pl-12 pr-6 focus:ring-1 focus:ring-[#059669] outline-none"
                          />
                          <svg className="w-5 h-5 absolute left-4 top-1/2 -translate-y-1/2 text-gray-400" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" /></svg>
                        </div>
                      </div>

                      <div className="flex-1 overflow-y-auto p-8 pt-0 space-y-8 custom-scrollbar">
                        {/* Fix: Explicitly type [category, types] to avoid 'unknown' inference for types.filter */}
                        {(Object.entries(availableHeirsForDeceased) as [string, HeirType[]][]).map(([category, types]) => {
                          const filteredTypes = types.filter(t => t.toLowerCase().includes(heirSearchQuery.toLowerCase()));
                          if (filteredTypes.length === 0) return null;

                          return (
                            <div key={category} className="space-y-4">
                              <h4 className="text-xs font-bold text-[#D4AF37] uppercase tracking-widest border-b border-gold-100 pb-2">{category}</h4>
                              <div className="grid grid-cols-2 sm:grid-cols-3 gap-3">
                                {filteredTypes.map(type => {
                                  const alreadyAdded = heirs.find(h => h.type === type);
                                  const max = MAX_HEIRS[type];
                                  const isMaxed = max && alreadyAdded && alreadyAdded.count >= max;

                                  return (
                                    <button 
                                      key={type} 
                                      disabled={isMaxed}
                                      onClick={() => addHeir(type as HeirType)}
                                      className={`p-4 rounded-2xl border text-sm font-bold transition-all text-center flex flex-col items-center gap-2 ${
                                        isMaxed ? 'bg-gray-50 border-gray-100 text-gray-300 cursor-not-allowed' : 
                                        alreadyAdded ? 'bg-emerald-50 border-emerald-100 text-[#059669] shadow-sm' : 
                                        'bg-white border-gray-100 text-gray-600 hover:border-[#059669] hover:text-[#059669]'
                                      }`}
                                    >
                                      <span className="text-xs">{type}</span>
                                      {alreadyAdded && <span className="text-[10px] px-2 py-0.5 bg-white border border-emerald-200 rounded-full">Added: {alreadyAdded.count}</span>}
                                    </button>
                                  );
                                })}
                              </div>
                            </div>
                          );
                        })}
                      </div>
                    </div>
                  </div>
                )}

                <div className="flex justify-between pt-6">
                   <button onClick={() => setStep(AppStep.DECEASED_INFO)} className="text-gray-400 malayalam flex items-center gap-2 hover:text-[#1F2937] transition-colors">
                     <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 19l-7-7 7-7" /></svg>
                     <span>പുറകോട്ട്</span>
                   </button>
                   <button 
                    disabled={heirs.length === 0}
                    onClick={() => setStep(AppStep.SUMMARY)} 
                    className="bg-[#059669] disabled:bg-gray-200 text-white px-10 py-4 rounded-xl font-bold shadow-lg malayalam transition-all hover:shadow-xl active:scale-95"
                   >
                     ഫിനിഷ് (Finish) →
                   </button>
                </div>
              </div>
            )}

            {step === AppStep.SUMMARY && (
               <div className="space-y-6 animate-in slide-in-from-bottom-4 duration-500">
