                       <h3 className="text-xl font-bold malayalam text-[#059669]">വിവരങ്ങൾ പൂർത്തിയായി!</h3>
                       <p className="text-sm text-gray-600">Click the button to generate the final inheritance report.</p>
                    </div>
                    <button onClick={() => performCalculation()} disabled={isCalculating} className="bg-[#059669] text-white px-8 py-4 rounded-2xl font-bold shadow-xl flex items-center justify-center gap-3 transition-all active:scale-95 malayalam">
                      {isCalculating ? (
                        <>
                          <svg className="animate-spin h-5 w-5 text-white" fill="none" viewBox="0 0 24 24"><circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle><path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path></svg>
                          <span>കണക്കാക്കുന്നു...</span>
                        </>
                      ) : (
                        <>
                          <span>കണക്ക് കാണുക</span>
                          <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M14 5l7 7m0 0l-7 7m7-7H3" /></svg>
                        </>
                      )}
                    </button>
                 </div>

                 {calcResult && (
                   <div className="bg-white border border-gray-100 p-8 rounded-[3rem] shadow-xl animate-in zoom-in duration-500 space-y-10">
                     <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4 border-b border-gray-100 pb-6">
                       <h2 className="text-2xl font-bold text-[#D4AF37] malayalam">അനന്തരാവകാശ ഓഹരികൾ</h2>
                       <div className="flex items-center gap-4">
                         <div className="flex items-center gap-2 mr-2">
                           <label className="text-[10px] font-bold text-gray-400 uppercase tracking-widest cursor-pointer" htmlFor="pctToggle">Show Percentage</label>
                           <button 
                             id="pctToggle"
                             onClick={() => setShowPercentage(!showPercentage)}
                             className={`w-10 h-5 rounded-full relative transition-colors ${showPercentage ? 'bg-[#059669]' : 'bg-gray-200'}`}
                           >
                             <div className={`absolute top-1 w-3 h-3 bg-white rounded-full transition-all ${showPercentage ? 'left-6' : 'left-1'}`} />
                           </button>
                         </div>
                         <div className={`px-4 py-1.5 rounded-full text-xs font-bold ${calcResult.validation === 'valid' ? 'bg-emerald-100 text-emerald-700' : 'bg-red-100 text-red-700'}`}>
                           {calcResult.validation.toUpperCase()}
                         </div>
                       </div>
                     </div>

                     {calcResult.validation === 'invalid' ? (
                       <div className="p-6 bg-red-50 text-red-600 rounded-2xl malayalam border border-red-100">
                         <strong>പിശക് (Error):</strong> {calcResult.reason}
                       </div>
                     ) : (
                       <>
                         {calcResult.excluded_heirs && calcResult.excluded_heirs.length > 0 && (
                           <div className="p-4 bg-gray-50 border border-gray-200 rounded-2xl">
                             <h4 className="text-xs font-bold text-gray-400 uppercase tracking-widest mb-2 malayalam">ഒഴിവാക്കപ്പെട്ടവർ (Excluded Heirs):</h4>
                             <div className="flex flex-wrap gap-2">
                               {calcResult.excluded_heirs.map(heir => (
                                 <span key={heir} className="px-3 py-1 bg-red-50 text-red-600 text-xs font-bold rounded-full border border-red-100">{heir}</span>
                               ))}
                             </div>
                           </div>
                         )}

                         <div className="grid grid-cols-1 sm:grid-cols-2 gap-6">
                           {Object.entries(calcResult.shares).map(([heir, share]) => {
                             const numericValue = getNumericShare(heir, calcResult);
                             const percentage = (numericValue * 100).toFixed(2);

                             return (
                               <div key={heir} className="bg-gray-50 p-6 rounded-[2rem] border border-gray-100 flex justify-between items-center group hover:bg-emerald-50 transition-all">
                                 <div>
                                   <p className="text-[10px] font-bold text-gray-400 uppercase tracking-widest">{heir}</p>
                                   <p className="text-xl font-bold text-[#1F2937] malayalam capitalize">{heir}</p>
                                 </div>
                                 <div className="text-right">
                                   <p className="text-3xl font-serif text-[#059669] font-bold">
                                     {showPercentage ? `${percentage}%` : String(share)}
                                   </p>
                                   {!showPercentage && (
                                     <p className="text-[10px] text-gray-400 font-bold mt-1 uppercase">({percentage}%)</p>
                                   )}
                                   {netEstate > 0 && (
                                     <p className="text-xs text-gray-400 font-bold mt-1">~ ₹{(numericValue * netEstate).toLocaleString()}</p>
                                   )}
                                 </div>
                               </div>
                             );
                           })}
                         </div>

                         <div className="space-y-6">
                           <div className="p-6 bg-amber-50 rounded-[2rem] border border-amber-100">
                             <h4 className="text-xs font-bold text-amber-700 uppercase mb-3 tracking-widest malayalam">🔢 കണക്ക് (Fraction Math):</h4>
                             <p className="text-lg font-serif text-amber-900 leading-relaxed whitespace-pre-line">{calcResult.fraction_math}</p>
                           </div>

                           <div className="p-6 bg-gray-50 rounded-[2rem] border border-gray-100">
                             <h4 className="text-xs font-bold text-gray-400 uppercase mb-3 tracking-widest malayalam">📝 വിശദീകരണം (Notes):</h4>
                             <p className="text-sm text-gray-600 leading-relaxed malayalam">{calcResult.distribution_notes}</p>
                           </div>
                         </div>
                       </>
                     )}
                   </div>
                 )}

                 <div className="bg-white border border-gray-100 p-8 rounded-[2rem] space-y-4 shadow-sm">
                   <h4 className="text-xs font-bold text-gray-400 uppercase tracking-widest">Chat with Assistant:</h4>
                   <div ref={scrollRef} className="h-[300px] overflow-y-auto space-y-4 pr-3 custom-scrollbar">
                      {messages.map((msg, i) => (
                        <div key={i} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}>
                           <div className={`max-w-[85%] p-4 rounded-2xl ${msg.role === 'user' ? 'bg-[#059669] text-white rounded-tr-none' : 'bg-gray-50 text-[#1F2937] rounded-tl-none border border-gray-100'}`}>
                              <p className="text-sm malayalam whitespace-pre-wrap">{msg.text}</p>
                           </div>
                        </div>
                      ))}
                   </div>
                   <div className="relative group">
                      <textarea value={input} onChange={e => setInput(e.target.value)} onKeyDown={e => e.key === 'Enter' && !e.shiftKey && (e.preventDefault(), handleChat())} placeholder="ചോദിക്കൂ..." className="w-full bg-gray-50 border border-gray-100 rounded-2xl py-4 pl-6 pr-14 focus:outline-none focus:ring-1 focus:ring-[#059669] resize-none h-16 shadow-sm" />
                      <button onClick={handleChat} className="absolute right-3 bottom-3 p-2 bg-[#059669] text-white rounded-xl shadow-lg hover:bg-[#047857] transition-all"><svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path d="M12 19l9 2-9-18-9 18 9-2zm0 0v-8" /></svg></button>
                   </div>
                 </div>
               </div>
            )}
          </div>
        )}
      </div>
    </Layout>
  );
};

export default App;

