                              <p className={`text-[10px] mt-3 font-black uppercase tracking-tighter ${msg.role === 'user' ? 'text-white/50' : 'text-slate-400'}`}>
                                {msg.timestamp.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
