                                className="w-10 h-10 rounded-xl bg-white border border-slate-100 shadow-md font-black text-slate-400 hover:text-emerald-500 transition-all active:scale-90"
                              >
                                +
                              </button>
                            </div>
                            <button 
                              onClick={() => removeHeir(h.id)} 
