          )}
        </div>
      </div>
      <div>
        <h3 className="text-xs font-black text-slate-400 uppercase tracking-[0.2em] mb-4 malayalam">അവകാശികൾ ({Object.values(heirCounts).reduce((acc, c) => acc + c, 0)})</h3>
        <div className="space-y-2">
           {Object.entries(heirCounts).filter(([_, count]) => count > 0).map(([type, count]) => {
              const theme = (HEIR_THEMES as any)[type] || HEIR_THEMES['Nephew'];
              return (
                <div key={type} className={`flex justify-between items-center p-3 ${theme.bg} rounded-xl border ${theme.border} group shadow-sm transition-all`}>
                  <div className="flex items-center gap-2">
                    <div className={`w-2 h-2 rounded-full ${theme.text.replace('text', 'bg')}`} />
                    <span className={`text-xs font-bold ${theme.text}`}>{type} <span className="opacity-60 ml-1">x{count}</span></span>
                  </div>
