                <div className="absolute top-0 right-0 w-32 h-32 bg-amber-100/50 rounded-full -mr-16 -mt-16 blur-3xl" />
                <h2 className="text-2xl md:text-3xl font-black mb-6 md:mb-8 malayalam border-b-4 border-amber-400 pb-4 text-amber-700 inline-block">ഫറായിദ് അറിവുകൾ</h2>
                <div className="space-y-6">
