                           </div>
                        </div>
                      ))}
                   </div>

                   <div className="relative group">
                      <div className="absolute -inset-1 bg-gradient-to-r from-emerald-500 to-teal-600 rounded-[1.5rem] md:rounded-[2.5rem] blur opacity-25 group-focus-within:opacity-50 transition-opacity" />
                      <div className="relative flex items-center bg-white rounded-[1.5rem] md:rounded-[2.5rem] border-2 border-slate-100 overflow-hidden shadow-inner">
