                          value={input} 
                          onChange={e => setInput(e.target.value)} 
                          onKeyDown={e => e.key === 'Enter' && !e.shiftKey && (e.preventDefault(), handleChat())} 
                          placeholder="ചോദിക്കൂ... (Ask anything)" 
                          className="w-full bg-transparent py-4 md:py-6 pl-6 md:pl-8 pr-16 md:pr-20 focus:outline-none resize-none h-16 md:h-20 text-base md:text-lg font-medium" 
                        />
                        <button 
                          onClick={handleChat} 
                          className="absolute right-2 md:right-4 top-1/2 -translate-y-1/2 w-10 h-10 md:w-14 md:h-14 bg-emerald-600 text-white rounded-xl md:rounded-2xl shadow-xl hover:bg-emerald-700 transition-all active:scale-90 flex items-center justify-center"
                        >
                          <svg className="w-5 h-5 md:w-8 md:h-8" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M12 19l9 2-9-18-9 18 9-2zm0 0v-8" /></svg>
                        </button>
                      </div>
                   </div>
                 </div>
               </div>
            )}
          </div>
        )}
      </div>
    </Layout>
  );
};

