{
  "name": "Faraid Malayalam - Islamic Inheritance Assistant",
  "description": "A fully offline specialized tool for Islamic inheritance based on Shafi'i Fiqh with Malayalam support.",
  "requestFramePermissions": []
}

import { HeirType } from '../types';

export interface LocalCalculationResult {
  eligible_heirs: string[];
  excluded_heirs: string[];
  shares: Record<string, string>;
  fraction_math: string;
  distribution_notes: string;
  validation: 'valid' | 'invalid';
  reason?: string;
}

/**
 * Core Faraid Logic Engine
 * Implements primary Shafi'i Fiqh rules for immediate and extended family.
 */
export const calculateFaraidLocally = (
  gender: 'Male' | 'Female',
  counts: Record<string, number>
): LocalCalculationResult => {
  const survivors = { ...counts };
  const shares: Record<string, number> = {};
  const labels: Record<string, string> = {};
  const excluded: string[] = [];

  // 1. Initial State Check
  const totalSurvivors = Object.values(survivors).reduce((a, b) => a + b, 0);
  if (totalSurvivors === 0) {
    return { validation: 'invalid', reason: 'അവകാശികളെ തിരഞ്ഞെടുക്കുക. (Please select heirs.)', eligible_heirs: [], excluded_heirs: [], shares: {}, fraction_math: '', distribution_notes: '' };
  }

  // Helper: check if any descendants exist
  const hasDescendants = (survivors['Son'] || 0) > 0 || (survivors['Daughter'] || 0) > 0 || (survivors['Grandson'] || 0) > 0 || (survivors['Granddaughter'] || 0) > 0;
  const hasMaleDescendants = (survivors['Son'] || 0) > 0 || (survivors['Grandson'] || 0) > 0;
  const totalSiblings = (survivors['FullBrother'] || 0) + (survivors['FullSister'] || 0) + (survivors['ConsanguineBrother'] || 0) + (survivors['ConsanguineSister'] || 0) + (survivors['UterineBrother'] || 0) + (survivors['UterineSister'] || 0);

  // 2. Blocking Rules (Hujub)
  const block = (heir: string) => {
    if (survivors[heir] > 0) {
      excluded.push(heir);
      survivors[heir] = 0;
    }
  };

  if ((survivors['Son'] || 0) > 0) {
    ['Grandson', 'Granddaughter', 'FullBrother', 'FullSister', 'ConsanguineBrother', 'ConsanguineSister', 'UterineBrother', 'UterineSister', 'Nephew', 'PaternalNephew', 'FullNephewSon', 'PaternalNephewSon', 'PaternalUncle', 'PaternalPaternalUncle', 'FullCousin', 'PaternalCousin'].forEach(block);
  }
  if ((survivors['Father'] || 0) > 0) {
    ['PaternalGrandfather', 'FullBrother', 'FullSister', 'ConsanguineBrother', 'ConsanguineSister', 'UterineBrother', 'UterineSister', 'Nephew', 'PaternalNephew', 'PaternalUncle'].forEach(block);
  }
  if ((survivors['Mother'] || 0) > 0) {
    ['PaternalGrandmother', 'MaternalGrandmother'].forEach(block);
  }
  if ((survivors['FullBrother'] || 0) > 0) {
    ['ConsanguineBrother', 'ConsanguineSister', 'Nephew', 'PaternalNephew', 'PaternalUncle'].forEach(block);
  }

  // 3. Fixed Share Assignment (Zawil Furud)

  // Spouse
  if (gender === 'Female' && survivors['Husband'] > 0) {
    shares['Husband'] = hasDescendants ? 1/4 : 1/2;
  }
  if (gender === 'Male' && survivors['Wife'] > 0) {
    shares['Wife'] = hasDescendants ? 1/8 : 1/4;
  }

  // Parents
  if (survivors['Father'] > 0) {
    shares['Father'] = hasMaleDescendants ? 1/6 : 0; // If no male descendants, Father is Asaba (handled later)
  }
  if (survivors['Mother'] > 0) {
    if (hasDescendants || totalSiblings >= 2) {
      shares['Mother'] = 1/6;
    } else {
      shares['Mother'] = 1/3;
    }
  }

  // Daughters (if no sons)
  if ((survivors['Daughter'] || 0) > 0 && (survivors['Son'] || 0) === 0) {
    shares['Daughter'] = survivors['Daughter'] === 1 ? 1/2 : 2/3;
  }

  // Uterine Siblings
  if ((survivors['UterineBrother'] || 0) + (survivors['UterineSister'] || 0) > 0 && !hasDescendants && (survivors['Father'] || 0) === 0) {
    const count = (survivors['UterineBrother'] || 0) + (survivors['UterineSister'] || 0);
    const totalUterineShare = count === 1 ? 1/6 : 1/3;
    if (survivors['UterineBrother'] > 0) shares['UterineBrother'] = totalUterineShare * (survivors['UterineBrother'] / count);
    if (survivors['UterineSister'] > 0) shares['UterineSister'] = totalUterineShare * (survivors['UterineSister'] / count);
  }

  // 4. Residuary Allocation (Asaba)
  let currentTotalFixed = Object.values(shares).reduce((a, b) => a + b, 0);
  let residue = Math.max(0, 1 - currentTotalFixed);

  // Priorities for Asaba
  if (residue > 0) {
    if ((survivors['Son'] || 0) > 0 || (survivors['Daughter'] || 0) > 0) {
      // Daughters become Asaba with Sons (2:1)
      const maleParts = (survivors['Son'] || 0) * 2;
      const femaleParts = (survivors['Daughter'] || 0);
      const totalParts = maleParts + femaleParts;
      if (survivors['Son'] > 0) shares['Son'] = residue * (maleParts / totalParts);
      if (survivors['Daughter'] > 0) shares['Daughter'] = (shares['Daughter'] || 0) + (residue * (femaleParts / totalParts));
      residue = 0;
    } else if (survivors['Father'] > 0 && !hasMaleDescendants) {
      shares['Father'] = (shares['Father'] || 0) + residue;
      residue = 0;
    } else if ((survivors['FullBrother'] || 0) > 0 || (survivors['FullSister'] || 0) > 0) {
      const maleParts = (survivors['FullBrother'] || 0) * 2;
      const femaleParts = (survivors['FullSister'] || 0);
      const totalParts = maleParts + femaleParts;
      if (survivors['FullBrother'] > 0) shares['FullBrother'] = residue * (maleParts / totalParts);
      if (survivors['FullSister'] > 0) shares['FullSister'] = residue * (femaleParts / totalParts);
      residue = 0;
    }
  }

  // 5. Final Normalization (Aul/Radd Check)
  let finalTotal = Object.values(shares).reduce((a, b) => a + b, 0);

  // Convert decimals to readable fractions for display
  const toFraction = (val: number) => {
    if (val === 0) return "0";
    if (Math.abs(val - 0.5) < 0.01) return "1/2";
    if (Math.abs(val - 0.25) < 0.01) return "1/4";
    if (Math.abs(val - 0.125) < 0.01) return "1/8";
    if (Math.abs(val - 0.333) < 0.02) return "1/3";
    if (Math.abs(val - 0.666) < 0.02) return "2/3";
    if (Math.abs(val - 0.166) < 0.02) return "1/6";
    return val.toFixed(3);
  };

  const finalSharesStr: Record<string, string> = {};
  Object.entries(shares).forEach(([k, v]) => {
    if (v > 0) finalSharesStr[k] = toFraction(v);
  });

  return {
    eligible_heirs: Object.keys(finalSharesStr),
    excluded_heirs: excluded,
    shares: finalSharesStr,
    fraction_math: `ആകെ ഓഹരികൾ കണക്കാക്കുന്നു... (Calculating total parts...)\nZawil Furud Total: ${currentTotalFixed.toFixed(3)}\nResidue: ${residue.toFixed(3)}`,
    distribution_notes: "ഈ കണക്ക് ഷാഫി മദ്ഹബ് പ്രകാരമുള്ള അടിസ്ഥാന നിയമങ്ങൾ അടിസ്ഥാനമാക്കിയുള്ളതാണ്. സങ്കീർണ്ണമായ കേസുകളിൽ പണ്ഡിതസഹായം തേടുക.",
    validation: 'valid'
  };
};

