  useEffect(() => {
    if (scrollRef.current) scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
  }, [messages, viewMode, hasStarted]);

  useEffect(() => {
    if (calcResult) {
      setVisualizeTrigger(false);
      setTimeout(() => setVisualizeTrigger(true), 100);
