  }, [calcResult]);

  const handleChat = () => {
    if (!input.trim()) return;
    const userMsg: Message = { id: Date.now().toString(), role: 'user', text: input, timestamp: new Date() };
    setMessages(prev => [...prev, userMsg]);
    setInput('');

    // Offline Local Counselor Logic
    let responseText = "ക്ഷമിക്കണം, ഇതിനെക്കുറിച്ച് എനിക്ക് ഇപ്പോൾ കൂടുതൽ വ്യക്തത നൽകാൻ കഴിയില്ല. അടുത്ത ഘട്ടത്തിലേക്ക് പോകാൻ ദയവായി വിവരങ്ങൾ നൽകുക.";
    const lowerInput = input.toLowerCase();

    if (lowerInput.includes("hai") || lowerInput.includes("hello") || lowerInput.includes("assalamu")) {
      responseText = "വഅലൈക്കുമുസ്സലാം! നിങ്ങൾക്ക് എന്ത് സഹായമാണ് വേണ്ടത്?";
    } else if (step === AppStep.ESTATE) {
      responseText = "ആദ്യമായി മരണപ്പെട്ട വ്യക്തിയുടെ ആസ്തിയും ബാധ്യതകളും കൃത്യമായി രേഖപ്പെടുത്തുക. ആകെ തുകയിൽ നിന്ന് കടങ്ങളും വസിയത്തും സംസ്കാര ചിലവും കുറച്ചതിന് ശേഷമാണ് ഓഹരി കണക്കാക്കുക.";
    } else if (step === AppStep.DECEASED_INFO) {
      responseText = "മരണപ്പെട്ട വ്യക്തി പുരുഷനാണോ സ്ത്രീയാണോ എന്ന് തിരഞ്ഞെടുക്കുക. ഇതനുസരിച്ചാണ് ഭർത്താവ്/ഭാര്യ എന്നിവരുടെ ഓഹരികൾ മാറുന്നത്.";
    } else if (step === AppStep.HEIRS) {
      responseText = "ജീവനോടുള്ള അവകാശികളെ മാത്രം ഇവിടെ ചേർക്കുക. ഒരാൾക്ക് ഓഹരിയുണ്ടോ എന്നറിയാൻ ആ പേരിന് അടുത്തുള്ള 'i' ബട്ടൺ അമർത്തുക.";
    }

    setTimeout(() => {
      setMessages(prev => [...prev, { id: Date.now().toString(), role: 'model', text: responseText, timestamp: new Date() }]);
    }, 500);
  };

  const performCalculation = () => {
    setIsCalculating(true);
    // Add small delay to simulate processing for better UX
    setTimeout(() => {
      const result = calculateFaraidLocally(deceasedGender || 'Male', heirCounts);
      setCalcResult(result);
      setIsCalculating(false);
