                             </div>
                             <div className="flex items-end justify-between border-t border-black/5 pt-4">
                               <p className={`text-2xl font-serif font-black ${theme.text}`}>{showPercentage ? `${(val * 100).toFixed(1)}%` : share}</p>
                               {netEstate > 0 && <p className={`text-base font-black ${theme.text}`}>₹{(val * netEstate).toLocaleString()}</p>}
                             </div>
                           </div>
                         );
                       })}
                     </div>

                     <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
                       <div className="p-6 bg-amber-50 rounded-3xl border-2 border-amber-100">
