                         <p className="text-sm font-medium text-emerald-900">{calcResult.distribution_notes}</p>
                       </div>
                     </div>
                   </div>
                 )}

                 <div className="bg-white border-2 border-slate-100 p-6 md:p-10 rounded-3xl md:rounded-[4rem] space-y-6 shadow-2xl">
                   <div className="flex items-center justify-between"><h4 className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Local Assistant</h4></div>
                   <div ref={scrollRef} className="h-[300px] overflow-y-auto space-y-4 pr-2 custom-scrollbar">
                      {messages.map((msg, i) => (
                        <div key={i} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}>
                           <div className={`max-w-[90%] p-4 rounded-2xl shadow-md ${msg.role === 'user' ? 'bg-gradient-to-br from-emerald-500 to-teal-700 text-white' : 'bg-slate-50 text-slate-800 border border-slate-200'}`}>
                              <p className="text-sm malayalam whitespace-pre-wrap leading-relaxed">{msg.text}</p>
                           </div>
                        </div>
                      ))}
                   </div>
                   <div className="relative flex items-center bg-white rounded-2xl border-2 border-slate-100 overflow-hidden shadow-inner">
                      <textarea value={input} onChange={e => setInput(e.target.value)} onKeyDown={e => e.key === 'Enter' && !e.shiftKey && (e.preventDefault(), handleChat())} placeholder="ചോദിക്കൂ... (Ask anything)" className="w-full bg-transparent py-4 px-6 focus:outline-none resize-none h-16 text-base" />
                      <button onClick={handleChat} className="absolute right-2 top-1/2 -translate-y-1/2 w-10 h-10 bg-emerald-600 text-white rounded-xl shadow-xl flex items-center justify-center"><svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M12 19l9 2-9-18-9 18 9-2zm0 0v-8" /></svg></button>
                   </div>
                 </div>
               </div>
            )}
          </div>
        )}
      </div>
    </Layout>
  );
};

