// ===========================
// ISLAMIC INHERITANCE ENGINE
// Frontend Only - No Backend
// ===========================

// RELATIVE KEYS (SUPPORTED 29)
const RELS = {
  HUSBAND: "husband",
  WIVES: "wives",
  SONS: "sons",
  DAUGHTERS: "daughters",
  SONS_SONS: "sons_sons",
  SONS_DAUGHTERS: "sons_daughters",
  FATHER: "father",
  MOTHER: "mother",
  GF_FATHER: "grandfather_father",
  GM_FATHER: "grandmother_father",
  GM_MOTHER: "grandmother_mother",
  FULL_BRO: "full_brothers",
  FULL_SIS: "full_sisters",
  PAT_BRO: "paternal_brothers",
  PAT_SIS: "paternal_sisters",
  MAT_BRO: "maternal_brothers",
  MAT_SIS: "maternal_sisters"
};

// HELPER
const exists = (obj, key) => (obj[key] || 0) > 0;

// MAIN ENGINE
function calcInheritance(input) {
  let result = {};
  let blocked = {};
  let furud = {};
  let residue = 1.0;

  // INITIAL DEFAULTS
  Object.values(RELS).forEach(k => {
    result[k] = 0;
    blocked[k] = false;
  });

  // ================
  // 1. BLOCKING LOGIC
  // ================

  // Sons block siblings/collaterals
  if (exists(input, RELS.SONS)) {
    [
      RELS.FULL_BRO, RELS.FULL_SIS,
      RELS.PAT_BRO, RELS.PAT_SIS
    ].forEach(k => blocked[k] = true);
  }

  // Father blocks grandfather + collaterals
  if (exists(input, RELS.FATHER)) {
    blocked[RELS.GF_FATHER] = true;
    [
      RELS.FULL_BRO, RELS.PAT_BRO,
      RELS.FULL_SIS, RELS.PAT_SIS
    ].forEach(k => blocked[k] = true);
  }

  // Full brother blocks paternal brother
  if (exists(input, RELS.FULL_BRO)) {
    blocked[RELS.PAT_BRO] = true;
  }

  // Full sister blocks paternal sister (furud case)
  if (exists(input, RELS.FULL_SIS)) {
    blocked[RELS.PAT_SIS] = true;
  }

  // ==========================
  // 2. FIXED SHARE (FURUD)
  // ==========================

  // Husband
  if (exists(input, RELS.HUSBAND)) {
    if (exists(input, RELS.SONS) || exists(input, RELS.DAUGHTERS)) {
      furud[RELS.HUSBAND] = 1/4;
    } else {
      furud[RELS.HUSBAND] = 1/2;
    }
  }

  // Wives
  if (exists(input, RELS.WIVES)) {
    if (exists(input, RELS.SONS) || exists(input, RELS.DAUGHTERS)) {
      furud[RELS.WIVES] = 1/8;
    } else {
      furud[RELS.WIVES] = 1/4;
    }
  }

  // Mother
  if (exists(input, RELS.MOTHER)) {
    if (
      exists(input, RELS.SONS) ||
      exists(input, RELS.DAUGHTERS) ||
      exists(input, RELS.FULL_BRO) ||
      exists(input, RELS.FULL_SIS) ||
      exists(input, RELS.PAT_BRO) ||
      exists(input, RELS.PAT_SIS)
    ) {
      furud[RELS.MOTHER] = 1/6;
    } else {
      furud[RELS.MOTHER] = 1/3;
    }
  }

  // Father
  if (exists(input, RELS.FATHER)) {
    if (exists(input, RELS.SONS) || exists(input, RELS.DAUGHTERS)) {
      furud[RELS.FATHER] = 1/6; // rest becomes asaba
    }
  }

  // Daughter
  if (exists(input, RELS.DAUGHTERS)) {
    if (!exists(input, RELS.SONS)) {
      if (input[RELS.DAUGHTERS] === 1) {
        furud[RELS.DAUGHTERS] = 1/2;
      } else {
        furud[RELS.DAUGHTERS] = 2/3;
      }
    }
  }

  // Maternal siblings
  const matCount = (input[RELS.MAT_BRO] || 0) + (input[RELS.MAT_SIS] || 0);
  if (matCount > 0) {
    if (matCount === 1) {
      furud["maternal_siblings"] = 1/6;
    } else {
      furud["maternal_siblings"] = 1/3;
    }
  }

  // ============================
  // 3. APPLY FURUD & REDUCE RESIDUE
  // ============================

  Object.keys(furud).forEach(key => {
    if (!blocked[key]) {
      let share = furud[key];
      result[key] = share;
      residue -= share;
    }
  });

  // ============================
  // 4. ASABA DISTRIBUTION
  // ============================

  // Sons + daughters (2:1 rule)
  if (exists(input, RELS.SONS) && exists(input, RELS.DAUGHTERS)) {
    let m = input[RELS.SONS];
    let f = input[RELS.DAUGHTERS];
    let total = (m * 2) + f;

    result[RELS.SONS] = (residue * 2 * m) / total;
    result[RELS.DAUGHTERS] = (residue * f) / total;
    residue = 0;
  }

  // Sons only
  else if (exists(input, RELS.SONS)) {
    result[RELS.SONS] = residue;
    residue = 0;
  }

  // Father asaba (when furud given = 1/6)
  else if (exists(input, RELS.FATHER)) {
    if (furud[RELS.FATHER] === 1/6) {
      result[RELS.FATHER] += residue;
      residue = 0;
    } else {
      result[RELS.FATHER] = residue;
      residue = 0;
    }
  }

  return { shares: result, blocked, residue: residue.toFixed(4) };
}

// EXPORT MODULE
window.calcInheritance = calcInheritance;
window.RELS = RELS;

