  if (totalSurvivors === 0) {
    return {
      validation: 'invalid',
      reason: 'അവകാശികളെ തിരഞ്ഞെടുക്കുക. (Please select heirs.)',
      eligible_heirs: [],
      excluded_heirs: [],
      shares: {},
      fraction_math: '',
      distribution_notes: ''
    };
  }

