  const SIBLINGS_ALL = [
    'FullBrother', 'FullSister', 
    'ConsanguineBrother', 'ConsanguineSister', 
    'UterineBrother', 'UterineSister'
  ];

  const EXTENDED_ALL = [
    'Nephew', 'PaternalNephew', 
    'FullNephewSon', 'PaternalNephewSon', 
    'PaternalUncle', 'PaternalPaternalUncle', 
    'FullCousin', 'PaternalCousin', 
    'FullCousinSon', 'PaternalCousinSon', 
    'FullCousinGrandson', 'PaternalCousinGrandson'
  ];

  // Helper flags
  const hasDescendants = (survivors['Son'] || 0) > 0 || (survivors['Daughter'] || 0) > 0 || (survivors['Grandson'] || 0) > 0 || (survivors['Granddaughter'] || 0) > 0;
  const hasMaleDescendants = (survivors['Son'] || 0) > 0 || (survivors['Grandson'] || 0) > 0;
  const totalSiblingsCount = (survivors['FullBrother'] || 0) + (survivors['FullSister'] || 0) + (survivors['ConsanguineBrother'] || 0) + (survivors['ConsanguineSister'] || 0) + (survivors['UterineBrother'] || 0) + (survivors['UterineSister'] || 0);

  // 2. Blocking Rules (Hujub - Exclusion)
  const blockHeirs = (list: string[]) => {
    list.forEach(heir => {
      if ((survivors[heir] || 0) > 0) {
        excluded.push(heir);
        survivors[heir] = 0;
      }
    });
  };

  // --- PRIMARY BLOCKERS ---

  // SON: Blocks all lower descendants, all siblings, and all extended collaterals.
  if ((survivors['Son'] || 0) > 0) {
    blockHeirs(['Grandson', 'Granddaughter', ...SIBLINGS_ALL, ...EXTENDED_ALL]);
  }

  // GRANDSON: Blocks all lower descendants and all siblings/extended (if no Son).
  if ((survivors['Grandson'] || 0) > 0) {
