  // FATHER: Blocks Paternal Grandfather and ALL siblings and ALL extended collaterals.
  if ((survivors['Father'] || 0) > 0) {
    blockHeirs(['PaternalGrandfather', ...SIBLINGS_ALL, ...EXTENDED_ALL]);
  }

