  // MOTHER: Blocks all grandmothers.
  if ((survivors['Mother'] || 0) > 0) {
    blockHeirs(['PaternalGrandmother', 'MaternalGrandmother']);
  }

  // PATERNAL GRANDFATHER: Blocks Uterine Siblings and lower collaterals.
  if ((survivors['PaternalGrandfather'] || 0) > 0) {
    blockHeirs(['UterineBrother', 'UterineSister']);
  }

  // FULL BROTHER: Blocks Consanguine siblings and all extended collaterals (nephews, uncles, etc.).
  if ((survivors['FullBrother'] || 0) > 0) {
    blockHeirs(['ConsanguineBrother', 'ConsanguineSister', ...EXTENDED_ALL]);
  }

  // CONSANGUINE BROTHER: Blocks all extended collaterals (nephews, uncles, etc.).
  if ((survivors['ConsanguineBrother'] || 0) > 0) {
    blockHeirs(EXTENDED_ALL);
  }

  // UTERINE SIBLINGS: Blocked by any descendant or male ascendant.
  if (hasDescendants || (survivors['Father'] || 0) > 0 || (survivors['PaternalGrandfather'] || 0) > 0) {
