  // SPOUSE
  if (gender === 'Female' && (survivors['Husband'] || 0) > 0) {
    shares['Husband'] = hasDescendants ? 1/4 : 1/2;
  }
  if (gender === 'Male' && (survivors['Wife'] || 0) > 0) {
    shares['Wife'] = hasDescendants ? 1/8 : 1/4;
  }

  // PARENTS
  if ((survivors['Father'] || 0) > 0) {
    // If male descendants exist, Father gets fixed 1/6. 
    // If no male descendants, Father is Asaba (handled in step 4).
    shares['Father'] = hasMaleDescendants ? 1/6 : 0; 
  }
  if ((survivors['Mother'] || 0) > 0) {
    if (hasDescendants || totalSiblingsCount >= 2) {
      shares['Mother'] = 1/6;
    } else {
      shares['Mother'] = 1/3;
    }
  }

  // DAUGHTERS (Fixed share if no Son)
  if ((survivors['Daughter'] || 0) > 0 && (survivors['Son'] || 0) === 0) {
    shares['Daughter'] = (survivors['Daughter'] || 0) === 1 ? 1/2 : 2/3;
  }

  // UTERINE SIBLINGS (Blocked check already done in Hujub)
  if ((survivors['UterineBrother'] || 0) > 0 || (survivors['UterineSister'] || 0) > 0) {
    const count = (survivors['UterineBrother'] || 0) + (survivors['UterineSister'] || 0);
    const totalUterineShare = count === 1 ? 1/6 : 1/3;
    if (survivors['UterineBrother'] > 0) shares['UterineBrother'] = totalUterineShare * (survivors['UterineBrother'] / count);
    if (survivors['UterineSister'] > 0) shares['UterineSister'] = totalUterineShare * (survivors['UterineSister'] / count);
  }

  // 4. Residuary Allocation (Asaba)
  let currentTotalFixed = Object.values(shares).reduce((a, b) => a + b, 0);
  let residue = Math.max(0, 1 - currentTotalFixed);

  if (residue > 0) {
    // ASABA PRIORITIES
    // A: Children
    if ((survivors['Son'] || 0) > 0 || (survivors['Daughter'] || 0) > 0) {
      const maleParts = (survivors['Son'] || 0) * 2;
      const femaleParts = (survivors['Daughter'] || 0);
      const totalParts = maleParts + femaleParts;
      if (totalParts > 0) {
        if (survivors['Son'] > 0) shares['Son'] = (shares['Son'] || 0) + (residue * (maleParts / totalParts));
        if (survivors['Daughter'] > 0) shares['Daughter'] = (shares['Daughter'] || 0) + (residue * (femaleParts / totalParts));
        residue = 0;
      }
    } 
    // B: Father (if no male descendants)
    else if ((survivors['Father'] || 0) > 0 && !hasMaleDescendants) {
      shares['Father'] = (shares['Father'] || 0) + residue;
      residue = 0;
    } 
    // C: Full Siblings
    else if ((survivors['FullBrother'] || 0) > 0 || (survivors['FullSister'] || 0) > 0) {
      const maleParts = (survivors['FullBrother'] || 0) * 2;
      const femaleParts = (survivors['FullSister'] || 0);
      const totalParts = maleParts + femaleParts;
      if (totalParts > 0) {
        if (survivors['FullBrother'] > 0) shares['FullBrother'] = (shares['FullBrother'] || 0) + (residue * (maleParts / totalParts));
        if (survivors['FullSister'] > 0) shares['FullSister'] = (shares['FullSister'] || 0) + (residue * (femaleParts / totalParts));
        residue = 0;
      }
    }
    // D: Consanguine Siblings
    else if ((survivors['ConsanguineBrother'] || 0) > 0 || (survivors['ConsanguineSister'] || 0) > 0) {
      const maleParts = (survivors['ConsanguineBrother'] || 0) * 2;
      const femaleParts = (survivors['ConsanguineSister'] || 0);
      const totalParts = maleParts + femaleParts;
      if (totalParts > 0) {
        if (survivors['ConsanguineBrother'] > 0) shares['ConsanguineBrother'] = (shares['ConsanguineBrother'] || 0) + (residue * (maleParts / totalParts));
        if (survivors['ConsanguineSister'] > 0) shares['ConsanguineSister'] = (shares['ConsanguineSister'] || 0) + (residue * (femaleParts / totalParts));
        residue = 0;
      }
    }
  }

  // 5. Final Formatting
  const toFraction = (val: number) => {
    if (val === 0) return "0";
    if (Math.abs(val - 0.5) < 0.001) return "1/2";
    if (Math.abs(val - 0.25) < 0.001) return "1/4";
    if (Math.abs(val - 0.125) < 0.001) return "1/8";
    if (Math.abs(val - 0.3333) < 0.01) return "1/3";
    if (Math.abs(val - 0.6666) < 0.01) return "2/3";
    if (Math.abs(val - 0.1666) < 0.01) return "1/6";
    if (Math.abs(val - 0.0833) < 0.01) return "1/12";
    return val.toFixed(4);
  };

  const finalSharesStr: Record<string, string> = {};
  Object.entries(shares).forEach(([k, v]) => {
    if (v > 0) finalSharesStr[k] = toFraction(v);
  });

  return {
    eligible_heirs: Object.keys(finalSharesStr),
    excluded_heirs: excluded,
    shares: finalSharesStr,
    fraction_math: `ഹജ്ബ് (Blocking) വിവരങ്ങൾ:\n${excluded.length > 0 ? excluded.join(', ') + ' എന്നിവർക്ക് ഓഹരി ലഭിക്കില്ല.' : 'ഒഴിവാക്കപ്പെട്ടവരില്ല.'}\n\nഓഹരി വിതരണ അനുപാതം:\nZawil Furud: ${currentTotalFixed.toFixed(4)}\nAsaba: ${residue.toFixed(4)}`,
    distribution_notes: "ഈ കണക്ക് ഷാഫി മദ്ഹബ് പ്രകാരമുള്ള അടിസ്ഥാന അനന്തരാവകാശ നിയമങ്ങൾ (Hujub, Furud, Asaba) പാലിച്ചാണ് തയ്യാറാക്കിയിരിക്കുന്നത്. മക്കൾ, പിതാവ് എന്നിവരുടെ സാന്നിധ്യത്തിൽ സഹോദരങ്ങൾ ഒഴിവാക്കപ്പെടും.",
    validation: 'valid'
  };
};

