                           return <div key={heir} className={`${theme.barBg} h-full transition-all duration-1000 ease-out border-r border-white/20 last:border-r-0`} style={{ width: visualizeTrigger ? `${value * 100}%` : '0%' }} title={heir} />;
                         })}
                       </div>
                     </div>

                     <div className="grid grid-cols-1 sm:grid-cols-2 gap-8">
                       {Object.entries(calcResult.shares).map(([heir, share]) => {
