                           <div key={heir} className={`${theme.bg} p-10 rounded-[3rem] border-2 ${theme.border} shadow-xl relative overflow-hidden group hover:scale-[1.03] transition-all`}>
                             <div className="flex justify-between items-start mb-8">
                               <div className="min-w-0">
                                 <p className="text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1 truncate">{heir}</p>
                                 <p className={`text-2xl font-black malayalam ${theme.text}`}>{HEIR_LABELS[heir as HeirType]?.ml || heir}</p>
                               </div>
