                           // Fix: Cast 'share' to string to resolve 'unknown' type and handle fraction parsing for visualization
                           const s = share as string;
                           const value = s.includes('/') 
                             ? (parseInt(s.split('/')[0], 10) / parseInt(s.split('/')[1], 10)) 
                             : parseFloat(s);
