                         const s = share as string;
                         const val = s.includes('/') 
                           ? (parseInt(s.split('/')[0], 10) / parseInt(s.split('/')[1], 10)) 
                           : parseFloat(s);
                         const theme = HEIR_THEMES[heir] || HEIR_THEMES['default'];
                         return (
                           <div key={heir} className={`${theme.bg} p-10 rounded-[3rem] border-2 ${theme.border} shadow-xl relative overflow-hidden group hover:scale-[1.03] transition-all`}>
