                                 <div className="text-right">
                                   <p className={`text-2xl font-black ${theme.text}`}>₹{(val * netEstate).toLocaleString()}</p>
                                   <p className="text-[8px] font-black text-slate-400 uppercase tracking-widest">Amount</p>
                                 </div>
                               )}
                             </div>
                           </div>
