                     <div className="grid grid-cols-1 lg:grid-cols-2 gap-8 pt-10 border-t border-slate-50">
                       <div className="p-10 bg-slate-50 rounded-[3rem] border border-slate-200 shadow-inner group transition-all">
                         <h4 className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-6 malayalam">കണക്ക് വിവരങ്ങൾ (Logic Math)</h4>
                         <p className="text-sm font-medium whitespace-pre-line text-slate-700 leading-relaxed italic opacity-80 group-hover:opacity-100">{calcResult.fraction_math}</p>
                       </div>
                       <div className="p-10 bg-emerald-50 rounded-[3rem] border border-emerald-100 shadow-inner group transition-all">
                         <h4 className="text-[10px] font-black text-emerald-800 uppercase tracking-widest mb-6 malayalam">വിശദീകരണം (Fiqh Notes)</h4>
                         <p className="text-sm font-bold text-emerald-900 leading-relaxed malayalam">{calcResult.distribution_notes}</p>
                       </div>
                     </div>
                   </div>
                 )}

                 <div className="bg-white border-2 border-slate-100 p-8 md:p-14 rounded-[4rem] space-y-10 shadow-2xl relative overflow-hidden">
                   <div className="absolute top-0 left-0 w-full h-3 bg-gradient-to-r from-emerald-500 via-amber-500 to-rose-500" />
                   <div className="flex items-center justify-between">
                     <h4 className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Assistant Support</h4>
                     <div className="flex gap-2">
                       <div className="w-3 h-3 rounded-full bg-emerald-400 animate-pulse" />
                     </div>
                   </div>

                   <div ref={scrollRef} className="h-[400px] overflow-y-auto space-y-6 pr-4 custom-scrollbar">
                      {messages.map((msg, i) => (
                        <div key={i} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'} animate-in slide-in-from-bottom-2 duration-300`}>
                           <div className={`max-w-[85%] p-6 rounded-[2.5rem] shadow-md border ${msg.role === 'user' ? 'bg-slate-900 text-white border-slate-800 rounded-tr-none' : 'bg-slate-50 text-slate-800 border-slate-100 rounded-tl-none'}`}>
                              <p className="text-lg malayalam whitespace-pre-wrap leading-relaxed font-medium">{msg.text}</p>
                              <p className={`text-[9px] mt-4 font-black uppercase tracking-widest ${msg.role === 'user' ? 'text-slate-500' : 'text-slate-300'}`}>
                                {msg.timestamp.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                              </p>
                           </div>
                        </div>
                      ))}
                   </div>

                   <div className="relative group">
                      <div className="absolute -inset-1 bg-gradient-to-r from-emerald-600 to-amber-600 rounded-[2.5rem] blur opacity-10 group-focus-within:opacity-20 transition-all duration-500" />
                      <div className="relative flex items-center bg-slate-50 rounded-[2.5rem] border-2 border-slate-100 overflow-hidden shadow-inner group-focus-within:bg-white transition-all">
                        <textarea 
                          value={input} 
                          onChange={e => setInput(e.target.value)} 
                          onKeyDown={e => e.key === 'Enter' && !e.shiftKey && (e.preventDefault(), handleChat())} 
                          placeholder="ഇവിടെ ചോദിക്കൂ... (Ask anything)" 
                          className="w-full bg-transparent py-6 px-10 focus:outline-none resize-none h-20 text-lg malayalam font-medium" 
                        />
                        <button onClick={handleChat} className="mr-4 w-14 h-14 bg-slate-900 text-white rounded-[1.5rem] shadow-xl hover:bg-emerald-600 transition-all active:scale-90 flex items-center justify-center shrink-0">
                          <svg className="w-7 h-7" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M12 19l9 2-9-18-9 18 9-2zm0 0v-8" /></svg>
                        </button>
                      </div>
                   </div>
                 </div>
               </div>
            )}
          </div>
        )}
      </div>
    </Layout>
  );
};

export default App;

