{
  "name": "Farāid Calculator",
  "description": "A professional Islamic inheritance calculator for Sharia-compliant estate distribution.",
  "requestFramePermissions": []
}

export enum AppStep {
  WELCOME = 'WELCOME',
  SCRIPTURE = 'SCRIPTURE',
  SELECTION = 'SELECTION',
  RESULT = 'RESULT'
}

export type HeirType = 
  | 'Husband' | 'Wife' | 'Son' | 'Daughter' 
  | 'Grandson' | 'Granddaughter' 
  | 'Father' | 'Mother' | 'Grandfather' 
  | 'Paternal Grandmother' | 'Maternal Grandmother'
  | 'Full Brother' | 'Full Sister' | 'Paternal Brother' 
  | 'Paternal Sister' | 'Maternal Brother' | 'Maternal Sister'
  | 'Full Nephew' | 'Paternal Nephew' | 'Full Nephew Son' 
  | 'Paternal Nephew Son' | 'Full Paternal Uncle' 
  | 'Paternal Paternal Uncle' | 'Full Cousin' | 'Paternal Cousin' 
  | 'Full Cousin Son' | 'Paternal Cousin Son' 
  | 'Full Cousin Grandson' | 'Paternal Cousin Grandson';

export interface Heir {
  type: HeirType;
  count: number;
}

export interface CalculationResult {
  shares: Record<string, string>;
  percentages: Record<string, string>;
  complex: boolean;
  warnings: string[];
}

import { Heir, CalculationResult, HeirType } from '../types';

export const calculateShares = (heirs: Heir[], deceasedGender: 'Male' | 'Female'): CalculationResult => {
  const result: CalculationResult = {
    shares: {},
    percentages: {},
    complex: false,
    warnings: []
  };

  const heirMap = heirs.reduce((acc, h) => {
    acc[h.type] = h.count;
    return acc;
  }, {} as Record<HeirType, number>);

  const hasChildren = (heirMap['Son'] || 0) > 0 || 
                      (heirMap['Daughter'] || 0) > 0 || 
                      (heirMap['Grandson'] || 0) > 0 || 
                      (heirMap['Granddaughter'] || 0) > 0;

  const hasSiblings = (heirMap['Full Brother'] || 0) + (heirMap['Full Sister'] || 0) + 
                      (heirMap['Paternal Brother'] || 0) + (heirMap['Paternal Sister'] || 0) + 
                      (heirMap['Maternal Brother'] || 0) + (heirMap['Maternal Sister'] || 0) >= 2;

  // Basic validation
  if (deceasedGender === 'Male' && heirMap['Husband']) {
    result.warnings.push("A male deceased cannot have a husband.");
  }
  if (deceasedGender === 'Female' && heirMap['Wife']) {
    result.warnings.push("A female deceased cannot have a wife.");
  }
  if ((heirMap['Wife'] || 0) > 4) {
    result.warnings.push("Max 4 wives allowed in Islamic law.");
  }

  // 1. Fixed Shares (Zawil Furud)
  let totalFixed = 0;

  // Husband
  if (deceasedGender === 'Female' && heirMap['Husband']) {
    const share = hasChildren ? 0.25 : 0.5;
    result.shares['Husband'] = hasChildren ? '1/4' : '1/2';
    result.percentages['Husband'] = `${share * 100}%`;
    totalFixed += share;
  }

  // Wife
  if (deceasedGender === 'Male' && heirMap['Wife']) {
    const share = hasChildren ? 0.125 : 0.25;
    result.shares['Wife'] = hasChildren ? '1/8' : '1/4';
    result.percentages['Wife'] = `${share * 100}%`;
    totalFixed += share;
  }

  // Father
  if (heirMap['Father']) {
    if (hasChildren) {
      result.shares['Father'] = '1/6';
      result.percentages['Father'] = '16.66%';
      totalFixed += 1/6;
    } else {
      result.shares['Father'] = 'Residue';
      result.percentages['Father'] = 'Asaba';
    }
  }

  // Mother
  if (heirMap['Mother']) {
    const shareValue = (hasChildren || hasSiblings) ? 1/6 : 1/3;
    result.shares['Mother'] = (hasChildren || hasSiblings) ? '1/6' : '1/3';
    result.percentages['Mother'] = (hasChildren || hasSiblings) ? '16.66%' : '33.33%';
    totalFixed += shareValue;
  }

  // Daughters (if no Sons)
  if (heirMap['Daughter'] && !heirMap['Son']) {
    const count = heirMap['Daughter'];
    if (count === 1) {
      result.shares['Daughter'] = '1/2';
      result.percentages['Daughter'] = '50%';
      totalFixed += 0.5;
    } else {
      result.shares['Daughters (all)'] = '2/3';
      result.percentages['Daughters (all)'] = '66.66%';
      totalFixed += 2/3;
    }
  }

  // 2. Residue (Asaba)
  const residue = Math.max(0, 1 - totalFixed);

  if (heirMap['Son']) {
    const sonCount = heirMap['Son'];
    const daughterCount = heirMap['Daughter'] || 0;
    const totalUnits = (sonCount * 2) + daughterCount;

    const perUnit = residue / totalUnits;
    if (residue > 0) {
      result.shares['Son'] = `${(perUnit * 2 * 100).toFixed(2)}% of Residue`;
      result.shares['Daughter'] = `${(perUnit * 100).toFixed(2)}% of Residue`;
      result.percentages['Son'] = 'Residue (2x)';
      result.percentages['Daughter'] = 'Residue (1x)';
    }
  }

  // Check if we hit complex cases
  const knownHeirs: HeirType[] = ['Husband', 'Wife', 'Son', 'Daughter', 'Father', 'Mother'];
  const hasExtended = heirs.some(h => !knownHeirs.includes(h.type));
  if (hasExtended || totalFixed > 1) {
    result.complex = true;
  }

  return result;
};

import React, { useState } from 'react';
import { AppStep, Heir, HeirType, CalculationResult } from './types';
import { calculateShares } from './logic/faraidEngine';

const CATEGORIES: Record<string, HeirType[]> = {
  "Core Family": ["Husband", "Wife", "Son", "Daughter", "Father", "Mother"],
  "Grandparents": ["Grandfather", "Paternal Grandmother", "Maternal Grandmother"],
  "Descendants": ["Grandson", "Granddaughter"],
  "Siblings": ["Full Brother", "Full Sister", "Paternal Brother", "Paternal Sister", "Maternal Brother", "Maternal Sister"],
  "Uncles & Cousins": ["Full Paternal Uncle", "Paternal Paternal Uncle", "Full Cousin", "Paternal Cousin"]
};

const App: React.FC = () => {
  const [step, setStep] = useState<AppStep>(AppStep.WELCOME);
  const [deceasedGender, setDeceasedGender] = useState<'Male' | 'Female'>('Male');
  const [heirs, setHeirs] = useState<Heir[]>([]);
  const [result, setResult] = useState<CalculationResult | null>(null);

  const updateHeirCount = (type: HeirType, delta: number) => {
    setHeirs(prev => {
      const existing = prev.find(h => h.type === type);
      if (existing) {
        const newCount = Math.max(0, existing.count + delta);
        if (newCount === 0) return prev.filter(h => h.type !== type);
        return prev.map(h => h.type === type ? { ...h, count: newCount } : h);
      } else if (delta > 0) {
        return [...prev, { type, count: 1 }];
      }
      return prev;
    });
  };

  const getHeirCount = (type: HeirType) => {
    return heirs.find(h => h.type === type)?.count || 0;
  };

  const handleCalculate = () => {
    const calcResult = calculateShares(heirs, deceasedGender);
    setResult(calcResult);
    setStep(AppStep.RESULT);
  };

  const reset = () => {
    setHeirs([]);
    setResult(null);
    setStep(AppStep.WELCOME);
  };

  // --- Screens ---

  if (step === AppStep.WELCOME) {
    return (
      <div className="min-h-screen bg-slate-950 flex flex-col items-center justify-center p-6 text-white text-center">
        <div className="w-20 h-20 bg-emerald-600 rounded-2xl flex items-center justify-center mb-8 shadow-xl shadow-emerald-500/20">
          <svg className="w-10 h-10" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 6.253v13m0-13C10.832 5.477 9.246 5 7.5 5S4.168 5.477 3 6.253v13C4.168 18.477 5.754 18 7.5 18s3.332.477 4.5 1.253m0-13C13.168 5.477 14.754 5 16.5 5c1.747 0 3.332.477 4.5 1.253v13C19.832 18.477 18.247 18 16.5 18c-1.746 0-3.332.477-4.5 1.253" />
          </svg>
        </div>
        <h1 className="text-4xl font-extrabold mb-4 tracking-tight">Farāid Calculator</h1>
        <p className="text-slate-400 max-w-sm mb-12 text-lg">Learn & calculate Islamic inheritance shares according to Quran and Sunnah.</p>
        <button 
          onClick={() => setStep(AppStep.SCRIPTURE)}
          className="w-full max-w-xs bg-emerald-600 hover:bg-emerald-500 py-4 rounded-xl font-bold text-lg transition-all active:scale-95 shadow-lg shadow-emerald-600/20"
        >
          Continue
        </button>
      </div>
    );
  }

  if (step === AppStep.SCRIPTURE) {
    return (
      <div className="min-h-screen bg-slate-50 flex flex-col items-center p-6 space-y-8 py-12">
        <div className="max-w-md w-full space-y-8">
          <div className="bg-white p-8 rounded-3xl shadow-sm border border-slate-100 text-center">
             <p className="arabic text-3xl mb-4 text-emerald-800">"تَعَلَّمُوا الْفَرَائِضَ وَعَلِّمُوهَا النَّاسَ"</p>
             <p className="malayalam text-slate-600 leading-relaxed font-medium">"ഫറാഇദ് (ഇസ്ലാമിക അവകാശവിഭാഗം) പഠിക്കൂ, അത് ആളുകളെ പഠിപ്പിക്കൂ."</p>
             <p className="text-xs text-slate-400 mt-4 font-bold tracking-widest uppercase italic">Hadith</p>
          </div>

          <div className="bg-white p-8 rounded-3xl shadow-sm border border-slate-100 text-center">
             <p className="arabic text-2xl mb-4 text-emerald-800 leading-loose">"يُوصِيكُمُ اللَّهُ فِي أَوْلَادِكُمْ لِلذَّكَرِ مِثْلُ حَظِّ الْأُنْثَيَيْنِ"</p>
             <p className="malayalam text-slate-600 leading-relaxed font-medium">"നിങ്ങളുടെ മക്കളെ സംബന്ധിച്ച് അല്ലാഹു നിങ്ങളെ ഉപദേശിക്കുന്നു; ആൺകുട്ടിക്ക് രണ്ട് പെൺകുട്ടികളുടെ ഓഹരിക്ക് തുല്യമായിരിക്കും."</p>
             <p className="text-xs text-slate-400 mt-4 font-bold tracking-widest uppercase italic">Quran 4:11</p>
          </div>
        </div>

        <button 
          onClick={() => setStep(AppStep.SELECTION)}
          className="w-full max-w-xs bg-slate-900 text-white py-4 rounded-xl font-bold text-lg transition-all active:scale-95 shadow-xl"
        >
          Open Calculator
        </button>
      </div>
    );
  }

  if (step === AppStep.SELECTION) {
    return (
      <div className="min-h-screen bg-slate-50 flex flex-col p-6 pb-24">
        <header className="mb-8">
          <h2 className="text-2xl font-black text-slate-900 mb-2">Select Relatives</h2>
          <p className="text-slate-500 text-sm">Select surviving family members of the deceased.</p>
        </header>

        <div className="space-y-6 mb-12">
          {/* Gender Select */}
          <div className="bg-white p-5 rounded-2xl border border-slate-100 shadow-sm">
            <p className="text-xs font-bold text-slate-400 uppercase tracking-widest mb-4">Deceased Gender</p>
            <div className="flex gap-4">
              <button 
                onClick={() => setDeceasedGender('Male')}
                className={`flex-1 py-3 rounded-xl font-bold transition-all ${deceasedGender === 'Male' ? 'bg-emerald-600 text-white shadow-md' : 'bg-slate-100 text-slate-600'}`}
              >
                Male
              </button>
              <button 
                onClick={() => setDeceasedGender('Female')}
                className={`flex-1 py-3 rounded-xl font-bold transition-all ${deceasedGender === 'Female' ? 'bg-emerald-600 text-white shadow-md' : 'bg-slate-100 text-slate-600'}`}
              >
                Female
              </button>
            </div>
          </div>

          {/* Categorized Heirs */}
          {Object.entries(CATEGORIES).map(([cat, types]) => (
            <div key={cat} className="space-y-3">
              <h3 className="text-sm font-black text-slate-400 uppercase tracking-widest ml-1">{cat}</h3>
              <div className="grid grid-cols-1 gap-3">
                {types.map(type => (
                  <div key={type} className="bg-white p-4 rounded-2xl border border-slate-100 flex items-center justify-between shadow-sm group">
                    <span className="font-semibold text-slate-700">{type}</span>
                    <div className="flex items-center gap-4 bg-slate-50 p-1 rounded-xl">
                      <button 
