                        -
                      </button>
                      <span className="w-6 text-center font-bold text-slate-900">{getHeirCount(type)}</span>
                      <button 
                        onClick={() => updateHeirCount(type, 1)}
                        className="w-8 h-8 rounded-lg bg-white shadow-sm flex items-center justify-center text-slate-400 hover:text-emerald-500 transition-colors"
                      >
                        +
                      </button>
                    </div>
                  </div>
                ))}
              </div>
            </div>
          ))}
        </div>

        {/* Footer Action */}
        <div className="fixed bottom-0 left-0 right-0 p-6 bg-white/80 backdrop-blur-md border-t border-slate-100 flex justify-center">
          <button 
            disabled={heirs.length === 0}
            onClick={handleCalculate}
            className="w-full max-w-md bg-emerald-600 disabled:bg-slate-300 text-white py-4 rounded-2xl font-black text-xl shadow-lg transition-all active:scale-95 flex items-center justify-center gap-3"
          >
            Calculate Shares
            <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 7l5 5m0 0l-5 5m5-5H6" />
            </svg>
          </button>
        </div>
      </div>
    );
  }

  if (step === AppStep.RESULT && result) {
    return (
      <div className="min-h-screen bg-slate-50 flex flex-col p-6 py-12">
        <header className="mb-10 text-center">
          <h2 className="text-3xl font-black text-slate-900 mb-2">Inheritance Results</h2>
          <p className="text-slate-500">Distribution according to Shariah rules.</p>
        </header>

        <div className="max-w-lg mx-auto w-full space-y-6 mb-12">
          {result.warnings.map((w, i) => (
            <div key={i} className="bg-rose-50 text-rose-600 p-4 rounded-2xl border border-rose-100 text-sm font-bold flex gap-3">
              <svg className="w-5 h-5 shrink-0" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z" />
              </svg>
              {w}
            </div>
          ))}

          {result.complex && (
            <div className="bg-amber-50 text-amber-700 p-6 rounded-3xl border border-amber-100 space-y-2 text-center">
              <p className="font-black text-lg">Complex Case</p>
              <p className="text-sm">Extended relatives or oversubscription (Aul) detected. Please consult a qualified Islamic scholar for final confirmation.</p>
            </div>
          )}

          <div className="bg-white p-2 rounded-[2.5rem] shadow-sm border border-slate-100">
            {Object.entries(result.shares).map(([type, share], i) => (
              <div 
                key={type} 
                className={`flex items-center justify-between p-6 ${i !== 0 ? 'border-t border-slate-50' : ''}`}
              >
                <div className="space-y-1">
                  <p className="font-bold text-slate-900 text-lg">{type}</p>
                  <p className="text-xs text-slate-400 font-black uppercase tracking-widest">{result.percentages[type] || 'Calculated'}</p>
