          <div className="p-6 bg-slate-100 rounded-3xl space-y-2">
            <p className="text-xs font-black text-slate-400 uppercase tracking-widest">Logic Notes</p>
            <p className="text-sm text-slate-600 leading-relaxed italic">
              Shares are calculated based on fixed Quranic portions (Zawil Furud) and residuary portions (Asaba). Complex interactions involving siblings or paternal relatives may require scholarly review.
            </p>
          </div>
        </div>

        <div className="flex justify-center pt-8">
          <button 
            onClick={reset}
            className="bg-slate-900 text-white px-10 py-4 rounded-xl font-bold transition-all active:scale-95"
          >
            Start New Calculation
          </button>
        </div>
      </div>
    );
  }

  return null;
};

