export type HeirType = keyof typeof HEIR_METADATA;

export interface Heir {
  type: HeirType;
  count: number;
}

export interface CalculationResult {
  shares: Array<{ label: string, fraction: string, percentage: string }>;
  complex: boolean;
  warnings: string[];
}

import { Heir, CalculationResult, HeirType, HEIR_METADATA } from '../types';

export const calculateShares = (heirs: Heir[], deceasedGender: 'Male' | 'Female'): CalculationResult => {
  const result: CalculationResult = {
    shares: [],
    complex: false,
    warnings: []
  };

  const heirMap = heirs.reduce((acc, h) => {
    acc[h.type] = h.count;
    return acc;
  }, {} as Record<HeirType, number>);

  const hasChildren = (heirMap['Son'] || 0) > 0 || 
                      (heirMap['Daughter'] || 0) > 0 || 
                      (heirMap['Grandson'] || 0) > 0 || 
                      (heirMap['Granddaughter'] || 0) > 0;

  const hasSiblings = ((heirMap['Full Brother'] || 0) + 
                       (heirMap['Full Sister'] || 0) + 
                       (heirMap['Paternal Brother'] || 0) + 
                       (heirMap['Paternal Sister'] || 0) + 
                       (heirMap['Maternal Brother'] || 0) + 
                       (heirMap['Maternal Sister'] || 0)) >= 2;

  // Basic validation
  if (deceasedGender === 'Male' && heirMap['Husband']) {
    result.warnings.push("പുരുഷനായ പരേതന് ഭർത്താവ് ഉണ്ടാകാൻ കഴിയില്ല.");
  }
  if (deceasedGender === 'Female' && heirMap['Wife']) {
    result.warnings.push("സ്ത്രീയായ പരേതയ്ക്ക് ഭാര്യ ഉണ്ടാകാൻ കഴിയില്ല.");
  }
  if ((heirMap['Wife'] || 0) > 4) {
    result.warnings.push("ഇസ്‌ലാമിക നിയമപ്രകാരം പരമാവധി 4 ഭാര്യമാർ മാത്രമേ അനുവദനീയമുള്ളൂ.");
  }

  // Detect Complex Cases
  const complexTriggers: HeirType[] = [
    'Grandson', 'Granddaughter', 'Grandfather', 'Paternal Grandmother', 'Maternal Grandmother',
    'Full Brother', 'Full Sister', 'Paternal Brother', 'Paternal Sister', 'Maternal Brother', 'Maternal Sister',
    'Full Nephew', 'Paternal Nephew', 'Full Nephew Son', 'Paternal Nephew Son', 'Full Paternal Uncle',
    'Paternal Paternal Uncle', 'Full Cousin', 'Paternal Cousin', 'Full Cousin Son', 'Paternal Cousin Son',
    'Full Cousin Grandson', 'Paternal Cousin Grandson'
  ];

  if (heirs.some(h => complexTriggers.includes(h.type))) {
    result.complex = true;
  }

  // 1. Fixed Shares (Zawil Furud) Logic

  // Husband
  if (deceasedGender === 'Female' && heirMap['Husband']) {
    const fraction = hasChildren ? '1/4' : '1/2';
    const percent = hasChildren ? '25%' : '50%';
    result.shares.push({ label: HEIR_METADATA['Husband'].ml, fraction, percentage: percent });
  }

  // Wife
  if (deceasedGender === 'Male' && heirMap['Wife']) {
    const fraction = hasChildren ? '1/8' : '1/4';
    const percent = hasChildren ? '12.5%' : '25%';
    result.shares.push({ label: HEIR_METADATA['Wife'].ml, fraction: `${fraction} (കൂട്ടായി)`, percentage: percent });
  }

  // Father
  if (heirMap['Father']) {
    if (hasChildren) {
      result.shares.push({ label: HEIR_METADATA['Father'].ml, fraction: '1/6', percentage: '16.66%' });
    } else {
      result.shares.push({ label: HEIR_METADATA['Father'].ml, fraction: 'ബാക്കി മുഴുവൻ', percentage: 'Asaba' });
    }
  }

  // Mother
  if (heirMap['Mother']) {
    const fraction = (hasChildren || hasSiblings) ? '1/6' : '1/3';
    const percent = (hasChildren || hasSiblings) ? '16.66%' : '33.33%';
    result.shares.push({ label: HEIR_METADATA['Mother'].ml, fraction, percentage: percent });
  }

  // Daughters
  if (heirMap['Daughter'] > 0) {
    if (heirMap['Son']) {
      result.shares.push({ label: 'പുത്രന്മാരും പുത്രിമാരും', fraction: 'ബാക്കി (2:1 അനുപാതം)', percentage: 'Asaba' });
    } else {
      if (heirMap['Daughter'] === 1) {
        result.shares.push({ label: 'പുത്രി', fraction: '1/2', percentage: '50%' });
      } else {
        result.shares.push({ label: 'പുത്രിമാർ', fraction: '2/3 (കൂട്ടായി)', percentage: '66.66%' });
      }
    }
  } else if (heirMap['Son']) {
    result.shares.push({ label: 'പുത്രന്മാർ', fraction: 'ബാക്കി മുഴുവൻ', percentage: 'Asaba' });
  }

  return result;
};

import React, { useState, useMemo } from 'react';
