import React, { useState, useMemo } from 'react';
import { AppStep, Heir, HeirType, CalculationResult, HEIR_METADATA } from './types';
import { calculateShares } from './logic/faraidEngine';
import { getGeminiCalculation } from './services/geminiService';

const App: React.FC = () => {
  const [step, setStep] = useState<AppStep>(AppStep.WELCOME);
  const [deceasedGender, setDeceasedGender] = useState<'Male' | 'Female'>('Male');
  const [heirs, setHeirs] = useState<Heir[]>([]);
  const [result, setResult] = useState<CalculationResult | null>(null);
  const [loading, setLoading] = useState(false);

  const heirCategories = useMemo(() => {
    const cats: Record<string, HeirType[]> = {};
    Object.entries(HEIR_METADATA).forEach(([type, meta]) => {
      if (!cats[meta.category]) cats[meta.category] = [];
      cats[meta.category].push(type as HeirType);
    });
    return cats;
  }, []);

  const updateHeirCount = (type: HeirType, delta: number) => {
    setHeirs(prev => {
      const existing = prev.find(h => h.type === type);
      if (existing) {
        const newCount = Math.max(0, existing.count + delta);
        if (newCount === 0) return prev.filter(h => h.type !== type);
        return prev.map(h => h.type === type ? { ...h, count: newCount } : h);
      } else if (delta > 0) {
        return [...prev, { type, count: 1 }];
      }
      return prev;
    });
  };

  const getHeirCount = (type: HeirType) => {
    return heirs.find(h => h.type === type)?.count || 0;
  };

  const handleCalculate = async () => {
    const calcResult = calculateShares(heirs, deceasedGender);

    if (calcResult.complex) {
      setLoading(true);
      setStep(AppStep.RESULT);
      try {
        const aiResult = await getGeminiCalculation(heirs, deceasedGender);
        setResult(aiResult);
      } catch (error) {
        console.error("Gemini calculation failed", error);
        setResult(calcResult);
      } finally {
        setLoading(false);
      }
    } else {
      setResult(calcResult);
      setStep(AppStep.RESULT);
    }
  };

  const reset = () => {
    setHeirs([]);
    setResult(null);
    setStep(AppStep.WELCOME);
    setLoading(false);
