          </div>
        </div>

        {!loading && (
          <div className="flex justify-center pt-14 pb-8">
            <button 
              onClick={reset}
              className="bg-white border-2 border-slate-200 text-slate-900 px-12 py-4.5 rounded-2xl font-black text-lg transition-all active:scale-95 shadow-lg hover:border-emerald-500 malayalam"
