export type HeirType = keyof typeof HEIR_METADATA;

export interface Heir {
  type: HeirType;
  count: number;
}

export interface EstateData {
  totalAssets: number;
  debts: number;
  funeral: number;
  will: number;
}

export interface CalculationResult {
  shares: Array<{ label: string, fraction: string, percentage: string, amount?: number }>;
  netEstate: number;
  complex: boolean;
  warnings: string[];
}

import { Heir, CalculationResult, HeirType, HEIR_METADATA, EstateData } from '../types';

export const calculateShares = (heirs: Heir[], deceasedGender: 'Male' | 'Female', estate: EstateData): CalculationResult => {
  const netEstate = Math.max(0, estate.totalAssets - (estate.debts + estate.funeral + estate.will));

  const result: CalculationResult = {
    shares: [],
    netEstate,
    complex: false,
    warnings: []
  };

  const heirMap = heirs.reduce((acc, h) => {
    acc[h.type] = h.count;
    return acc;
  }, {} as Record<HeirType, number>);

  const hasChildren = (heirMap['Son'] || 0) > 0 || 
                      (heirMap['Daughter'] || 0) > 0;

  const hasSiblings = ((heirMap['Full Brother'] || 0) + 
                       (heirMap['Full Sister'] || 0) + 
                       (heirMap['Paternal Brother'] || 0) + 
                       (heirMap['Paternal Sister'] || 0) + 
                       (heirMap['Maternal Brother'] || 0) + 
                       (heirMap['Maternal Sister'] || 0)) >= 2;

  // Detect Complex Cases
  const complexTriggers: HeirType[] = [
    'Paternal Grandfather', 'Paternal Grandmother', 'Maternal Grandmother',
    'Full Brother', 'Full Sister', 'Paternal Brother', 'Paternal Sister', 'Maternal Brother', 'Maternal Sister',
    'Full Nephew', 'Paternal Nephew', 'Full Nephew Son', 'Paternal Nephew Son', 'Full Paternal Uncle',
    'Paternal Paternal Uncle', 'Full Cousin', 'Paternal Cousin', 'Full Cousin Son', 'Paternal Cousin Son',
    'Full Cousin Grandson', 'Paternal Cousin Grandson'
  ];

  if (heirs.some(h => complexTriggers.includes(h.type))) {
    result.complex = true;
  }

  // Fractions & Percentages
  let totalFixedShare = 0;

  // Husband
  if (deceasedGender === 'Female' && heirMap['Husband']) {
    const fraction = hasChildren ? 0.25 : 0.5;
    totalFixedShare += fraction;
    result.shares.push({
      label: HEIR_METADATA['Husband'].ml,
      fraction: hasChildren ? '1/4' : '1/2',
      percentage: hasChildren ? '25%' : '50%',
      amount: netEstate * fraction
    });
  }

  // Wife
  if (deceasedGender === 'Male' && heirMap['Wife']) {
    const fraction = hasChildren ? 0.125 : 0.25;
    totalFixedShare += fraction;
    result.shares.push({
      label: HEIR_METADATA['Wife'].ml,
      fraction: hasChildren ? '1/8 (കൂട്ടായി)' : '1/4 (കൂട്ടായി)',
      percentage: hasChildren ? '12.5%' : '25%',
      amount: netEstate * fraction
    });
  }

  // Father
  if (heirMap['Father']) {
    if (hasChildren) {
      totalFixedShare += 1/6;
      result.shares.push({
        label: HEIR_METADATA['Father'].ml,
        fraction: '1/6',
        percentage: '16.66%',
        amount: netEstate * (1/6)
      });
    } else {
      // Father takes residue as Asaba if no children
      // We handle Asaba at the end
    }
  }

  // Mother
  if (heirMap['Mother']) {
    const fraction = (hasChildren || hasSiblings) ? 1/6 : 1/3;
    totalFixedShare += fraction;
    result.shares.push({
      label: HEIR_METADATA['Mother'].ml,
      fraction: (hasChildren || hasSiblings) ? '1/6' : '1/3',
      percentage: (hasChildren || hasSiblings) ? '16.66%' : '33.33%',
      amount: netEstate * fraction
    });
  }

  // Daughters (Zawil Furud) if no Son
  if (heirMap['Daughter'] > 0 && !heirMap['Son']) {
    if (heirMap['Daughter'] === 1) {
      totalFixedShare += 0.5;
      result.shares.push({
        label: 'പുത്രി',
        fraction: '1/2',
        percentage: '50%',
        amount: netEstate * 0.5
      });
    } else {
      totalFixedShare += 2/3;
      result.shares.push({
        label: 'പുത്രിമാർ',
        fraction: '2/3 (കൂട്ടായി)',
        percentage: '66.66%',
        amount: netEstate * (2/3)
      });
    }
  }

  // Residue (Asaba)
  const residue = Math.max(0, 1 - totalFixedShare);

  if (heirMap['Son']) {
    const sonCount = heirMap['Son'];
    const daughterCount = heirMap['Daughter'] || 0;
    const totalUnits = (sonCount * 2) + daughterCount;

    if (residue > 0) {
      result.shares.push({
        label: sonCount > 1 ? 'പുത്രന്മാർ' : 'പുത്രൻ',
        fraction: 'ബാക്കി (2/3 ratio)',
        percentage: `${((residue * (sonCount * 2 / totalUnits)) * 100).toFixed(2)}%`,
        amount: netEstate * (residue * (sonCount * 2 / totalUnits))
      });
      if (daughterCount > 0) {
        result.shares.push({
          label: daughterCount > 1 ? 'പുത്രിമാർ' : 'പുത്രി',
          fraction: 'ബാക്കി (1/3 ratio)',
          percentage: `${((residue * (daughterCount / totalUnits)) * 100).toFixed(2)}%`,
          amount: netEstate * (residue * (daughterCount / totalUnits))
        });
      }
    }
  } else if (heirMap['Father'] && !hasChildren) {
    // Father takes residue as Asaba if no children
    if (residue > 0) {
      result.shares.push({
        label: HEIR_METADATA['Father'].ml,
        fraction: 'ബാക്കി മുഴുവൻ',
        percentage: `${(residue * 100).toFixed(2)}%`,
        amount: netEstate * residue
      });
    }
  }

  // Oversubscription check (Aul) - Simple detection
  if (totalFixedShare > 1) {
    result.complex = true;
    result.warnings.push("സ്വത്ത് ഓഹരികൾ ഒത്തുപോകാത്ത സങ്കീർണ്ണമായ സാഹചര്യം (Aul). ദയവായി ഒരു പണ്ഡിതനെ സമീപിക്കുക.");
  }

  return result;
};

