            { label: 'പരിച്ഛേദ ചെലവ് (Funeral ചെലവ്):', key: 'funeral' },
            { label: 'വസീയ്യത്ത് (Will):', key: 'will' }
          ].map(field => (
            <div key={field.key} className="bg-white p-5 rounded-2xl border border-slate-100 shadow-sm space-y-3">
              <label className="text-sm font-bold text-slate-700 malayalam">{field.label}</label>
              <div className="relative">
                <span className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400 font-bold">₹</span>
                <input 
                  type="number" 
                  value={(estate as any)[field.key] || ''}
                  onChange={e => setEstate({...estate, [field.key]: Number(e.target.value)})}
                  className="w-full bg-slate-50 border-2 border-transparent focus:border-emerald-500 focus:bg-white rounded-xl py-4 pl-10 pr-4 outline-none transition-all font-bold text-lg"
                  placeholder="0"
                />
              </div>
            </div>
          ))}
        </div>

        <div className="fixed bottom-0 left-0 right-0 p-6 bg-white/80 backdrop-blur-md border-t border-slate-100 flex justify-center gap-4">
          <button onClick={() => setStep(AppStep.AYAH)} className="flex-1 max-w-[140px] border-2 border-slate-200 py-4 rounded-2xl font-bold text-slate-600 active:scale-95 malayalam">പുറകോട്ട്</button>
          <button onClick={() => setStep(AppStep.GENDER)} className="flex-1 max-w-xs bg-emerald-600 text-white py-4 rounded-2xl font-bold text-xl shadow-lg malayalam">അടുത്തത്</button>
        </div>
      </div>
    );
  }

  if (step === AppStep.GENDER) {
    return (
      <ScreenWrapper nextStep={deceasedGender ? AppStep.SELECTION : undefined} prevStep={AppStep.ASSETS}>
        <div className="text-center space-y-10 w-full">
          <h2 className="text-3xl font-black text-slate-900 malayalam">മരണപ്പെട്ട വ്യക്തി ആരാണ്?</h2>
          <div className="flex flex-col gap-5 w-full">
            <button 
              onClick={() => setDeceasedGender('Male')}
              className={`w-full py-8 rounded-3xl font-black text-2xl transition-all malayalam flex items-center justify-center gap-4 border-4 ${deceasedGender === 'Male' ? 'bg-emerald-600 border-emerald-400 text-white shadow-xl shadow-emerald-500/20' : 'bg-white border-slate-100 text-slate-400 hover:border-emerald-100'}`}
            >
              <svg className="w-10 h-10" fill="currentColor" viewBox="0 0 24 24"><path d="M12 2C6.48 2 2 6.48 2 12s4.48 10 10 10 10-4.48 10-10S17.52 2 12 2zm0 3c1.66 0 3 1.34 3 3s-1.34 3-3 3-3-1.34-3-3 1.34-3 3-3zm0 14.2c-2.5 0-4.71-1.28-6-3.22.03-1.99 4-3.08 6-3.08s5.97 1.09 6 3.08c-1.29 1.94-3.5 3.22-6 3.22z" /></svg>
              <span>പുരുഷൻ</span>
            </button>
            <button 
              onClick={() => setDeceasedGender('Female')}
              className={`w-full py-8 rounded-3xl font-black text-2xl transition-all malayalam flex items-center justify-center gap-4 border-4 ${deceasedGender === 'Female' ? 'bg-emerald-600 border-emerald-400 text-white shadow-xl shadow-emerald-500/20' : 'bg-white border-slate-100 text-slate-400 hover:border-emerald-100'}`}
            >
              <svg className="w-10 h-10" fill="currentColor" viewBox="0 0 24 24"><path d="M12 2C6.48 2 2 6.48 2 12s4.48 10 10 10 10-4.48 10-10S17.52 2 12 2zm0 3c1.66 0 3 1.34 3 3s-1.34 3-3 3-3-1.34-3-3 1.34-3 3-3zm0 14.2c-2.5 0-4.71-1.28-6-3.22.03-1.99 4-3.08 6-3.08s5.97 1.09 6 3.08c-1.29 1.94-3.5 3.22-6 3.22z" /></svg>
              <span>സ്ത്രീ</span>
            </button>
          </div>
        </div>
      </ScreenWrapper>
    );
  }

  if (step === AppStep.SELECTION) {
    return (
      <div className="min-h-screen bg-slate-50 flex flex-col p-6 pb-28">
        <header className="mb-10 text-center">
          <h2 className="text-3xl font-black text-slate-900 mb-2 malayalam">ബന്ധുക്കളെ തിരഞ്ഞെടുക്കുക</h2>
          <p className="text-slate-500 text-sm malayalam">അവകാശികളെ ഇവിടെ ചേർക്കുക.</p>
        </header>

        <div className="space-y-8 max-w-md mx-auto w-full">
          {Object.entries(heirCategories).map(([category, types]) => {
            const filteredTypes = types.filter(t => {
              if (t === 'Husband' && deceasedGender === 'Male') return false;
              if (t === 'Wife' && deceasedGender === 'Female') return false;
              return true;
            });
            if (filteredTypes.length === 0) return null;

            return (
              <div key={category} className="space-y-4">
                <h4 className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-2 malayalam">{category}</h4>
                <div className="grid grid-cols-1 gap-3">
                  {filteredTypes.map(type => {
                    const count = getHeirCount(type);
                    return (
                      <div key={type} className="bg-white p-5 rounded-[2rem] border border-slate-100 flex items-center justify-between shadow-sm transition-transform active:scale-[0.99]">
                        <div className="flex flex-col">
                          <span className="font-bold text-slate-800 malayalam leading-tight">{HEIR_METADATA[type].ml}</span>
                          <span className="text-[9px] text-slate-400 font-bold uppercase tracking-tight">{type}</span>
                        </div>
                        <div className="flex items-center gap-4 bg-slate-50 p-1.5 rounded-2xl">
                          <button 
                            onClick={() => updateHeirCount(type, -1)}
                            className="w-10 h-10 rounded-xl bg-white shadow-sm flex items-center justify-center text-slate-400 hover:text-rose-500 transition-colors active:scale-90"
                          >
                            <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M20 12H4" /></svg>
                          </button>
                          <span className="w-6 text-center font-black text-lg text-slate-900">{count}</span>
                          <button 
                            onClick={() => updateHeirCount(type, 1)}
                            className="w-10 h-10 rounded-xl bg-white shadow-sm flex items-center justify-center text-slate-400 hover:text-emerald-500 transition-colors active:scale-90"
                          >
                            <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M12 4v16m8-8H4" /></svg>
                          </button>
                        </div>
                      </div>
                    );
                  })}
                </div>
              </div>
            );
          })}
        </div>

        <div className="fixed bottom-0 left-0 right-0 p-6 bg-white/80 backdrop-blur-md border-t border-slate-100 flex justify-center gap-4">
          <button onClick={() => setStep(AppStep.GENDER)} className="flex-1 max-w-[140px] border-2 border-slate-200 py-4 rounded-2xl font-bold text-slate-600 active:scale-95 malayalam">പുറകോട്ട്</button>
          <button 
            disabled={heirs.length === 0}
            onClick={handleCalculate} 
            className="flex-1 max-w-xs bg-emerald-600 text-white py-4 rounded-2xl font-bold text-xl shadow-lg disabled:bg-slate-300 malayalam"
          >
            കണക്കാക്കുക
          </button>
        </div>
      </div>
    );
  }

  if (step === AppStep.RESULT && result) {
    return (
      <div className="min-h-screen bg-slate-50 flex flex-col p-6 py-14 animate-in zoom-in duration-500">
        <header className="mb-10 text-center space-y-3">
          <h2 className="text-3xl font-black text-slate-900 malayalam">അവകാശ വിഹിതങ്ങൾ</h2>
          <div className="bg-emerald-600 text-white px-8 py-4 rounded-[2.5rem] inline-block shadow-xl shadow-emerald-500/20">
             <p className="text-xs uppercase font-black tracking-widest mb-1 opacity-80">Net Estate</p>
             <p className="text-2xl font-black">₹{result.netEstate.toLocaleString()}</p>
          </div>
        </header>

        <div className="max-w-xl mx-auto w-full space-y-8 flex-1">
          {result.warnings.map((w, i) => (
            <div key={i} className="bg-rose-50 text-rose-600 p-6 rounded-[2rem] border border-rose-100 text-sm font-bold flex gap-4">
              <svg className="w-6 h-6 shrink-0" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z" /></svg>
              <span className="malayalam">{w}</span>
            </div>
          ))}

          {result.complex && (
            <div className="bg-amber-50 text-amber-800 p-8 rounded-[3rem] border-2 border-amber-100 text-center shadow-lg shadow-amber-500/5 malayalam space-y-2">
              <p className="font-black text-xl">സങ്കീർണ്ണമായ കേസ്</p>
              <p className="text-sm">വിപുലമായ നിയമങ്ങൾ ബാധകമായതിനാൽ കൃത്യതയ്ക്കായി ഒരു പണ്ഡിതനെ സമീപിക്കുക.</p>
            </div>
          )}

          <div className="bg-white p-3 rounded-[3rem] shadow-xl border border-slate-100 overflow-hidden divide-y divide-slate-50">
            {result.shares.map((share, i) => (
              <div key={i} className="flex items-center justify-between p-6 transition-colors hover:bg-slate-50">
                <div className="space-y-1">
                  <p className="font-black text-slate-900 text-xl malayalam">{share.label}</p>
                  <p className="text-xs text-slate-400 font-bold uppercase tracking-widest">{share.percentage}</p>
                </div>
                <div className="text-right">
                  <div className="bg-emerald-50 text-emerald-700 px-5 py-2 rounded-2xl font-black text-lg mb-1">{share.fraction}</div>
                  {share.amount !== undefined && <p className="text-xs font-bold text-slate-400">₹{share.amount.toLocaleString()}</p>}
                </div>
              </div>
            ))}
            {result.shares.length === 0 && (
              <div className="p-16 text-center text-slate-400 malayalam italic">അർഹരായ അവകാശികളെ കണ്ടെത്താനായില്ല.</div>
            )}
          </div>
        </div>

        <div className="flex flex-col gap-4 mt-12 mb-8">
          <button 
            onClick={() => setStep(AppStep.SELECTION)}
            className="w-full bg-slate-900 text-white py-5 rounded-2xl font-black text-lg transition-all active:scale-95 malayalam"
          >
            എഡിറ്റ് ചെയ്യുക
          </button>
          <button 
            onClick={reset}
            className="w-full border-2 border-slate-200 text-slate-600 py-5 rounded-2xl font-black text-lg transition-all active:scale-95 malayalam"
          >
            പുതിയ കണക്ക് തുടങ്ങുക
          </button>
        </div>
      </div>
    );
  }

  return null;
};

export default App;

import React, { useState, useMemo } from 'react';
import { AppStep, Heir, HeirType, CalculationResult, HEIR_METADATA, EstateData } from './types';
import { calculateShares } from './logic/faraidEngine';

// Move ScreenWrapper outside to avoid re-creation on every render and fix JSX type inference issues
interface ScreenWrapperProps {
  children: React.ReactNode;
  nextStep?: AppStep;
  prevStep?: AppStep;
  setStep: (step: AppStep) => void;
  nextLabel?: string;
}

const ScreenWrapper: React.FC<ScreenWrapperProps> = ({ 
  children, 
  nextStep, 
  prevStep, 
  setStep, 
  nextLabel = "അടുത്തത്" 
}) => (
  <div className="min-h-screen bg-white flex flex-col p-6 pb-24 animate-in fade-in duration-500">
    <div className="flex-1 flex flex-col items-center justify-center max-w-lg mx-auto w-full">
      {children}
    </div>
    <div className="fixed bottom-0 left-0 right-0 p-6 bg-white/80 backdrop-blur-md border-t border-slate-100 flex justify-center gap-4">
      {prevStep && (
        <button 
          onClick={() => setStep(prevStep)}
          className="flex-1 max-w-[140px] border-2 border-slate-200 py-4 rounded-2xl font-bold text-slate-600 active:scale-95 transition-all malayalam"
        >
          പുറകോട്ട്
        </button>
      )}
      {nextStep && (
        <button 
          onClick={() => setStep(nextStep)}
          className="flex-1 max-w-xs bg-emerald-600 hover:bg-emerald-500 text-white py-4 rounded-2xl font-bold text-xl transition-all active:scale-95 shadow-lg shadow-emerald-600/20 malayalam"
        >
          {nextLabel}
        </button>
      )}
    </div>
  </div>
);

const App: React.FC = () => {
  const [step, setStep] = useState<AppStep>(AppStep.WELCOME);
  const [deceasedGender, setDeceasedGender] = useState<'Male' | 'Female'>('Male');
  const [heirs, setHeirs] = useState<Heir[]>([]);
  const [estate, setEstate] = useState<EstateData>({
    totalAssets: 0,
    debts: 0,
    funeral: 0,
    will: 0
  });
  const [result, setResult] = useState<CalculationResult | null>(null);

  const heirCategories = useMemo(() => {
    const cats: Record<string, HeirType[]> = {};
    Object.entries(HEIR_METADATA).forEach(([type, meta]) => {
      if (!cats[meta.category]) cats[meta.category] = [];
      cats[meta.category].push(type as HeirType);
    });
    return cats;
  }, []);

  const updateHeirCount = (type: HeirType, delta: number) => {
    const meta = HEIR_METADATA[type];
    setHeirs(prev => {
      const existing = prev.find(h => h.type === type);
      if (existing) {
        let newCount = existing.count + delta;
        if (meta.max) newCount = Math.min(newCount, meta.max);
        newCount = Math.max(0, newCount);
        if (newCount === 0) return prev.filter(h => h.type !== type);
        return prev.map(h => h.type === type ? { ...h, count: newCount } : h);
      } else if (delta > 0) {
        return [...prev, { type, count: 1 }];
      }
      return prev;
    });
  };

  const getHeirCount = (type: HeirType) => heirs.find(h => h.type === type)?.count || 0;

  const handleCalculate = () => {
    const calcResult = calculateShares(heirs, deceasedGender, estate);
    setResult(calcResult);
    setStep(AppStep.RESULT);
  };

  const reset = () => {
    setHeirs([]);
    setEstate({ totalAssets: 0, debts: 0, funeral: 0, will: 0 });
    setResult(null);
    setStep(AppStep.WELCOME);
  };

  // --- Screens ---

  if (step === AppStep.WELCOME) {
    return (
      <div className="min-h-screen bg-slate-900 flex flex-col items-center justify-center p-6 text-white text-center">
        <div className="w-24 h-24 bg-emerald-600 rounded-[2rem] flex items-center justify-center mb-10 shadow-2xl shadow-emerald-500/20 rotate-3 animate-bounce">
          <svg className="w-12 h-12" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 6.253v13m0-13C10.832 5.477 9.246 5 7.5 5S4.168 5.477 3 6.253v13C4.168 18.477 5.754 18 7.5 18s3.332.477 4.5 1.253m0-13C13.168 5.477 14.754 5 16.5 5c1.747 0 3.332.477 4.5 1.253v13C19.832 18.247 18.247 18 16.5 18c-1.746 0-3.332.477-4.5 1.253" />
          </svg>
        </div>
        <h1 className="text-4xl font-extrabold mb-4 tracking-tight malayalam">ഫറാഇദ് കാൽക്കുലേറ്റർ</h1>
        <p className="text-slate-400 max-w-sm mb-14 text-lg leading-relaxed malayalam">
          ഇസ്ലാമിക അവകാശവിഹിതം ലളിതമായി കണക്കാക്കാം
        </p>
        <button 
          onClick={() => setStep(AppStep.DESCRIPTION)}
          className="w-full max-w-xs bg-emerald-600 hover:bg-emerald-500 py-5 rounded-2xl font-bold text-xl transition-all active:scale-95 shadow-lg shadow-emerald-600/30 malayalam"
        >
          തുടരുക
        </button>
      </div>
    );
  }

  if (step === AppStep.DESCRIPTION) {
    return (
      /* Fix: Use setStep prop and wrap children correctly */
      <ScreenWrapper nextStep={AppStep.HADITH} prevStep={AppStep.WELCOME} setStep={setStep}>
        <div className="text-center space-y-8">
          <div className="w-20 h-20 bg-emerald-50 text-emerald-600 rounded-full flex items-center justify-center mx-auto mb-4">
             <svg className="w-10 h-10" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 16h-1v-4h-1m1-4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z" /></svg>
          </div>
          <p className="malayalam text-slate-700 leading-relaxed text-xl font-medium px-4">
            ഖുര്‍ആനും സുന്നത്തും അടിസ്ഥാനമാക്കി മരണപ്പെട്ട വ്യക്തിയുടെ സ്വത്ത് ന്യായമായ വിധത്തിൽ ആരെല്ലാമാണ് ലഭിക്കേണ്ടത് എന്ന് കണക്കാക്കാനുള്ള ഉപകരണം ആണ് ഫറാഇദ് കാൽക്കുലേറ്റർ. ഈ ആപ്പ് കേരളത്തിലെ മുസ്ലിം ഉപയോക്താക്കളെ ധിഷണാപൂർവ്വം സഹായിക്കാൻ രൂപപ്പെടുത്തിയതാണ്.
          </p>
        </div>
      </ScreenWrapper>
    );
  }

  if (step === AppStep.HADITH) {
    return (
      /* Fix: Use setStep prop and wrap children correctly */
      <ScreenWrapper nextStep={AppStep.AYAH} prevStep={AppStep.DESCRIPTION} setStep={setStep}>
        <div className="text-center space-y-8 px-4">
          <header className="space-y-2">
            <p className="text-[10px] text-emerald-500 font-bold tracking-[0.2em] uppercase">Hadith</p>
            <div className="w-8 h-1 bg-emerald-500 mx-auto rounded-full"></div>
          </header>
          <div className="bg-emerald-50 p-8 rounded-[2.5rem] border border-emerald-100">
            <p className="arabic text-3xl mb-6 text-slate-800 leading-relaxed font-bold">"تَعَلَّمُوا الْفَرَائِضَ وَعَلِّمُوهَا النَّاسَ"</p>
            <p className="malayalam text-emerald-900 leading-relaxed font-bold text-xl">"ഫറാഇദ് (ഇസ്ലാമിക അവകാശവിഭാഗം) പഠിക്കൂ, അത് ആളുകളെ പഠിപ്പിക്കൂ."</p>
          </div>
          <p className="malayalam text-slate-500 text-lg">ഫറാഇദ് പഠിക്കുന്നത് സമൂഹത്തിലെ അവകാശവിതരണത്തിൽ നീതി ഉറപ്പാക്കുന്നു.</p>
        </div>
      </ScreenWrapper>
    );
  }

  if (step === AppStep.AYAH) {
    return (
      /* Fix: Use setStep prop and wrap children correctly */
      <ScreenWrapper nextStep={AppStep.ASSETS} prevStep={AppStep.HADITH} setStep={setStep}>
        <div className="text-center space-y-8 px-4">
          <header className="space-y-2">
            <p className="text-[10px] text-amber-500 font-bold tracking-[0.2em] uppercase">Quran 4:11</p>
            <div className="w-8 h-1 bg-amber-500 mx-auto rounded-full"></div>
          </header>
          <div className="bg-amber-50 p-8 rounded-[2.5rem] border border-amber-100">
            <p className="arabic text-2xl mb-6 text-slate-800 leading-loose font-bold">"يُوصِيكُمُ اللَّهُ فِي أَوْلَادِكُمْ لِلذَّكَرِ مِثْلُ حَظِّ الْأُنْثَيَيْنِ"</p>
            <p className="malayalam text-amber-900 leading-relaxed font-bold text-lg">"നിങ്ങളുടെ മക്കളെ സംബന്ധിച്ച് അല്ലാഹു നിങ്ങളെ ഉപദേശിക്കുന്നു; ആൺകുട്ടിക്ക് രണ്ട് പെൺകുട്ടികളുടെ ഓഹരിക്ക് തുല്യമായിരിക്കും."</p>
          </div>
          <p className="malayalam text-slate-500 text-lg">ഖുര്‍ആനിൽ സുതാര്യമായി അവകാശവിതരണ നിയമങ്ങൾ നിർദ്ദേശിച്ചിട്ടുണ്ട്.</p>
        </div>
      </ScreenWrapper>
    );
  }

  if (step === AppStep.ASSETS) {
    return (
      <div className="min-h-screen bg-slate-50 flex flex-col p-6 animate-in slide-in-from-right duration-500 pb-28">
        <header className="mb-10 text-center">
          <h2 className="text-3xl font-black text-slate-900 mb-2 malayalam">സ്വത്ത് വിവരങ്ങൾ</h2>
          <p className="text-slate-500 text-sm malayalam">ലഭ്യമായ ആസ്തിയും ബാധ്യതകളും ഇവിടെ നൽകുക.</p>
        </header>

        <div className="space-y-6 max-w-md mx-auto w-full">
          {[
            { label: 'ആസ്തി (മൊത്തം സ്വത്ത്):', key: 'totalAssets' },
            { label: 'കടം (കരുതേണ്ട കുടിശ്ശിക):', key: 'debts' },
            { label: 'പരിച്ഛേദ ചെലവ് (Funeral ചെലവ്):', key: 'funeral' },
            { label: 'വസീയ്യത്ത് (Will):', key: 'will' }
          ].map(field => (
            <div key={field.key} className="bg-white p-5 rounded-2xl border border-slate-100 shadow-sm space-y-3">
              <label className="text-sm font-bold text-slate-700 malayalam">{field.label}</label>
              <div className="relative">
                <span className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400 font-bold">₹</span>
                <input 
                  type="number" 
                  value={(estate as any)[field.key] || ''}
                  onChange={e => setEstate({...estate, [field.key]: Number(e.target.value)})}
                  className="w-full bg-slate-50 border-2 border-transparent focus:border-emerald-500 focus:bg-white rounded-xl py-4 pl-10 pr-4 outline-none transition-all font-bold text-lg"
                  placeholder="0"
                />
              </div>
            </div>
          ))}
        </div>

        <div className="fixed bottom-0 left-0 right-0 p-6 bg-white/80 backdrop-blur-md border-t border-slate-100 flex justify-center gap-4">
          <button onClick={() => setStep(AppStep.AYAH)} className="flex-1 max-w-[140px] border-2 border-slate-200 py-4 rounded-2xl font-bold text-slate-600 active:scale-95 malayalam">പുറകോട്ട്</button>
          <button onClick={() => setStep(AppStep.GENDER)} className="flex-1 max-w-xs bg-emerald-600 text-white py-4 rounded-2xl font-bold text-xl shadow-lg malayalam">അടുത്തത്</button>
        </div>
      </div>
    );
  }

  if (step === AppStep.GENDER) {
    return (
      /* Fix: Use setStep prop and wrap children correctly */
      <ScreenWrapper nextStep={deceasedGender ? AppStep.SELECTION : undefined} prevStep={AppStep.ASSETS} setStep={setStep}>
        <div className="text-center space-y-10 w-full">
          <h2 className="text-3xl font-black text-slate-900 malayalam">മരണപ്പെട്ട വ്യക്തി ആരാണ്?</h2>
          <div className="flex flex-col gap-5 w-full">
            <button 
              onClick={() => setDeceasedGender('Male')}
              className={`w-full py-8 rounded-3xl font-black text-2xl transition-all malayalam flex items-center justify-center gap-4 border-4 ${deceasedGender === 'Male' ? 'bg-emerald-600 border-emerald-400 text-white shadow-xl shadow-emerald-500/20' : 'bg-white border-slate-100 text-slate-400 hover:border-emerald-100'}`}
            >
              <svg className="w-10 h-10" fill="currentColor" viewBox="0 0 24 24"><path d="M12 2C6.48 2 2 6.48 2 12s4.48 10 10 10 10-4.48 10-10S17.52 2 12 2zm0 3c1.66 0 3 1.34 3 3s-1.34 3-3 3-3-1.34-3-3 1.34-3 3-3zm0 14.2c-2.5 0-4.71-1.28-6-3.22.03-1.99 4-3.08 6-3.08s5.97 1.09 6 3.08c-1.29 1.94-3.5 3.22-6 3.22z" /></svg>
              <span>പുരുഷൻ</span>
            </button>
            <button 
              onClick={() => setDeceasedGender('Female')}
              className={`w-full py-8 rounded-3xl font-black text-2xl transition-all malayalam flex items-center justify-center gap-4 border-4 ${deceasedGender === 'Female' ? 'bg-emerald-600 border-emerald-400 text-white shadow-xl shadow-emerald-500/20' : 'bg-white border-slate-100 text-slate-400 hover:border-emerald-100'}`}
            >
              <svg className="w-10 h-10" fill="currentColor" viewBox="0 0 24 24"><path d="M12 2C6.48 2 2 6.48 2 12s4.48 10 10 10 10-4.48 10-10S17.52 2 12 2zm0 3c1.66 0 3 1.34 3 3s-1.34 3-3 3-3-1.34-3-3 1.34-3 3-3zm0 14.2c-2.5 0-4.71-1.28-6-3.22.03-1.99 4-3.08 6-3.08s5.97 1.09 6 3.08c-1.29 1.94-3.5 3.22-6 3.22z" /></svg>
              <span>സ്ത്രീ</span>
            </button>
          </div>
        </div>
      </ScreenWrapper>
    );
  }

  if (step === AppStep.SELECTION) {
    return (
      <div className="min-h-screen bg-slate-50 flex flex-col p-6 pb-28">
        <header className="mb-10 text-center">
          <h2 className="text-3xl font-black text-slate-900 mb-2 malayalam">ബന്ധുക്കളെ തിരഞ്ഞെടുക്കുക</h2>
          <p className="text-slate-500 text-sm malayalam">അവകാശികളെ ഇവിടെ ചേർക്കുക.</p>
        </header>

        <div className="space-y-8 max-w-md mx-auto w-full">
          {Object.entries(heirCategories).map(([category, types]) => {
            /* Fix: Explicitly type 'types' to avoid unknown type error on filter */
            const typedTypes = types as HeirType[];
            const filteredTypes = typedTypes.filter(t => {
              if (t === 'Husband' && deceasedGender === 'Male') return false;
              if (t === 'Wife' && deceasedGender === 'Female') return false;
              return true;
            });
            if (filteredTypes.length === 0) return null;

            return (
              <div key={category} className="space-y-4">
                <h4 className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-2 malayalam">{category}</h4>
                <div className="grid grid-cols-1 gap-3">
                  {filteredTypes.map(type => {
                    const count = getHeirCount(type);
                    return (
                      <div key={type} className="bg-white p-5 rounded-[2rem] border border-slate-100 flex items-center justify-between shadow-sm transition-transform active:scale-[0.99]">
                        <div className="flex flex-col">
                          <span className="font-bold text-slate-800 malayalam leading-tight">{HEIR_METADATA[type].ml}</span>
                          <span className="text-[9px] text-slate-400 font-bold uppercase tracking-tight">{type}</span>
                        </div>
                        <div className="flex items-center gap-4 bg-slate-50 p-1.5 rounded-2xl">
                          <button 
                            onClick={() => updateHeirCount(type, -1)}
                            className="w-10 h-10 rounded-xl bg-white shadow-sm flex items-center justify-center text-slate-400 hover:text-rose-500 transition-colors active:scale-90"
                          >
                            <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M20 12H4" /></svg>
                          </button>
                          <span className="w-6 text-center font-black text-lg text-slate-900">{count}</span>
                          <button 
                            onClick={() => updateHeirCount(type, 1)}
                            className="w-10 h-10 rounded-xl bg-white shadow-sm flex items-center justify-center text-slate-400 hover:text-emerald-500 transition-colors active:scale-90"
                          >
                            <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M12 4v16m8-8H4" /></svg>
                          </button>
                        </div>
                      </div>
                    );
                  })}
                </div>
              </div>
            );
          })}
        </div>

        <div className="fixed bottom-0 left-0 right-0 p-6 bg-white/80 backdrop-blur-md border-t border-slate-100 flex justify-center gap-4">
          <button onClick={() => setStep(AppStep.GENDER)} className="flex-1 max-w-[140px] border-2 border-slate-200 py-4 rounded-2xl font-bold text-slate-600 active:scale-95 malayalam">പുറകോട്ട്</button>
          <button 
            disabled={heirs.length === 0}
            onClick={handleCalculate} 
            className="flex-1 max-w-xs bg-emerald-600 text-white py-4 rounded-2xl font-bold text-xl shadow-lg disabled:bg-slate-300 malayalam"
          >
            കണക്കാക്കുക
          </button>
        </div>
      </div>
    );
  }

  if (step === AppStep.RESULT && result) {
    return (
      <div className="min-h-screen bg-slate-50 flex flex-col p-6 py-14 animate-in zoom-in duration-500">
        <header className="mb-10 text-center space-y-3">
          <h2 className="text-3xl font-black text-slate-900 malayalam">അവകാശ വിഹിതങ്ങൾ</h2>
          <div className="bg-emerald-600 text-white px-8 py-4 rounded-[2.5rem] inline-block shadow-xl shadow-emerald-500/20">
             <p className="text-xs uppercase font-black tracking-widest mb-1 opacity-80">Net Estate</p>
             <p className="text-2xl font-black">₹{result.netEstate.toLocaleString()}</p>
          </div>
        </header>

        <div className="max-w-xl mx-auto w-full space-y-8 flex-1">
          {result.warnings.map((w, i) => (
            <div key={i} className="bg-rose-50 text-rose-600 p-6 rounded-[2rem] border border-rose-100 text-sm font-bold flex gap-4">
              <svg className="w-6 h-6 shrink-0" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z" /></svg>
              <span className="malayalam">{w}</span>
            </div>
          ))}

          {result.complex && (
            <div className="bg-amber-50 text-amber-800 p-8 rounded-[3rem] border-2 border-amber-100 text-center shadow-lg shadow-amber-500/5 malayalam space-y-2">
              <p className="font-black text-xl">സങ്കീർണ്ണമായ കേസ്</p>
              <p className="text-sm">വിപുലമായ നിയമങ്ങൾ ബാധകമായതിനാൽ കൃത്യതയ്ക്കായി ഒരു പണ്ഡിതനെ സമീപിക്കുക.</p>
            </div>
          )}

          <div className="bg-white p-3 rounded-[3rem] shadow-xl border border-slate-100 overflow-hidden divide-y divide-slate-50">
            {result.shares.map((share, i) => (
              <div key={i} className="flex items-center justify-between p-6 transition-colors hover:bg-slate-50">
                <div className="space-y-1">
                  <p className="font-black text-slate-900 text-xl malayalam">{share.label}</p>
                  <p className="text-xs text-slate-400 font-bold uppercase tracking-widest">{share.percentage}</p>
                </div>
                <div className="text-right">
                  <div className="bg-emerald-50 text-emerald-700 px-5 py-2 rounded-2xl font-black text-lg mb-1">{share.fraction}</div>
                  {share.amount !== undefined && <p className="text-xs font-bold text-slate-400">₹{share.amount.toLocaleString()}</p>}
                </div>
              </div>
            ))}
            {result.shares.length === 0 && (
              <div className="p-16 text-center text-slate-400 malayalam italic">അർഹരായ അവകാശികളെ കണ്ടെത്താനായില്ല.</div>
            )}
          </div>
        </div>

        <div className="flex flex-col gap-4 mt-12 mb-8">
          <button 
            onClick={() => setStep(AppStep.SELECTION)}
            className="w-full bg-slate-900 text-white py-5 rounded-2xl font-black text-lg transition-all active:scale-95 malayalam"
          >
            എഡിറ്റ് ചെയ്യുക
          </button>
          <button 
            onClick={reset}
            className="w-full border-2 border-slate-200 text-slate-600 py-5 rounded-2xl font-black text-lg transition-all active:scale-95 malayalam"
          >
            പുതിയ കണക്ക് തുടങ്ങുക
          </button>
        </div>
      </div>
    );
  }

  return null;
};

export default App;

import React, { useState, useMemo } from 'react';
import { AppStep, Heir, HeirType, CalculationResult, HEIR_METADATA, EstateData } from './types';
import { calculateShares } from './logic/faraidEngine';

interface ScreenWrapperProps {
  children: React.ReactNode;
  nextStep?: AppStep;
  prevStep?: AppStep;
  setStep: (step: AppStep) => void;
  nextLabel?: string;
  disabled?: boolean;
}

const ScreenWrapper: React.FC<ScreenWrapperProps> = ({ 
  children, 
  nextStep, 
  prevStep, 
  setStep, 
  nextLabel = "അടുത്തത്",
  disabled = false
}) => (
  <div className="min-h-screen flex flex-col relative overflow-hidden bg-[#fdfdfb]">
    <div className="absolute inset-0 islamic-pattern pointer-events-none"></div>

    <main className="flex-1 flex flex-col items-center justify-center max-w-lg mx-auto w-full px-6 py-12 relative z-10 animate-slide-up">
      {children}
    </main>

    <div className="sticky bottom-0 left-0 right-0 p-6 glass border-t border-emerald-100/50 flex justify-center gap-4 z-50">
      {prevStep && (
        <button 
          onClick={() => setStep(prevStep)}
          className="flex-1 max-w-[120px] h-14 rounded-2xl font-bold text-emerald-800 bg-emerald-50 hover:bg-emerald-100 active:scale-95 transition-all malayalam flex items-center justify-center gap-2"
        >
          <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M15 19l-7-7 7-7" /></svg>
          പുറകോട്ട്
        </button>
      )}
      {nextStep && (
        <button 
          disabled={disabled}
          onClick={() => setStep(nextStep)}
          className="flex-1 max-w-xs h-14 bg-emerald-900 hover:bg-emerald-800 disabled:bg-slate-200 disabled:text-slate-400 text-white rounded-2xl font-bold text-lg transition-all active:scale-95 shadow-xl shadow-emerald-900/10 malayalam flex items-center justify-center gap-2 group"
        >
          <span>{nextLabel}</span>
          {!disabled && <svg className="w-5 h-5 group-hover:translate-x-1 transition-transform" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M9 5l7 7-7 7" /></svg>}
        </button>
      )}
    </div>
  </div>
);

const App: React.FC = () => {
  const [step, setStep] = useState<AppStep>(AppStep.WELCOME);
  const [deceasedGender, setDeceasedGender] = useState<'Male' | 'Female' | null>(null);
  const [heirs, setHeirs] = useState<Heir[]>([]);
  const [estate, setEstate] = useState<EstateData>({
    totalAssets: 0,
    debts: 0,
    funeral: 0,
    will: 0
  });
  const [result, setResult] = useState<CalculationResult | null>(null);

  const heirCategories = useMemo(() => {
    const cats: Record<string, HeirType[]> = {};
    Object.entries(HEIR_METADATA).forEach(([type, meta]) => {
      if (!cats[meta.category]) cats[meta.category] = [];
      cats[meta.category].push(type as HeirType);
    });
    return cats;
  }, []);

  const updateHeirCount = (type: HeirType, delta: number) => {
    const meta = HEIR_METADATA[type];
    setHeirs(prev => {
      const existing = prev.find(h => h.type === type);
      if (existing) {
        let newCount = existing.count + delta;
        if (meta.max) newCount = Math.min(newCount, meta.max);
        newCount = Math.max(0, newCount);
        if (newCount === 0) return prev.filter(h => h.type !== type);
        return prev.map(h => h.type === type ? { ...h, count: newCount } : h);
      } else if (delta > 0) {
        return [...prev, { type, count: 1 }];
      }
      return prev;
    });
  };

  const getHeirCount = (type: HeirType) => heirs.find(h => h.type === type)?.count || 0;

  const handleCalculate = () => {
    if (deceasedGender) {
      const calcResult = calculateShares(heirs, deceasedGender, estate);
      setResult(calcResult);
      setStep(AppStep.RESULT);
    }
  };

  const reset = () => {
    setHeirs([]);
    setDeceasedGender(null);
    setEstate({ totalAssets: 0, debts: 0, funeral: 0, will: 0 });
    setResult(null);
    setStep(AppStep.WELCOME);
  };

  // --- Screens ---

  if (step === AppStep.WELCOME) {
    return (
      <div className="min-h-screen bg-emerald-950 flex flex-col items-center justify-center p-8 text-white relative overflow-hidden">
        <div className="absolute inset-0 opacity-10 islamic-pattern"></div>
        <div className="relative z-10 flex flex-col items-center text-center animate-slide-up">
          <div className="w-32 h-32 bg-emerald-600 rounded-[3rem] flex items-center justify-center mb-10 shadow-3xl shadow-emerald-500/20 rotate-6 hover:rotate-0 transition-transform duration-500">
            <svg className="w-16 h-16 text-emerald-50" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1.5} d="M12 6.253v13m0-13C10.832 5.477 9.246 5 7.5 5S4.168 5.477 3 6.253v13C4.168 18.477 5.754 18 7.5 18s3.332.477 4.5 1.253m0-13C13.168 5.477 14.754 5 16.5 5c1.747 0 3.332.477 4.5 1.253v13C19.832 18.247 18.247 18 16.5 18c-1.746 0-3.332.477-4.5 1.253" />
            </svg>
          </div>
          <h1 className="text-4xl md:text-5xl font-extrabold mb-4 malayalam tracking-tight">ഫറാഇദ് കാൽക്കുലേറ്റർ</h1>
          <p className="text-emerald-300 max-w-sm mb-16 text-lg malayalam leading-relaxed opacity-80">
            ഇസ്ലാമിക അവകാശവിഹിതം ലളിതമായും കൃത്യമായും കണക്കാക്കാം
          </p>
          <button 
            onClick={() => setStep(AppStep.DESCRIPTION)}
            className="w-full max-w-xs bg-emerald-500 hover:bg-emerald-400 text-emerald-950 py-5 rounded-2xl font-bold text-xl transition-all active:scale-95 shadow-2xl shadow-emerald-500/30 malayalam"
          >
            തുടരുക
          </button>
        </div>
      </div>
    );
  }

  if (step === AppStep.DESCRIPTION) {
    return (
      <ScreenWrapper nextStep={AppStep.HADITH} prevStep={AppStep.WELCOME} setStep={setStep}>
        <div className="text-center space-y-8">
          <div className="w-24 h-24 bg-emerald-50 text-emerald-700 rounded-full flex items-center justify-center mx-auto mb-4 border border-emerald-100">
             <svg className="w-12 h-12" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1.5} d="M13 16h-1v-4h-1m1-4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z" /></svg>
          </div>
          <h3 className="text-2xl font-bold text-emerald-900 malayalam">വിവരണം</h3>
          <p className="malayalam text-slate-600 leading-relaxed text-xl font-medium px-4">
            ഖുര്‍ആനും സുന്നത്തും അടിസ്ഥാനമാക്കി മരണപ്പെട്ട വ്യക്തിയുടെ സ്വത്ത് ന്യായമായ വിധത്തിൽ ആരെല്ലാമാണ് ലഭിക്കേണ്ടത് എന്ന് കണക്കാക്കാനുള്ള ഉപകരണം ആണ് ഫറാഇദ് കാൽക്കുലേറ്റർ.
          </p>
          <p className="malayalam text-slate-500 leading-relaxed text-base px-6">
            കേരളത്തിലെ മുസ്ലിം ഉപയോക്താക്കൾക്ക് ലളിതമായ രീതിയിൽ വിവരങ്ങൾ ലഭ്യമാക്കാൻ ഇത് സഹായിക്കുന്നു.
          </p>
        </div>
      </ScreenWrapper>
    );
  }

  if (step === AppStep.HADITH) {
    return (
      <ScreenWrapper nextStep={AppStep.AYAH} prevStep={AppStep.DESCRIPTION} setStep={setStep}>
        <div className="w-full space-y-10">
          <div className="bg-white p-10 rounded-[3rem] border border-emerald-100 shadow-xl shadow-emerald-900/5 text-center relative overflow-hidden group">
            <div className="absolute top-0 right-0 w-32 h-32 bg-emerald-50 rounded-bl-full -mr-16 -mt-16 opacity-50 group-hover:scale-110 transition-transform"></div>
            <header className="mb-8">
              <span className="text-[11px] text-emerald-600 font-extrabold tracking-[0.3em] uppercase">Hadith</span>
              <div className="w-10 h-1 bg-emerald-200 mx-auto mt-2 rounded-full"></div>
            </header>
            <p className="arabic text-4xl mb-8 text-emerald-950 font-bold leading-relaxed">"تَعَلَّمُوا الْفَرَائِضَ وَعَلِّمُوهَا النَّاسَ"</p>
            <p className="malayalam text-emerald-900 leading-relaxed font-bold text-xl">"ഫറാഇദ് (ഇസ്ലാമിക അവകാശവിഭാഗം) പഠിക്കൂ, അത് ആളുകളെ പഠിപ്പിക്കൂ."</p>
          </div>
          <p className="malayalam text-slate-500 text-center text-lg italic px-4">ഫറാഇദ് പഠിക്കുന്നത് സമൂഹത്തിലെ അവകാശവിതരണത്തിൽ നീതി ഉറപ്പാക്കുന്നു.</p>
        </div>
      </ScreenWrapper>
    );
  }

  if (step === AppStep.AYAH) {
    return (
      <ScreenWrapper nextStep={AppStep.ASSETS} prevStep={AppStep.HADITH} setStep={setStep}>
        <div className="w-full space-y-10">
          <div className="bg-white p-10 rounded-[3rem] border border-amber-100 shadow-xl shadow-amber-900/5 text-center relative overflow-hidden group">
            <div className="absolute top-0 left-0 w-32 h-32 bg-amber-50 rounded-br-full -ml-16 -mt-16 opacity-50 group-hover:scale-110 transition-transform"></div>
            <header className="mb-8">
              <span className="text-[11px] text-amber-600 font-extrabold tracking-[0.3em] uppercase">Quran 4:11</span>
              <div className="w-10 h-1 bg-amber-200 mx-auto mt-2 rounded-full"></div>
            </header>
            <p className="arabic text-3xl mb-8 text-amber-950 font-bold leading-[2]">"يُوصِيكُمُ اللَّهُ فِي أَوْلَادِكُمْ لِلذَّكَرِ مِثْلُ حَظِّ الْأُنْثَيَيْنِ"</p>
            <p className="malayalam text-amber-900 leading-relaxed font-bold text-lg">"നിങ്ങളുടെ മക്കളെ സംബന്ധിച്ച് അല്ലാഹു നിങ്ങളെ ഉപദേശിക്കുന്നു; ആൺകുട്ടിക്ക് രണ്ട് പെൺകുട്ടികളുടെ ഓഹരിക്ക് തുല്യമായിരിക്കും."</p>
          </div>
          <p className="malayalam text-slate-500 text-center text-lg italic px-4">ഖുര്‍ആനിൽ സുതാര്യമായി അവകാശവിതരണ നിയമങ്ങൾ നിർദ്ദേശിച്ചിട്ടുണ്ട്.</p>
        </div>
      </ScreenWrapper>
    );
  }

  if (step === AppStep.ASSETS) {
    return (
      <div className="min-h-screen bg-[#fdfdfb] flex flex-col p-6 animate-slide-up pb-28 islamic-pattern">
        <header className="mb-10 mt-8 text-center max-w-md mx-auto">
          <h2 className="text-3xl font-black text-emerald-950 mb-3 malayalam">സ്വത്ത് വിവരങ്ങൾ</h2>
          <p className="text-slate-500 text-sm malayalam leading-relaxed">ലഭ്യമായ ആസ്തിയും കടങ്ങളും കൃത്യമായി രേഖപ്പെടുത്തുക.</p>
        </header>

        <div className="space-y-4 max-w-md mx-auto w-full">
          {[
            { label: 'ആസ്തി (മൊത്തം സ്വത്ത്)', key: 'totalAssets', icon: 'M12 8c-1.657 0-3 1.343-3 3s1.343 3 3 3 3-1.343 3-3-1.343-3-3-3z M12 2C6.477 2 2 6.477 2 12s4.477 10 10 10 10-4.477 10-10S17.523 2 12 2zm0 18c-4.411 0-8-3.589-8-8s3.589-8 8-8 8 3.589 8 8-3.589 8-8 8z' },
            { label: 'കടം (കരുതേണ്ട കുടിശ്ശിക)', key: 'debts', icon: 'M12 8v4m0 4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z' },
            { label: 'മരണാനന്തര ചെലവുകൾ', key: 'funeral', icon: 'M5 13l4 4L19 7' },
            { label: 'വസീയ്യത്ത് (Will)', key: 'will', icon: 'M9 12h6m-6 4h6m2 5H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z' }
          ].map(field => (
            <div key={field.key} className="bg-white p-5 rounded-3xl border border-emerald-100/50 shadow-sm space-y-3 focus-within:ring-2 focus-within:ring-emerald-500/20 transition-all">
              <div className="flex items-center gap-3 mb-1">
                <svg className="w-5 h-5 text-emerald-600" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d={field.icon} /></svg>
                <label className="text-sm font-bold text-emerald-900 malayalam">{field.label}</label>
              </div>
              <div className="relative">
                <span className="absolute left-4 top-1/2 -translate-y-1/2 text-emerald-300 font-bold text-xl">₹</span>
                <input 
                  type="number" 
                  value={(estate as any)[field.key] || ''}
                  onChange={e => setEstate({...estate, [field.key]: Math.max(0, Number(e.target.value))})}
                  className="w-full bg-emerald-50/30 border-2 border-transparent focus:border-emerald-500 focus:bg-white rounded-2xl py-4 pl-12 pr-4 outline-none transition-all font-bold text-xl text-emerald-950 placeholder-emerald-200"
                  placeholder="0"
                />
              </div>
            </div>
          ))}
        </div>

        <div className="fixed bottom-0 left-0 right-0 p-6 glass border-t border-emerald-100 flex justify-center gap-4 z-50">
          <button onClick={() => setStep(AppStep.AYAH)} className="flex-1 max-w-[120px] h-14 border-2 border-emerald-100 bg-emerald-50/50 text-emerald-800 rounded-2xl font-bold active:scale-95 malayalam">പുറകോട്ട്</button>
          <button onClick={() => setStep(AppStep.GENDER)} className="flex-1 max-w-xs h-14 bg-emerald-900 text-white rounded-2xl font-bold text-lg shadow-xl shadow-emerald-900/10 malayalam">അടുത്തത്</button>
        </div>
      </div>
    );
  }

  if (step === AppStep.GENDER) {
    return (
      <ScreenWrapper nextStep={deceasedGender ? AppStep.SELECTION : undefined} prevStep={AppStep.ASSETS} setStep={setStep} disabled={!deceasedGender}>
        <div className="text-center space-y-12 w-full">
          <header>
            <h2 className="text-3xl font-black text-emerald-950 malayalam mb-2">മരണപ്പെട്ട വ്യക്തി</h2>
            <p className="text-slate-500 malayalam">ആരാണ് മരണപ്പെട്ടത് എന്ന് തിരഞ്ഞെടുക്കുക.</p>
          </header>

          <div className="grid grid-cols-1 gap-5 w-full">
            {[
              { id: 'Male', label: 'പുരുഷൻ', sub: 'Male' },
              { id: 'Female', label: 'സ്ത്രീ', sub: 'Female' }
            ].map((opt) => (
              <button 
                key={opt.id}
                onClick={() => setDeceasedGender(opt.id as any)}
                className={`group w-full py-10 rounded-[2.5rem] font-black text-2xl transition-all malayalam flex flex-col items-center justify-center gap-2 border-4 ${deceasedGender === opt.id ? 'bg-emerald-900 border-emerald-500 text-white shadow-2xl shadow-emerald-900/20' : 'bg-white border-emerald-50 text-emerald-800 hover:border-emerald-200'}`}
              >
                <span className="text-3xl">{opt.label}</span>
                <span className={`text-[11px] font-extrabold tracking-widest uppercase opacity-40 group-hover:opacity-60 transition-opacity ${deceasedGender === opt.id ? 'text-emerald-100' : 'text-emerald-900'}`}>{opt.sub}</span>
              </button>
            ))}
          </div>
        </div>
      </ScreenWrapper>
    );
  }

  if (step === AppStep.SELECTION) {
    return (
      <div className="min-h-screen bg-[#fdfdfb] flex flex-col p-6 pb-32 animate-slide-up islamic-pattern">
        <header className="mb-10 mt-8 text-center max-w-md mx-auto">
          <h2 className="text-3xl font-black text-emerald-950 mb-2 malayalam">ബന്ധുക്കൾ</h2>
          <p className="text-slate-500 text-sm malayalam leading-relaxed">അർഹരായ ഓരോ ബന്ധുക്കളെയും തിരഞ്ഞെടുക്കുക.</p>
        </header>

        <div className="space-y-10 max-w-md mx-auto w-full">
          {(Object.entries(heirCategories) as [string, HeirType[]][]).map(([category, types]) => {
            const filteredTypes = types.filter(t => {
              if (t === 'Husband' && deceasedGender === 'Male') return false;
              if (t === 'Wife' && deceasedGender === 'Female') return false;
              return true;
            });
            if (filteredTypes.length === 0) return null;

            return (
              <div key={category} className="space-y-5">
                <h4 className="text-[10px] font-extrabold text-emerald-600/50 uppercase tracking-[0.4em] ml-2 malayalam">{category}</h4>
                <div className="grid grid-cols-1 gap-4">
                  {filteredTypes.map(type => {
                    const count = getHeirCount(type);
                    const meta = HEIR_METADATA[type];
                    return (
                      <div key={type} className={`p-6 rounded-[2rem] border transition-all duration-300 flex items-center justify-between ${count > 0 ? 'bg-emerald-900 border-emerald-700 shadow-lg shadow-emerald-900/10' : 'bg-white border-emerald-50 shadow-sm'}`}>
                        <div className="flex flex-col">
                          <span className={`font-bold malayalam leading-tight text-lg ${count > 0 ? 'text-white' : 'text-emerald-950'}`}>{meta.ml}</span>
                          <span className={`text-[9px] font-extrabold uppercase tracking-tight ${count > 0 ? 'text-emerald-300' : 'text-emerald-900/30'}`}>{type}</span>
                        </div>
                        <div className={`flex items-center gap-4 p-1 rounded-2xl ${count > 0 ? 'bg-emerald-800' : 'bg-emerald-50'}`}>
                          <button 
                            onClick={() => updateHeirCount(type, -1)}
                            className={`w-11 h-11 rounded-xl shadow-sm flex items-center justify-center transition-all active:scale-90 ${count > 0 ? 'bg-emerald-700 text-white' : 'bg-white text-emerald-300'}`}
                          >
                            <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M20 12H4" /></svg>
                          </button>
                          <span className={`w-8 text-center font-black text-xl ${count > 0 ? 'text-white' : 'text-emerald-950'}`}>{count}</span>
                          <button 
                            disabled={meta.max ? count >= meta.max : false}
                            onClick={() => updateHeirCount(type, 1)}
                            className={`w-11 h-11 rounded-xl shadow-sm flex items-center justify-center transition-all active:scale-90 disabled:opacity-30 ${count > 0 ? 'bg-emerald-700 text-white' : 'bg-white text-emerald-800'}`}
                          >
                            <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M12 4v16m8-8H4" /></svg>
                          </button>
                        </div>
                      </div>
                    );
                  })}
                </div>
              </div>
            );
          })}
        </div>

        <div className="fixed bottom-0 left-0 right-0 p-6 glass border-t border-emerald-100 flex justify-center gap-4 z-50">
          <button onClick={() => setStep(AppStep.GENDER)} className="flex-1 max-w-[120px] h-14 border-2 border-emerald-100 bg-emerald-50/50 text-emerald-800 rounded-2xl font-bold active:scale-95 malayalam">പുറകോട്ട്</button>
          <button 
            disabled={heirs.length === 0}
            onClick={handleCalculate} 
            className="flex-1 max-w-xs h-14 bg-emerald-900 text-white rounded-2xl font-bold text-xl shadow-xl disabled:bg-slate-100 disabled:text-slate-300 malayalam"
          >
            കണക്കാക്കുക
          </button>
        </div>
      </div>
    );
  }

  if (step === AppStep.RESULT && result) {
    return (
      <div className="min-h-screen bg-[#fdfdfb] flex flex-col p-6 py-14 animate-slide-up islamic-pattern">
        <header className="mb-12 text-center space-y-5 max-w-md mx-auto">
          <h2 className="text-3xl font-black text-emerald-950 malayalam">അവകാശ വിഹിതങ്ങൾ</h2>
          <div className="bg-emerald-900 text-white px-10 py-6 rounded-[2.5rem] inline-block shadow-2xl shadow-emerald-900/30 relative group overflow-hidden">
             <div className="absolute top-0 right-0 w-24 h-24 bg-white/5 rounded-full -mr-12 -mt-12 transition-transform group-hover:scale-110"></div>
             <p className="text-[10px] uppercase font-black tracking-[0.3em] mb-2 opacity-60">Net Estate</p>
             <p className="text-3xl font-black">₹{result.netEstate.toLocaleString()}</p>
          </div>
        </header>

        <div className="max-w-xl mx-auto w-full space-y-8 flex-1">
          {result.warnings.map((w, i) => (
            <div key={i} className="bg-rose-50 text-rose-800 p-6 rounded-[2.5rem] border border-rose-100 text-sm font-bold flex gap-4 items-start shadow-sm">
              <div className="bg-rose-100 p-2 rounded-xl text-rose-600">
                <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z" /></svg>
              </div>
              <span className="malayalam leading-relaxed">{w}</span>
            </div>
          ))}

          {result.complex && (
            <div className="bg-amber-50 text-amber-900 p-8 rounded-[3rem] border-2 border-amber-100 text-center shadow-xl shadow-amber-900/5 malayalam space-y-2">
              <p className="font-black text-xl">സങ്കീർണ്ണമായ കേസ്</p>
              <p className="text-sm opacity-80 leading-relaxed">വിപുലമായ നിയമങ്ങൾ ബാധകമായതിനാൽ കൃത്യതയ്ക്കായി ഒരു പണ്ഡിതനെ സമീപിക്കാൻ താൽപ്പര്യപ്പെടുന്നു.</p>
            </div>
          )}

          <div className="bg-white p-4 rounded-[3.5rem] shadow-2xl shadow-emerald-900/5 border border-emerald-50 overflow-hidden divide-y divide-emerald-50/50">
            {result.shares.map((share, i) => (
              <div key={i} className="group flex items-center justify-between p-7 transition-all hover:bg-emerald-50/30">
                <div className="space-y-2">
                  <p className="font-black text-emerald-950 text-2xl malayalam leading-tight">{share.label}</p>
                  <div className="flex items-center gap-3">
                    <p className="text-[10px] text-emerald-800/40 font-extrabold uppercase tracking-widest">{share.percentage}</p>
                    <div className="h-1.5 w-24 bg-emerald-100 rounded-full overflow-hidden">
                       <div className="h-full bg-emerald-600 rounded-full" style={{ width: share.percentage }}></div>
                    </div>
                  </div>
                </div>
                <div className="text-right flex flex-col items-end gap-1">
                  <div className="bg-emerald-50 text-emerald-900 px-6 py-2.5 rounded-2xl font-black text-xl group-hover:bg-emerald-100 transition-colors">{share.fraction}</div>
                  {share.amount !== undefined && <p className="text-xs font-bold text-emerald-800/30">₹{share.amount.toLocaleString()}</p>}
                </div>
              </div>
            ))}
            {result.shares.length === 0 && (
              <div className="p-20 text-center text-slate-300 malayalam italic text-lg">അർഹരായ അവകാശികളെ കണ്ടെത്താനായില്ല.</div>
            )}
          </div>
        </div>

        <div className="flex flex-col gap-4 mt-16 max-w-md mx-auto w-full mb-12">
          <button 
            onClick={() => setStep(AppStep.SELECTION)}
            className="w-full bg-emerald-950 text-white h-16 rounded-2xl font-black text-lg transition-all active:scale-95 shadow-2xl shadow-emerald-950/20 flex items-center justify-center gap-2 group malayalam"
          >
            <svg className="w-5 h-5 group-hover:-translate-x-1 transition-transform" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M11 5L6 10l5 5M6 10h12" /></svg>
            <span>വിവരങ്ങൾ മാറ്റുക</span>
          </button>
          <button 
            onClick={reset}
            className="w-full border-2 border-emerald-100 bg-white text-emerald-800 h-16 rounded-2xl font-black text-lg transition-all active:scale-95 malayalam"
          >
            പുതിയ കണക്ക് തുടങ്ങുക
          </button>
        </div>
      </div>
    );
  }

  return null;
};

export default App;

export enum AppStep {
  WELCOME = 'WELCOME',
  DESCRIPTION = 'DESCRIPTION',
  HADITH = 'HADITH',
  AYAH = 'AYAH',
  ASSETS = 'ASSETS',
  GENDER = 'GENDER',
  SELECTION = 'SELECTION',
  RESULT = 'RESULT'
}

