    funeral: 0,
    will: 0
  });
  const [result, setResult] = useState<CalculationResult | null>(null);
  const [showRules, setShowRules] = useState(false);

  const heirCategories = useMemo(() => {
    const cats: Record<string, HeirType[]> = {};
    Object.entries(HEIR_METADATA).forEach(([type, meta]) => {
      if (!cats[meta.category]) cats[meta.category] = [];
      cats[meta.category].push(type as HeirType);
    });
    return cats;
  }, []);

  const updateHeirCount = (type: HeirType, delta: number) => {
    const meta = HEIR_METADATA[type];
    setHeirs(prev => {
      const existing = prev.find(h => h.type === type);
      if (existing) {
        let newCount = existing.count + delta;
        if (meta.max) newCount = Math.min(newCount, meta.max);
        newCount = Math.max(0, newCount);
        if (newCount === 0) return prev.filter(h => h.type !== type);
        return prev.map(h => h.type === type ? { ...h, count: newCount } : h);
      } else if (delta > 0) {
        return [...prev, { type, count: 1 }];
      }
      return prev;
    });
  };

  const getHeirCount = (type: HeirType) => heirs.find(h => h.type === type)?.count || 0;

  const handleCalculate = () => {
    if (deceasedGender) {
      const calcResult = calculateShares(heirs, deceasedGender, estate);
      setResult(calcResult);
      setStep(AppStep.RESULT);
    }
  };

  const reset = () => {
    setHeirs([]);
    setDeceasedGender(null);
    setEstate({ totalAssets: 0, debts: 0, funeral: 0, will: 0 });
    setResult(null);
    setStep(AppStep.WELCOME);
  };

  // --- Screens ---

  if (step === AppStep.WELCOME) {
    return (
      <div className="min-h-screen bg-emerald-950 flex flex-col items-center justify-center p-6 text-white relative overflow-hidden">
        {showRules && <RulesContent onClose={() => setShowRules(false)} />}
        <div className="absolute inset-0 opacity-10 islamic-pattern"></div>
        <div className="relative z-10 flex flex-col items-center text-center animate-slide-up w-full max-w-xs">
          <div className="w-24 h-24 bg-emerald-600 rounded-[2.2rem] flex items-center justify-center mb-8 shadow-2xl shadow-emerald-500/20 rotate-3 hover:rotate-0 transition-transform duration-500">
            <svg className="w-12 h-12 text-emerald-50" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1.5} d="M12 6.253v13m0-13C10.832 5.477 9.246 5 7.5 5S4.168 5.477 3 6.253v13C4.168 18.477 5.754 18 7.5 18s3.332.477 4.5 1.253m0-13C13.168 5.477 14.754 5 16.5 5c1.747 0 3.332.477 4.5 1.253v13C19.832 18.247 18.247 18 16.5 18c-1.746 0-3.332.477-4.5 1.253" />
            </svg>
          </div>
          <h1 className="text-3xl font-extrabold mb-3 malayalam tracking-tight">ഫറാഇദ് കാൽക്കുലേറ്റർ</h1>
          <p className="text-emerald-300 mb-10 text-base malayalam leading-relaxed opacity-80 italic px-4">
            ഷാഫിഈ മദ്ഹബ് പ്രകാരമുള്ള കൃത്യമായ അവകാശവിഹിതം
          </p>
          <div className="flex flex-col gap-3 w-full">
            <button 
              onClick={() => setStep(AppStep.DESCRIPTION)}
              className="w-full bg-emerald-500 hover:bg-emerald-400 text-emerald-950 py-3.5 rounded-xl font-bold text-lg transition-all active:scale-95 shadow-xl shadow-emerald-500/20 malayalam"
            >
              തുടരുക
            </button>
            <button 
              onClick={() => setShowRules(true)}
              className="w-full bg-emerald-900/40 border-2 border-emerald-800 text-emerald-100/90 py-3 rounded-xl font-bold text-base transition-all active:scale-95 malayalam flex items-center justify-center gap-2"
            >
              <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M12 6.253v13m0-13C10.832 5.477 9.246 5 7.5 5S4.168 5.477 3 6.253v13C4.168 18.477 5.754 18 7.5 18s3.332.477 4.5 1.253m0-13C13.168 5.477 14.754 5 16.5 5c1.747 0 3.332.477 4.5 1.253v13C19.832 18.247 18.247 18 16.5 18c-1.746 0-3.332.477-4.5 1.253" /></svg>
              നിയമങ്ങൾ കാണുക
            </button>
          </div>
        </div>
      </div>
    );
  }

  if (step === AppStep.DESCRIPTION) {
    return (
      <ScreenWrapper nextStep={AppStep.HADITH} prevStep={AppStep.WELCOME} setStep={setStep}>
        <div className="text-center space-y-6">
          <div className="w-20 h-20 bg-emerald-50 text-emerald-700 rounded-full flex items-center justify-center mx-auto mb-2 border border-emerald-100 shadow-sm">
             <svg className="w-10 h-10" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1.5} d="M13 16h-1v-4h-1m1-4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z" /></svg>
          </div>
          <h3 className="text-xl font-bold text-emerald-900 malayalam">ഷാഫിഈ ഫിഖ്ഹ്</h3>
          <p className="malayalam text-slate-600 leading-relaxed text-lg font-medium px-2">
            ഈ ഉപകരണം പൂർണ്ണമായും <b>ഷാഫിഈ മദ്ഹബ്</b> പ്രകാരമുള്ള അവകാശ നിയമങ്ങൾ അടിസ്ഥാനമാക്കിയുള്ളതാണ്.
          </p>
          <p className="malayalam text-slate-500 leading-relaxed text-sm px-4">
            കേരളത്തിലെ മുസ്ലിംകൾക്കിടയിൽ പൊതുവെ നിലനിൽക്കുന്ന ഫിഖ്ഹ് നിയമങ്ങൾ ഇതിൽ ലഭ്യമാണ്.
          </p>
        </div>
      </ScreenWrapper>
    );
  }

  if (step === AppStep.HADITH) {
    return (
      <ScreenWrapper nextStep={AppStep.AYAH} prevStep={AppStep.DESCRIPTION} setStep={setStep}>
        <div className="w-full space-y-8">
          <div className="bg-white p-8 rounded-[2rem] border border-emerald-50 shadow-sm text-center relative overflow-hidden">
            <header className="mb-6">
              <span className="text-[10px] text-emerald-600 font-extrabold tracking-[0.2em] uppercase italic opacity-70">Hadith</span>
            </header>
            <div className="mb-6">
               <span className="arabic text-[26px] text-emerald-950 font-semibold leading-relaxed">أَلْحِقُوا الْفَرَائِضَ بِأَهْلِهَا فَمَا بَقِيَ فَهُوَ لِأَوْلَى رَجُلٍ ذَكَرٍ</span>
            </div>
            <p className="malayalam text-emerald-900 leading-relaxed font-bold text-lg px-2">"അവകാശവിഹിതങ്ങൾ അവയ്ക്ക് അർഹരായവർക്ക് എത്തിക്കുക. ബാക്കി ഏറ്റവും അടുത്ത പുരുഷ ബന്ധുവിനുള്ളതാണ്."</p>
          </div>
        </div>
      </ScreenWrapper>
    );
  }

  if (step === AppStep.AYAH) {
    return (
      <ScreenWrapper nextStep={AppStep.ASSETS} prevStep={AppStep.HADITH} setStep={setStep}>
        <div className="w-full space-y-8">
          <div className="bg-white p-8 rounded-[2rem] border border-amber-50 shadow-sm text-center relative overflow-hidden">
            <header className="mb-6">
              <span className="text-[10px] text-amber-600 font-extrabold tracking-[0.2em] uppercase italic opacity-70">Surah An-Nisa 4:11</span>
            </header>
            <div className="mb-6">
              <span className="arabic text-[22px] text-amber-950 font-semibold leading-[1.8]">يُوصِيكُمُ اللَّهُ فِي أَوْلَادِكُمْ لِلذَّكَرِ مِثْلُ حَظِّ الْأُنْثَيَيْنِ</span>
            </div>
            <p className="malayalam text-amber-900 leading-relaxed font-bold text-base px-2">"നിങ്ങളുടെ മക്കളുടെ കാര്യത്തിൽ അല്ലാഹു കൽപ്പിക്കുന്നു; ആണിന് രണ്ട് പെണ്ണിന്റെ വിഹിതത്തിന് തുല്യമായതുണ്ട്."</p>
          </div>
        </div>
      </ScreenWrapper>
    );
  }

  if (step === AppStep.ASSETS) {
    return (
      <div className="min-h-screen bg-[#f8faf9] flex flex-col p-5 animate-slide-up pb-24 islamic-pattern">
        <header className="mb-8 mt-6 text-center max-w-xs mx-auto">
          <h2 className="text-2xl font-black text-emerald-950 mb-2 malayalam">സ്വത്ത് വിവരങ്ങൾ</h2>
          <p className="text-slate-500 text-[13px] malayalam leading-relaxed">വിതരണത്തിന് മുൻപ് കടങ്ങളും ബാധ്യതകളും കുറയ്ക്കേണ്ടതുണ്ട്.</p>
        </header>

        <div className="space-y-3 max-w-sm mx-auto w-full">
          {[
            { label: 'ആസ്തി (മൊത്തം സ്വത്ത്):', key: 'totalAssets' },
            { label: 'കടം (ബാധ്യതകൾ):', key: 'debts' },
            { label: 'മരണാനന്തര കർമ്മങ്ങൾ:', key: 'funeral' },
            { label: 'വസീയ്യത്ത് (പരമാവധി 1/3):', key: 'will' }
          ].map(field => (
            <div key={field.key} className="bg-white p-4 rounded-2xl border border-slate-100 shadow-sm space-y-2">
              <label className="text-[12px] font-bold text-emerald-900 malayalam uppercase tracking-wide opacity-80">{field.label}</label>
              <div className="relative">
                <span className="absolute left-3.5 top-1/2 -translate-y-1/2 text-emerald-300 font-bold text-lg">₹</span>
                <input 
                  type="number" 
                  value={(estate as any)[field.key] || ''}
                  onChange={e => setEstate({...estate, [field.key]: Math.max(0, Number(e.target.value))})}
                  className="w-full bg-slate-50 border border-transparent focus:border-emerald-500/30 focus:bg-white rounded-xl py-3 pl-10 pr-4 outline-none transition-all font-bold text-lg text-emerald-950 placeholder-slate-200"
                  placeholder="0"
                />
              </div>
            </div>
          ))}
        </div>

        <div className="fixed bottom-0 left-0 right-0 p-4 glass border-t border-emerald-100/30 flex justify-center gap-3 z-50">
          <button onClick={() => setStep(AppStep.AYAH)} className="flex-1 max-w-[100px] h-12 border border-slate-200 bg-white text-emerald-800 rounded-xl font-bold active:scale-95 malayalam text-sm">പുറകോട്ട്</button>
          <button onClick={() => setStep(AppStep.GENDER)} className="flex-1 max-w-xs h-12 bg-emerald-900 text-white rounded-xl font-bold text-base shadow-lg shadow-emerald-900/10 malayalam">അടുത്തത്</button>
        </div>
      </div>
    );
  }

  if (step === AppStep.GENDER) {
    return (
      <ScreenWrapper nextStep={deceasedGender ? AppStep.SELECTION : undefined} prevStep={AppStep.ASSETS} setStep={setStep} disabled={!deceasedGender}>
        <div className="text-center space-y-10 w-full">
          <header>
            <h2 className="text-2xl font-black text-emerald-950 malayalam mb-2">മരണപ്പെട്ട വ്യക്തി</h2>
          </header>

          <div className="grid grid-cols-1 gap-4 w-full">
            {[
              { id: 'Male', label: 'പുരുഷൻ' },
              { id: 'Female', label: 'സ്ത്രീ' }
            ].map((opt) => (
              <button 
                key={opt.id}
                onClick={() => setDeceasedGender(opt.id as any)}
                className={`w-full py-8 rounded-2xl font-black text-xl transition-all malayalam border-2 ${deceasedGender === opt.id ? 'bg-emerald-900 border-emerald-500 text-white shadow-xl' : 'bg-white border-slate-100 text-emerald-800 hover:border-emerald-200'}`}
              >
                {opt.label}
              </button>
            ))}
          </div>
        </div>
      </ScreenWrapper>
    );
  }

  if (step === AppStep.SELECTION) {
    return (
      <div className="min-h-screen bg-[#f8faf9] flex flex-col p-5 pb-28 animate-slide-up islamic-pattern">
        <header className="mb-6 mt-4 text-center max-w-xs mx-auto">
          <h2 className="text-xl font-black text-emerald-950 mb-1 malayalam">ബന്ധുക്കളെ ചേർക്കുക</h2>
          <p className="text-slate-400 text-[12px] malayalam leading-relaxed px-4">നിലവിലുള്ള ഓരോ ബന്ധുക്കളെയും തിരഞ്ഞെടുക്കുക.</p>
        </header>

        <div className="space-y-5 max-w-sm mx-auto w-full overflow-y-auto pb-4 hide-scrollbar">
          {(Object.entries(heirCategories) as [string, HeirType[]][]).map(([category, types]) => {
            const filteredTypes = types.filter(t => {
              if (t === 'Husband' && deceasedGender === 'Male') return false;
              if (t === 'Wife' && deceasedGender === 'Female') return false;
              return true;
            });
            if (filteredTypes.length === 0) return null;

            return (
              <div key={category} className="space-y-2.5">
                <div className="flex items-center gap-3 px-1">
                  <h4 className="text-[9px] font-extrabold text-emerald-700/50 uppercase tracking-[0.2em] malayalam whitespace-nowrap">{category}</h4>
                  <div className="h-px flex-1 bg-emerald-100/50"></div>
                </div>
                <div className="grid grid-cols-1 gap-2.5">
                  {filteredTypes.map(type => {
                    const count = getHeirCount(type);
                    const meta = HEIR_METADATA[type];
                    return (
                      <div 
                        key={type} 
                        className={`p-3.5 rounded-xl border transition-all duration-300 flex items-center justify-between ${count > 0 ? 'bg-emerald-900 border-emerald-700 shadow-md' : 'bg-white border-slate-100 shadow-sm'}`}
                      >
                        <span className={`font-bold malayalam text-[14px] ${count > 0 ? 'text-white' : 'text-emerald-950'}`}>
                          {meta.ml}
                        </span>
                        <div className={`flex items-center gap-1.5 p-1 rounded-lg ${count > 0 ? 'bg-emerald-800' : 'bg-slate-50'}`}>
                          <button 
                            onClick={() => updateHeirCount(type, -1)}
                            className={`w-8 h-8 rounded-md flex items-center justify-center transition-all active:scale-90 ${count > 0 ? 'bg-emerald-700 text-white' : 'bg-white text-slate-300'}`}
                          >
                            <svg className="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M20 12H4" /></svg>
                          </button>
                          <span className={`w-5 text-center font-bold text-sm ${count > 0 ? 'text-white' : 'text-emerald-950'}`}>
                            {count}
                          </span>
                          <button 
                            disabled={meta.max ? count >= meta.max : false}
                            onClick={() => updateHeirCount(type, 1)}
                            className={`w-8 h-8 rounded-md flex items-center justify-center transition-all active:scale-90 disabled:opacity-30 ${count > 0 ? 'bg-emerald-700 text-white' : 'bg-white text-emerald-800'}`}
                          >
                            <svg className="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M12 4v16m8-8H4" /></svg>
                          </button>
                        </div>
                      </div>
                    );
                  })}
                </div>
              </div>
            );
          })}
        </div>

        <div className="fixed bottom-0 left-0 right-0 p-4 glass border-t border-emerald-100/30 flex justify-center gap-3 z-50">
          <button onClick={() => setStep(AppStep.GENDER)} className="flex-1 max-w-[90px] h-12 border border-slate-200 bg-white text-emerald-800 rounded-xl font-bold active:scale-95 malayalam text-sm">പുറകോട്ട്</button>
          <button 
            disabled={heirs.length === 0}
            onClick={handleCalculate} 
            className="flex-1 max-w-xs h-12 bg-emerald-900 text-white rounded-xl font-black text-base shadow-xl shadow-emerald-900/10 malayalam flex items-center justify-center gap-2"
          >
            <span>കണക്കാക്കുക</span>
          </button>
        </div>
      </div>
    );
  }

  if (step === AppStep.RESULT && result) {
    return (
      <div className="min-h-screen bg-[#f8faf9] flex flex-col p-5 py-10 animate-slide-up islamic-pattern">
        {showRules && <RulesContent onClose={() => setShowRules(false)} />}
        <header className="mb-10 text-center space-y-4 max-w-xs mx-auto">
          <h2 className="text-2xl font-black text-emerald-950 malayalam">അവകാശ വിഹിതങ്ങൾ</h2>
          <div className="bg-emerald-900 text-white px-8 py-5 rounded-[1.8rem] inline-block shadow-xl">
             <p className="text-[9px] uppercase font-bold tracking-[0.2em] mb-1 opacity-60">Net Estate</p>
             <p className="text-2xl font-black">₹{result.netEstate.toLocaleString()}</p>
          </div>
        </header>

        <div className="max-w-md mx-auto w-full space-y-6 flex-1">
          {result.warnings.map((w, i) => (
            <div key={i} className="bg-rose-50/80 text-rose-800 p-4 rounded-2xl border border-rose-100/50 text-xs font-bold flex gap-3 items-start shadow-sm malayalam leading-relaxed">
              <svg className="w-4 h-4 shrink-0 mt-0.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z" /></svg>
              <span>{w}</span>
            </div>
          ))}

          <div className="bg-white p-3 rounded-[2.2rem] shadow-xl border border-emerald-50 overflow-hidden divide-y divide-emerald-50/50">
            {result.shares.map((share, i) => (
              <div key={i} className="flex items-center justify-between p-5 transition-all hover:bg-emerald-50/20">
                <div className="space-y-1">
                  <p className="font-bold text-emerald-950 text-lg malayalam leading-tight">{share.label}</p>
                  <p className="text-[9px] text-emerald-800/40 font-extrabold uppercase tracking-wider">{share.percentage}</p>
                </div>
                <div className="text-right flex flex-col items-end gap-1">
                  <div className="bg-emerald-50 text-emerald-900 px-4 py-1.5 rounded-lg font-black text-base">{share.fraction}</div>
                  {share.amount !== undefined && <p className="text-[10px] font-bold text-slate-300">₹{share.amount.toLocaleString()}</p>}
                </div>
              </div>
            ))}
          </div>
        </div>

        <div className="flex flex-col gap-3 mt-12 max-w-sm mx-auto w-full mb-10">
          <button 
            onClick={() => setShowRules(true)}
            className="w-full bg-white text-emerald-900 border border-emerald-100 h-14 rounded-xl font-bold text-base transition-all active:scale-95 malayalam flex items-center justify-center gap-2"
          >
            <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M12 6.253v13m0-13C10.832 5.477 9.246 5 7.5 5S4.168 5.477 3 6.253v13C4.168 18.477 5.754 18 7.5 18s3.332.477 4.5 1.253m0-13C13.168 5.477 14.754 5 16.5 5c1.747 0 3.332.477 4.5 1.253v13C19.832 18.247 18.247 18 16.5 18c-1.746 0-3.332.477-4.5 1.253" /></svg>
            <span>നിയമങ്ങൾ കാണുക</span>
          </button>
          <button onClick={() => setStep(AppStep.SELECTION)} className="w-full bg-emerald-950 text-white h-14 rounded-xl font-bold text-base shadow-xl malayalam">മാറ്റങ്ങൾ വരുത്തുക</button>
          <button onClick={reset} className="w-full border border-slate-200 bg-slate-50 text-slate-500 h-14 rounded-xl font-bold text-base malayalam">പുതിയ കണക്ക്</button>
        </div>
      </div>
    );
  }

  return null;
};

export default App;

import React, { useState, useMemo } from 'react';
import { AppStep, Heir, HeirType, CalculationResult, HEIR_METADATA, EstateData } from './types';
