const ScreenWrapper: React.FC<ScreenWrapperProps> = ({ 
  children, 
  nextStep, 
  prevStep, 
  setStep, 
  nextLabel = "അടുത്തത്",
  disabled = false
}) => (
  <div className="h-full flex flex-col relative overflow-hidden bg-[#f8faf9]">
