          >
            <span>കണക്കാക്കുക</span>
          </button>
        </div>
      </div>
    );
  }

  if (step === AppStep.RESULT && result) {
    return (
      <div className="h-full bg-[#f8faf9] flex flex-col p-5 py-6 animate-slide-up islamic-pattern overflow-hidden">
