                <span>{w}</span>
              </div>
            ))}

            <div className="bg-white p-2 rounded-[2.2rem] shadow-xl border border-emerald-50 overflow-hidden divide-y divide-emerald-50/50">
              {result.shares.map((share, i) => (
                <div key={i} className="flex items-center justify-between p-4 transition-all hover:bg-emerald-50/20">
                  <div className="space-y-1">
                    <p className="font-bold text-emerald-950 text-lg malayalam leading-tight">{share.label}</p>
