          <div className="grid grid-cols-1 gap-3 w-full">
            {['Male', 'Female'].map((id) => (
              <button key={id} onClick={() => setDeceasedGender(id as any)} className={`w-full py-7 rounded-2xl font-bold text-lg transition-all malayalam border-2 ${deceasedGender === id ? 'bg-emerald-950 border-emerald-950 text-white' : 'bg-white border-slate-100 text-slate-600'}`}>
                {id === 'Male' ? 'പുരുഷൻ' : 'സ്ത്രീ'}
              </button>
            ))}
          </div>
        </div>
      </ScreenWrapper>
    );
  }

  if (step === AppStep.SELECTION) {
    return (
      <div className="h-full bg-[#f8faf9] flex flex-col p-5 animate-slide-up overflow-hidden">
        <header className="mb-4 mt-4 text-center shrink-0">
          <h2 className="text-xl font-black text-emerald-950 mb-1 malayalam">അവകാശികൾ</h2>
          <p className="text-slate-400 text-[11px] malayalam">ബന്ധുക്കളെ തിരഞ്ഞെടുക്കുക.</p>
        </header>
        <div className="flex-1 overflow-y-auto pb-4 space-y-4 max-w-sm mx-auto w-full pr-1">
          {(Object.entries(heirCategories) as [string, HeirType[]][]).map(([category, types]) => {
            const filtered = types.filter(t => (t === 'Husband' ? deceasedGender === 'Female' : t === 'Wife' ? deceasedGender === 'Male' : true));
            if (filtered.length === 0) return null;
            return (
              <div key={category} className="space-y-2">
                <h4 className="text-[10px] font-bold text-slate-400 uppercase tracking-widest malayalam pl-1">{category}</h4>
                <div className="grid grid-cols-1 gap-2">
                  {filtered.map(type => {
                    const count = getHeirCount(type);
                    const meta = HEIR_METADATA[type];
                    return (
                      <div key={type} className={`p-3 rounded-xl border flex items-center justify-between ${count > 0 ? 'bg-emerald-950 border-emerald-950 text-white' : 'bg-white border-slate-100'}`}>
                        <span className="font-bold malayalam text-[13px]">{meta.ml}</span>
                        <div className={`flex items-center gap-1.5 p-1 rounded-lg ${count > 0 ? 'bg-emerald-800/50' : 'bg-slate-50'}`}>
                          <button onClick={() => updateHeirCount(type, -1)} className={`w-7 h-7 rounded-md flex items-center justify-center ${count > 0 ? 'bg-emerald-700 text-white' : 'bg-white text-slate-300'}`}><svg className="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M20 12H4" /></svg></button>
                          <span className="w-4 text-center font-bold text-[13px]">{count}</span>
                          <button disabled={meta.max ? count >= meta.max : false} onClick={() => updateHeirCount(type, 1)} className={`w-7 h-7 rounded-md flex items-center justify-center ${count > 0 ? 'bg-emerald-700 text-white' : 'bg-white text-emerald-800'}`}><svg className="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M12 4v16m8-8H4" /></svg></button>
                        </div>
                      </div>
                    );
                  })}
                </div>
              </div>
            );
          })}
        </div>
        <div className="p-4 glass border-t border-slate-100 flex justify-center gap-3 shrink-0 mt-4">
          <button onClick={() => setStep(AppStep.GENDER)} className="flex-1 max-w-[90px] h-12 border border-slate-200 bg-white text-slate-500 rounded-xl font-bold active:scale-95 malayalam text-sm">പുറകോട്ട്</button>
          <button disabled={heirs.length === 0} onClick={handleCalculate} className="flex-1 max-w-xs h-12 bg-emerald-950 text-white rounded-xl font-black text-base shadow-xl malayalam">കണക്കാക്കുക</button>
        </div>
      </div>
    );
  }

  if (step === AppStep.RESULT && result) {
    return (
      <div className="h-full bg-[#f8faf9] flex flex-col p-5 py-6 animate-slide-up overflow-hidden">
        {showRules && <RulesContent onClose={() => setShowRules(false)} />}
        <header className="mb-6 text-center shrink-0">
          <h2 className="text-xl font-black text-emerald-950 malayalam">അവകാശ വിഹിതങ്ങൾ</h2>
          <div className="bg-emerald-950 text-white px-8 py-4 rounded-2xl inline-block mt-3 shadow-lg">
             <p className="text-[9px] uppercase font-bold tracking-widest opacity-60">Net Estate</p>
             <p className="text-xl font-black">₹{result.netEstate.toLocaleString()}</p>
          </div>
        </header>
        <div className="max-w-md mx-auto w-full flex-1 flex flex-col min-h-0">
          <div className="flex-1 overflow-y-auto space-y-3 pr-1">
            {result.warnings.map((w, i) => (
              <div key={i} className="bg-rose-50 text-rose-800 p-3 rounded-xl border border-rose-100 text-[11px] font-bold flex gap-2 malayalam shrink-0">
                <svg className="w-3.5 h-3.5 shrink-0 mt-0.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z" /></svg>
                {w}
              </div>
            ))}
            <div className="bg-white rounded-[2rem] shadow-sm border border-slate-50 overflow-hidden divide-y divide-slate-50">
              {result.shares.map((share, i) => (
                <div key={i} className="flex items-center justify-between p-4">
                  <div><p className="font-bold text-slate-900 text-[15px] malayalam">{share.label}</p><p className="text-[9px] text-slate-400 font-bold tracking-wider">{share.percentage}</p></div>
                  <div className="text-right"><div className="bg-slate-50 text-emerald-900 px-3 py-1 rounded-lg font-black text-[14px]">{share.fraction}</div>{share.amount !== undefined && <p className="text-[9px] font-bold text-slate-300 mt-1">₹{share.amount.toLocaleString()}</p>}</div>
                </div>
              ))}
            </div>
          </div>
        </div>
        <div className="flex flex-col gap-2 mt-6 max-w-sm mx-auto w-full shrink-0">
          <button onClick={() => setShowRules(true)} className="w-full bg-white text-emerald-900 border border-slate-100 h-13 rounded-xl font-bold text-sm malayalam flex items-center justify-center gap-2 py-3"><svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M12 6.253v13m0-13C10.832 5.477 9.246 5 7.5 5S4.168 5.477 3 6.253v13C4.168 18.477 5.754 18 7.5 18s3.332.477 4.5 1.253m0-13C13.168 5.477 14.754 5 16.5 5c1.747 0 3.332.477 4.5 1.253v13C19.832 18.247 18.247 18 16.5 18c-1.746 0-3.332.477-4.5 1.253" /></svg>നിയമങ്ങൾ കാണുക</button>
          <button onClick={() => setStep(AppStep.SELECTION)} className="w-full bg-emerald-950 text-white h-13 rounded-xl font-bold text-sm malayalam py-3">മാറ്റങ്ങൾ വരുത്തുക</button>
          <button onClick={reset} className="w-full text-slate-400 font-bold text-[12px] malayalam py-2">പുതിയ കണക്ക്</button>
        </div>
      </div>
    );
  }

  return null;
};

export default App;

