                            onClick={() => updateHeirCount(type, -1)} 
                            className={`w-8 h-8 rounded-lg flex items-center justify-center transition-all ${count > 0 ? 'bg-white/20 text-white' : 'bg-white text-slate-300 border border-slate-100'}`}
