        </div>
      </div>
    );
  }

  // Screen 8: Results
  if (step === AppStep.RESULT && result) {
    return (
      <div className="h-full bg-[#F7FAF7] flex flex-col p-5 py-6 animate-slide-up overflow-hidden">
