            return (
              <div key={category} className="space-y-4">
                <div className="flex items-center gap-4 px-2">
                   <h4 className="text-[11px] font-black text-[#D89F37] uppercase tracking-[0.2em] malayalam whitespace-nowrap">{category}</h4>
                   <div className="h-0.5 w-full bg-[#D89F37] opacity-10 rounded-full"></div>
                </div>
                <div className="grid grid-cols-1 gap-3">
                  {filtered.map(type => {
                    const count = getHeirCount(type);
                    const meta = HEIR_METADATA[type];
                    return (
                      <div key={type} className={`p-5 rounded-[1.8rem] border flex items-center justify-between transition-all duration-500 ${count > 0 ? 'bg-[#006B46] border-[#006B46] text-white shadow-xl shadow-[#006B46]/10' : 'bg-white border-slate-100 shadow-sm'}`}>
                        <div className="flex flex-col gap-0.5">
                          <span className="font-bold malayalam text-[15px] leading-tight tracking-tight">{meta.ml}</span>
                          <span className={`text-[10px] font-bold uppercase tracking-widest ${count > 0 ? 'text-white/50' : 'text-slate-300'}`}>{type}</span>
                        </div>
                        <div className={`flex items-center gap-3 p-1.5 rounded-2xl ${count > 0 ? 'bg-black/10' : 'bg-slate-50'}`}>
                          <button 
                            onClick={() => updateHeirCount(type, -1)} 
                            className={`w-9 h-9 rounded-xl flex items-center justify-center transition-all active:scale-90 ${count > 0 ? 'bg-white/20 text-white' : 'bg-white text-slate-300 border border-slate-100'}`}
                          >
                            <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M20 12H4" /></svg>
                          </button>
                          <span className="w-6 text-center font-black text-[16px]">{count}</span>
                          <button 
                            disabled={meta.max ? count >= meta.max : false} 
                            onClick={() => updateHeirCount(type, 1)} 
                            className={`w-9 h-9 rounded-xl flex items-center justify-center transition-all active:scale-90 ${count > 0 ? 'bg-white/20 text-white' : 'bg-white text-[#006B46] border border-slate-100'}`}
                          >
                            <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M12 4v16m8-8H4" /></svg>
