              </div>
            );
          })}
        </div>

        <div className="p-4 glass border-t border-slate-100 flex justify-center gap-3 shrink-0 mt-4 rounded-3xl">
          <button onClick={() => setStep(AppStep.GENDER)} className="flex-1 max-w-[100px] h-14 border border-slate-200 bg-white text-slate-500 rounded-2xl font-bold active:scale-95 malayalam text-sm">പുറകോട്ട്</button>
          <button disabled={heirs.length === 0} onClick={handleCalculate} className="flex-1 max-w-xs h-14 bg-[#006B46] text-white rounded-2xl font-black text-base shadow-2xl shadow-[#006B46]/20 malayalam">കണക്കാക്കുക</button>
        </div>
      </div>
    );
  }

  // Screen 8: Results
  if (step === AppStep.RESULT && result) {
    return (
      <div className="h-full bg-[#F7FAF7] flex flex-col p-6 py-8 animate-slide-up overflow-hidden">
        {showRules && <RulesContent onClose={() => setShowRules(false)} />}
        <header className="mb-10 text-center shrink-0 space-y-2">
          <h2 className="text-3xl font-black text-[#1E2E4F] malayalam tracking-tight">വിഹിതങ്ങൾ</h2>
          <div className="bg-[#1E2E4F] text-white px-12 py-6 rounded-[2.5rem] inline-block mt-4 shadow-3xl border border-white/5 relative overflow-hidden group">
             <div className="absolute inset-0 bg-gradient-to-br from-[#006B46]/20 to-transparent opacity-50"></div>
             <p className="text-[11px] uppercase font-black tracking-[0.25em] mb-2 opacity-50 relative z-10">വിതരണത്തിനുള്ള തുക</p>
             <p className="text-3xl font-black text-[#D89F37] relative z-10">₹{result.netEstate.toLocaleString()}</p>
          </div>
        </header>

        <div className="max-w-md mx-auto w-full flex-1 flex flex-col min-h-0">
          <div className="flex-1 overflow-y-auto space-y-5 pr-1 hide-scrollbar pb-6">
            {result.warnings.map((w, i) => (
              <div key={i} className="bg-rose-50/60 text-rose-900 p-5 rounded-[1.8rem] border border-rose-100 text-[13px] font-bold flex gap-4 malayalam shrink-0 shadow-sm leading-relaxed word-ready-text">
                <div className="bg-rose-100 p-2 h-fit rounded-full text-rose-600">
                  <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z" /></svg>
                </div>
                {w}
              </div>
            ))}

            <div className="space-y-4">
              {result.shares.map((share, i) => (
                <div key={i} className="bg-white rounded-[2rem] shadow-xl shadow-black/[0.02] border border-slate-50 flex items-center justify-between p-6 transition-all duration-300 hover:border-emerald-100 hover:bg-emerald-50/10">
                  <div className="space-y-1.5">
                    <p className="font-bold text-[#1E2E4F] text-[17px] malayalam leading-tight tracking-tight">{share.label}</p>
                    <p className="text-[11px] text-slate-400 font-black tracking-[0.15em] uppercase">{share.percentage}</p>
                  </div>
                  <div className="text-right flex flex-col items-end gap-2">
                    <div className="bg-[#F7FAF7] text-[#006B46] px-5 py-2 rounded-2xl font-black text-[16px] border border-emerald-50 shadow-inner">{share.fraction}</div>
                    {share.amount !== undefined && <p className="text-[12px] font-black text-[#D89F37] tracking-tight">₹{share.amount.toLocaleString()}</p>}
                  </div>
                </div>
              ))}
            </div>
          </div>
        </div>

        <div className="flex flex-col gap-4 mt-8 max-w-sm mx-auto w-full shrink-0 px-4">
          <button 
            onClick={() => setShowRules(true)} 
            className="w-full bg-white text-[#006B46] border border-emerald-100 h-15 rounded-[1.5rem] font-bold text-base malayalam flex items-center justify-center gap-3 py-4 shadow-xl shadow-emerald-900/[0.03] active:scale-95 transition-all"
          >
            <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M12 6.253v13m0-13C10.832 5.477 9.246 5 7.5 5S4.168 5.477 3 6.253v13C4.168 18.477 5.754 18 7.5 18s3.332.477 4.5 1.253m0-13C13.168 5.477 14.754 5 16.5 5c1.747 0 3.332.477 4.5 1.253v13C19.832 18.247 18.247 18 16.5 18c-1.746 0-3.332.477-4.5 1.253" /></svg>
            നിയമങ്ങൾ കാണുക
          </button>
          <button 
            onClick={() => setStep(AppStep.SELECTION)} 
            className="w-full bg-[#1E2E4F] text-white h-15 rounded-[1.5rem] font-black text-lg malayalam py-4 shadow-2xl shadow-black/20 active:scale-95 transition-all"
          >
            മാറ്റങ്ങൾ വരുത്തുക
          </button>
          <button 
            onClick={reset} 
            className="w-full text-slate-400 font-bold text-[14px] malayalam py-2 hover:text-[#006B46] transition-colors"
          >
            പുതിയ കണക്ക് തുടങ്ങുക
          </button>
        </div>
      </div>
    );
  }

  return null;
};

