                className={`w-full py-12 rounded-[3rem] font-bold transition-all malayalam border-2 flex flex-col items-center gap-3 active-press relative overflow-hidden ${deceasedGender === opt.id ? 'bg-[#1E2E4F] border-[#1E2E4F] text-white shadow-[0_20px_60px_-10px_rgba(30,46,79,0.4)]' : 'bg-white border-slate-100 text-slate-600 hover:border-[#D89F37]/30'}`}
              >
                <span className="text-3xl font-black tracking-tight">{opt.label}</span>
                <span className={`text-[12px] font-black uppercase tracking-[0.3em] ${deceasedGender === opt.id ? 'text-[#D89F37]' : 'opacity-30'}`}>{opt.sub}</span>
                {deceasedGender === opt.id && (
                  <div className="absolute top-6 right-6 text-[#D89F37]">
                    <svg className="w-8 h-8" fill="currentColor" viewBox="0 0 24 24"><path d="M12 2C6.48 2 2 6.48 2 12s4.48 10 10 10 10-4.48 10-10S17.52 2 12 2zm-2 15l-5-5 1.41-1.41L10 14.17l7.59-7.59L19 8l-9 9z"/></svg>
                  </div>
                )}
              </button>
            ))}
          </div>
        </div>
      </ScreenWrapper>
    );
  }

  if (step === AppStep.SELECTION) {
    const categories = Object.keys(heirCategories);
    return (
      <div className="h-full bg-[#F7FAF7] flex flex-col p-6 animate-in overflow-hidden">
        <header className="mb-8 mt-6 text-center shrink-0">
          <h2 className="text-3xl font-black text-[#1E2E4F] malayalam tracking-tight leading-tight">അവകാശികൾ</h2>
          <p className="text-slate-500 text-[14px] malayalam font-medium mt-1">ബന്ധുക്കളുടെ എണ്ണം ചേർക്കുക</p>
        </header>

        {/* Category Chips */}
        <div className="flex gap-2 overflow-x-auto pb-4 hide-scrollbar shrink-0 px-1">
          {categories.map(cat => (
            <button
              key={cat}
              onClick={() => setActiveCategory(cat)}
              className={`px-5 py-3 rounded-full text-[11px] font-black uppercase tracking-widest whitespace-nowrap transition-all active-press ${activeCategory === cat ? 'bg-[#1E2E4F] text-white shadow-lg' : 'bg-white text-slate-400 border border-slate-100'}`}
            >
              {cat}
            </button>
          ))}
        </div>

        <div className="flex-1 overflow-y-auto pb-8 space-y-4 max-w-sm mx-auto w-full pr-1 hide-scrollbar">
          {heirCategories[activeCategory]?.filter(t => (t === 'Husband' ? deceasedGender === 'Female' : t === 'Wife' ? deceasedGender === 'Male' : true))
            .map(type => {
              const count = getHeirCount(type);
              const meta = HEIR_METADATA[type];
              return (
                <div key={type} className={`p-6 rounded-[2.2rem] border flex items-center justify-between transition-all duration-500 ${count > 0 ? 'bg-[#006B46] border-[#006B46] text-white shadow-xl shadow-[#006B46]/10' : 'bg-white border-slate-100 shadow-sm'}`}>
                  <div className="flex flex-col gap-1">
                    <span className="font-black malayalam text-[16px] leading-tight tracking-tight">{meta.ml}</span>
                    <span className={`text-[10px] font-black uppercase tracking-widest ${count > 0 ? 'text-white/40' : 'text-slate-300'}`}>{type}</span>
                  </div>
                  <div className={`flex items-center gap-4 p-2 rounded-2xl ${count > 0 ? 'bg-black/10' : 'bg-slate-50'}`}>
                    <button 
                      onClick={() => updateHeirCount(type, -1)} 
                      className={`w-10 h-10 rounded-xl flex items-center justify-center transition-all active-press ${count > 0 ? 'bg-white/20 text-white' : 'bg-white text-slate-300 border border-slate-100'}`}
                    >
                      <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M20 12H4" /></svg>
                    </button>
                    <span className="w-6 text-center font-black text-[18px]">{count}</span>
                    <button 
                      disabled={meta.max ? count >= meta.max : false} 
                      onClick={() => updateHeirCount(type, 1)} 
                      className={`w-10 h-10 rounded-xl flex items-center justify-center transition-all active-press ${count > 0 ? 'bg-white/20 text-white' : 'bg-white text-[#006B46] border border-slate-100'}`}
                    >
                      <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M12 4v16m8-8H4" /></svg>
                    </button>
                  </div>
                </div>
              );
            })}
        </div>

        <div className="p-5 glass border-t border-slate-100 flex justify-center gap-3 shrink-0 rounded-t-[2.5rem] shadow-[0_-10px_40px_rgba(0,0,0,0.03)] mt-auto">
