        </div>
      </div>
    );
  }

  if (step === AppStep.RESULT && result) {
    return (
      <div className="h-full bg-[#F7FAF7] flex flex-col p-6 py-10 animate-in overflow-hidden">
        {showRules && <RulesContent onClose={() => setShowRules(false)} />}

