             <p className="text-[12px] uppercase font-black tracking-[0.3em] mb-3 opacity-40 relative z-10">വിതരണത്തിന് തയ്യാറുള്ള തുക</p>
             <p className="text-4xl font-black text-[#D89F37] relative z-10">₹{result.netEstate.toLocaleString()}</p>
          </div>
        </header>

        <div className="max-w-md mx-auto w-full flex-1 flex flex-col min-h-0">
          <div className="flex-1 overflow-y-auto space-y-6 pr-1 hide-scrollbar pb-10">
            {result.warnings.length > 0 && (
              <div className="space-y-3">
                {result.warnings.map((w, i) => (
                  <div key={i} className="bg-rose-50/70 text-rose-950 p-6 rounded-[2rem] border border-rose-100 text-[14px] font-bold flex gap-4 malayalam shrink-0 shadow-sm leading-relaxed word-ready-text">
                    <div className="bg-rose-100 p-2.5 h-fit rounded-full text-rose-600 shadow-inner">
                      <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z" /></svg>
                    </div>
                    {w}
                  </div>
                ))}
              </div>
            )}

            <div className="space-y-4">
              {result.shares.map((share, i) => (
                <div key={i} className="bg-white rounded-[2.2rem] shadow-premium border border-slate-50 flex items-center justify-between p-7 transition-all duration-300 hover:border-emerald-100 hover:bg-emerald-50/10 group">
                  <div className="space-y-1.5">
                    <p className="font-black text-[#1E2E4F] text-[18px] malayalam leading-tight tracking-tight group-hover:text-[#006B46] transition-colors">{share.label}</p>
                    <p className="text-[12px] text-slate-400 font-black tracking-[0.2em] uppercase">{share.percentage}</p>
                  </div>
                  <div className="text-right flex flex-col items-end gap-2.5">
                    <div className="bg-[#F7FAF7] text-[#006B46] px-6 py-2.5 rounded-[1.2rem] font-black text-[17px] border border-emerald-50 shadow-inner">{share.fraction}</div>
                    {share.amount !== undefined && <p className="text-[13px] font-black text-[#D89F37] tracking-tight">₹{share.amount.toLocaleString()}</p>}
                  </div>
                </div>
              ))}
            </div>
          </div>
        </div>

        <div className="flex flex-col gap-4 mt-auto max-w-sm mx-auto w-full shrink-0">
          <button 
            onClick={() => setShowRules(true)} 
            className="w-full bg-white text-[#006B46] border border-emerald-100 h-16 rounded-[2rem] font-black text-base malayalam flex items-center justify-center gap-3 py-4 shadow-premium active-press transition-all"
          >
            <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M12 6.253v13m0-13C10.832 5.477 9.246 5 7.5 5S4.168 5.477 3 6.253v13C4.168 18.477 5.754 18 7.5 18s3.332.477 4.5 1.253m0-13C13.168 5.477 14.754 5 16.5 5c1.747 0 3.332.477 4.5 1.253v13C19.832 18.247 18.247 18 16.5 18c-1.746 0-3.332.477-4.5 1.253" /></svg>
            നിയമങ്ങൾ
          </button>
          <button 
            onClick={() => setStep(AppStep.SELECTION)} 
            className="w-full bg-[#1E2E4F] text-white h-16 rounded-[2rem] font-black text-lg malayalam py-4 shadow-3xl active-press transition-all"
          >
            മാറ്റങ്ങൾ വരുത്തുക
          </button>
          <button 
            onClick={reset} 
            className="w-full text-slate-400 font-bold text-[14px] malayalam py-2 hover:text-[#006B46] transition-colors"
          >
            പുതിയ കണക്ക് തുടങ്ങുക
          </button>
        </div>
      </div>
    );
  }

  return null;
};

export default App;

