const App: React.FC = () => {
  const [step, setStep] = useState<AppStep>(AppStep.WELCOME);
  const [deceasedGender, setDeceasedGender] = useState<'Male' | 'Female' | null>(null);
  const [heirs, setHeirs] = useState<Heir[]>([]);
  const [estate, setEstate] = useState<EstateData>({ totalAssets: 0, debts: 0, funeral: 0, will: 0 });
  const [result, setResult] = useState<CalculationResult | null>(null);
  const [showRules, setShowRules] = useState(false);
  const [activeCategory, setActiveCategory] = useState<string>('പ്രാഥമിക കുടുംബം');

  const heirCategories = useMemo(() => {
    const cats: Record<string, HeirType[]> = {};
    Object.entries(HEIR_METADATA).forEach(([type, meta]) => {
      if (!cats[meta.category]) cats[meta.category] = [];
      cats[meta.category].push(type as HeirType);
    });
    return cats;
  }, []);

  const updateHeirCount = (type: HeirType, delta: number) => {
    const meta = HEIR_METADATA[type];
    setHeirs(prev => {
      const existing = prev.find(h => h.type === type);
      if (existing) {
        let newCount = Math.max(0, existing.count + delta);
        if (meta.max) newCount = Math.min(newCount, meta.max);
        if (newCount === 0) return prev.filter(h => h.type !== type);
        return prev.map(h => h.type === type ? { ...h, count: newCount } : h);
      } else if (delta > 0) return [...prev, { type, count: 1 }];
      return prev;
    });
  };

  const getHeirCount = (type: HeirType) => heirs.find(h => h.type === type)?.count || 0;

  const handleCalculate = () => {
    if (deceasedGender) {
      setResult(calculateShares(heirs, deceasedGender, estate));
      setStep(AppStep.RESULT);
    }
  };

  const reset = () => {
    setHeirs([]);
    setDeceasedGender(null);
    setEstate({ totalAssets: 0, debts: 0, funeral: 0, will: 0 });
    setResult(null);
    setStep(AppStep.WELCOME);
  };

  if (step === AppStep.WELCOME) {
    return (
      <div className="h-full bg-[#1E2E4F] flex flex-col items-center justify-center p-8 text-white relative overflow-hidden">
        {showRules && <RulesContent onClose={() => setShowRules(false)} />}

        {/* Background Visual Effects */}
        <div className="absolute top-[-10%] right-[-10%] w-[120%] h-[120%] bg-gradient-to-br from-[#006B46]/25 via-transparent to-[#D89F37]/15 opacity-60"></div>
        <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-96 h-96 bg-[#006B46]/15 rounded-full blur-[140px]"></div>

        <div className="relative z-10 flex flex-col items-center text-center animate-in w-full max-w-sm">
          <div className="relative mb-12">
            <div className="absolute inset-0 bg-[#006B46] blur-3xl opacity-50"></div>
            <div className="w-32 h-32 bg-[#006B46]/90 backdrop-blur-xl rounded-[3rem] flex items-center justify-center shadow-3xl border border-white/20 relative z-10 scale-110">
              <svg className="w-16 h-16 text-[#D89F37]" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1.5} d="M12 6.253v13m0-13C10.832 5.477 9.246 5 7.5 5S4.168 5.477 3 6.253v13C4.168 18.477 5.754 18 7.5 18s3.332.477 4.5 1.253m0-13C13.168 5.477 14.754 5 16.5 5c1.747 0 3.332.477 4.5 1.253v13C19.832 18.247 18.247 18 16.5 18c-1.746 0-3.332.477-4.5 1.253" />
              </svg>
            </div>
          </div>

          <h1 className="text-4xl font-black mb-6 malayalam tracking-tight leading-tight text-white drop-shadow-lg">ഫറാഇദ്<br/>കാൽക്കുലേറ്റർ</h1>
          <p className="text-[#F7FAF7]/70 mb-16 text-lg malayalam leading-relaxed px-6 font-medium">
            ഇസ്‌ലാമിക അനന്തരാവകാശ വിഹിതം കൃത്യമായും ലളിതമായും കണ്ടെത്താം.
          </p>

          <div className="flex flex-col gap-4 w-full px-4">
            <button 
              onClick={() => setStep(AppStep.DESCRIPTION)} 
              className="w-full bg-[#006B46] text-white py-5 rounded-[1.8rem] font-black text-xl active-press shadow-2xl shadow-black/20 malayalam transition-all backdrop-blur-md"
            >
              തുടരുക
            </button>
            <button 
              onClick={() => setShowRules(true)} 
              className="w-full bg-white/10 border border-white/20 text-white/95 py-4 rounded-[1.5rem] font-bold text-lg active-press malayalam transition-all backdrop-blur-xl hover:bg-white/15"
            >
              നിയമങ്ങൾ കാണുക
            </button>
          </div>
        </div>
      </div>
    );
  }

  if (step === AppStep.DESCRIPTION) {
    return (
      <ScreenWrapper currentStep={step} nextStep={AppStep.HADITH} prevStep={AppStep.WELCOME} setStep={setStep}>
        <div className="glass-card rounded-[3rem] p-10 w-full flex flex-col gap-10 animate-in">
          <div className="flex flex-col items-center gap-4">
            <div className="w-16 h-1.5 bg-[#D89F37]/30 rounded-full"></div>
