                    </div>
                    {w}
                  </div>
                ))}
              </div>
            )}

            <div className="space-y-4">
              {result.shares.map((share, i) => (
                <div key={i} className="glass-card rounded-[2.2rem] flex items-center justify-between p-7 transition-all duration-300 hover:border-emerald-200/50 hover:bg-emerald-50/20 group shadow-premium">
                  <div className="space-y-1.5">
                    <p className="font-black text-[#1E2E4F] text-[18px] malayalam leading-tight tracking-tight group-hover:text-[#006B46] transition-colors">{share.label}</p>
                    <p className="text-[12px] text-slate-400 font-black tracking-[0.2em] uppercase">{share.percentage}</p>
                  </div>
                  <div className="text-right flex flex-col items-end gap-2.5">
                    <div className="bg-[#F7FAF7]/60 text-[#006B46] px-6 py-2.5 rounded-[1.2rem] font-black text-[17px] border border-emerald-100/50 shadow-inner backdrop-blur-md">{share.fraction}</div>
                    {share.amount !== undefined && <p className="text-[13px] font-black text-[#D89F37] tracking-tight">₹{share.amount.toLocaleString()}</p>}
                  </div>
                </div>
              ))}
            </div>
          </div>
        </div>

        <div className="flex flex-col gap-4 mt-auto max-w-sm mx-auto w-full shrink-0">
          <button 
            onClick={() => setShowRules(true)} 
            className="w-full bg-white/60 backdrop-blur-md text-[#006B46] border border-emerald-100/50 h-16 rounded-[2rem] font-black text-base malayalam flex items-center justify-center gap-3 py-4 shadow-premium active-press transition-all"
          >
            <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M12 6.253v13m0-13C10.832 5.477 9.246 5 7.5 5S4.168 5.477 3 6.253v13C4.168 18.477 5.754 18 7.5 18s3.332.477 4.5 1.253m0-13C13.168 5.477 14.754 5 16.5 5c1.747 0 3.332.477 4.5 1.253v13C19.832 18.247 18.247 18 16.5 18c-1.746 0-3.332.477-4.5 1.253" /></svg>
            നിയമങ്ങൾ
          </button>
          <button 
            onClick={() => setStep(AppStep.SELECTION)} 
            className="w-full bg-[#1E2E4F]/90 backdrop-blur-md text-white h-16 rounded-[2rem] font-black text-lg malayalam py-4 shadow-3xl active-press transition-all border border-white/10"
