            മാറ്റങ്ങൾ വരുത്തുക
          </button>
          <button 
            onClick={reset} 
            className="w-full text-slate-400 font-bold text-[14px] malayalam py-2 hover:text-[#006B46] transition-colors active-press"
          >
            പുതിയ കണക്ക് തുടങ്ങുക
          </button>
        </div>
      </div>
    );
  }

  return null;
};

