                    <svg className="w-7 h-7" fill="currentColor" viewBox="0 0 24 24"><path d="M12 2C6.48 2 2 6.48 2 12s4.48 10 10 10 10-4.48 10-10S17.52 2 12 2zm-2 15l-5-5 1.41-1.41L10 14.17l7.59-7.59L19 8l-9 9z"/></svg>
                  </div>
                )}
              </button>
            ))}
          </div>
        </div>
      </ScreenWrapper>
    );
  }

  if (step === AppStep.SELECTION) {
    const categories = Object.keys(heirCategories);
    return (
      <ScreenWrapper currentStep={step} nextStep={heirs.length > 0 ? undefined : undefined} prevStep={AppStep.GENDER} setStep={setStep} disabled={heirs.length === 0} nextLabel="കണക്കാക്കുക">
        <header className="py-6 text-center shrink-0">
          <h2 className="text-2xl font-black text-[#1E2E4F] malayalam tracking-tight leading-tight">അവകാശികൾ</h2>
          <p className="text-slate-500 text-[12px] malayalam font-medium mt-0.5">ബന്ധുക്കളുടെ എണ്ണം ചേർക്കുക</p>
        </header>

        {/* Horizontal Category Scroller */}
        <div className="flex gap-2 overflow-x-auto scroll-container hide-scrollbar shrink-0 px-2 pb-4">
          {categories.map(cat => (
            <button
              key={cat}
              onClick={() => setActiveCategory(cat)}
              className={`px-5 py-2.5 rounded-full text-[10px] font-black uppercase tracking-widest whitespace-nowrap transition-all active-press backdrop-blur-md border ${activeCategory === cat ? 'bg-[#1E2E4F]/90 text-white border-[#1E2E4F]/50 shadow-md' : 'bg-white/40 text-slate-500 border-white/70 shadow-sm'}`}
            >
              {cat}
            </button>
          ))}
        </div>

        {/* Vertical Heir Scroller */}
        <div className="flex-1 min-h-0 scroll-container hide-scrollbar space-y-3 pb-10 pt-2">
          {heirCategories[activeCategory]?.filter(t => (t === 'Husband' ? deceasedGender === 'Female' : t === 'Wife' ? deceasedGender === 'Male' : true))
            .map(type => {
              const count = getHeirCount(type);
              const meta = HEIR_METADATA[type];
              return (
                <div key={type} className={`p-5 rounded-[1.8rem] border flex items-center justify-between transition-all duration-300 backdrop-blur-md ${count > 0 ? 'bg-[#006B46]/90 border-white/30 text-white shadow-xl shadow-emerald-900/10' : 'bg-white/60 border-white/80 shadow-sm'}`}>
                  <div className="flex flex-col">
                    <span className="font-bold malayalam text-[15px] leading-tight tracking-tight">{meta.ml}</span>
                    <span className={`text-[9px] font-black uppercase tracking-[0.15em] ${count > 0 ? 'text-white/50' : 'text-slate-400'}`}>{type}</span>
                  </div>
                  <div className={`flex items-center gap-3 p-1.5 rounded-xl ${count > 0 ? 'bg-black/20' : 'bg-slate-100/40 shadow-inner'}`}>
                    <button 
                      onClick={() => updateHeirCount(type, -1)} 
                      className={`w-9 h-9 rounded-lg flex items-center justify-center transition-all active-press backdrop-blur-md ${count > 0 ? 'bg-white/20 text-white shadow-sm' : 'bg-white/70 text-slate-300 border border-white/60'}`}
                    >
                      <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M20 12H4" /></svg>
                    </button>
                    <span className="w-5 text-center font-black text-base">{count}</span>
                    <button 
                      disabled={meta.max ? count >= meta.max : false} 
                      onClick={() => updateHeirCount(type, 1)} 
                      className={`w-9 h-9 rounded-lg flex items-center justify-center transition-all active-press backdrop-blur-md ${count > 0 ? 'bg-white/20 text-white shadow-sm' : 'bg-white/70 text-[#006B46] border border-white/60'}`}
                    >
                      <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M12 4v16m8-8H4" /></svg>
                    </button>
                  </div>
                </div>
              );
            })}
        </div>

        {/* Explicit CTA Overlay for SELECTION step because of specific requirement to "Calculate" */}
        <div className="pt-2">
            <button 
                disabled={heirs.length === 0} 
                onClick={handleCalculate} 
                className="w-full bg-[#006B46] text-white h-16 rounded-[2rem] font-black text-lg malayalam py-4 shadow-2xl shadow-[#006B46]/20 active-press transition-all disabled:opacity-30 flex items-center justify-center gap-2"
            >
                കണക്കാക്കുക
                <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M9 5l7 7-7 7" /></svg>
            </button>
        </div>
      </ScreenWrapper>
    );
  }

  if (step === AppStep.RESULT && result) {
    return (
      <div className="h-full flex flex-col overflow-hidden bg-transparent">
        {showRules && <RulesContent onClose={() => setShowRules(false)} />}

        <header className="pt-10 pb-6 text-center shrink-0 px-6">
          <h2 className="text-3xl font-black text-[#1E2E4F] malayalam leading-tight mb-5">വിഹിതങ്ങൾ</h2>

          <div className="glass-navy text-white p-8 rounded-[2.5rem] inline-block shadow-2xl border border-white/10 relative overflow-hidden w-full max-w-xs">
             <div className="absolute top-0 right-0 w-24 h-24 bg-[#006B46]/40 rounded-full blur-[35px] -mr-12 -mt-12 opacity-80"></div>
             <p className="text-[10px] uppercase font-black tracking-[0.25em] mb-2 opacity-50 relative z-10">വിതരണത്തിന് തയ്യാറുള്ള തുക</p>
             <p className="text-3xl font-black text-[#D89F37] relative z-10">₹{result.netEstate.toLocaleString()}</p>
          </div>
        </header>

        <div className="flex-1 min-h-0 scroll-container hide-scrollbar px-6 pb-6 space-y-4">
          {result.warnings.length > 0 && (
            <div className="space-y-2">
              {result.warnings.map((w, i) => (
                <div key={i} className="bg-rose-50/50 backdrop-blur-md text-rose-950 p-5 rounded-[1.5rem] border border-rose-100/50 text-[12px] font-bold flex gap-3.5 malayalam leading-relaxed shadow-sm">
                  <div className="bg-rose-100/60 p-2 h-fit rounded-full text-rose-600 shadow-inner">
                    <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z" /></svg>
                  </div>
                  <span className="flex-1">{w}</span>
                </div>
              ))}
            </div>
          )}

          <div className="space-y-3 pb-8">
            {result.shares.map((share, i) => (
              <div key={i} className="glass-card rounded-[2rem] flex items-center justify-between p-6 transition-all duration-300 hover:bg-emerald-50/10 shadow-premium border-white/60">
                <div className="space-y-1">
                  <p className="font-black text-[#1E2E4F] text-[16px] malayalam leading-tight tracking-tight">{share.label}</p>
                  <p className="text-[10px] text-slate-400 font-black tracking-[0.15em] uppercase">{share.percentage}</p>
                </div>
                <div className="text-right flex flex-col items-end gap-1.5">
                  <div className="bg-[#F7FAF7]/60 text-[#006B46] px-5 py-1.5 rounded-xl font-black text-[15px] border border-emerald-100/50 shadow-inner backdrop-blur-md">{share.fraction}</div>
                  {share.amount !== undefined && <p className="text-[11px] font-black text-[#D89F37] tracking-tight">₹{share.amount.toLocaleString()}</p>}
                </div>
              </div>
            ))}
          </div>
        </div>

        {/* Sticky Actions in Result Step */}
        <div className="px-6 pb-6 pt-3 glass rounded-t-[2.5rem] space-y-3">
          <div className="flex gap-3">
            <button 
              onClick={() => setShowRules(true)} 
              className="flex-1 bg-white/60 text-[#006B46] border border-emerald-100/50 h-14 rounded-2xl font-black text-sm malayalam flex items-center justify-center gap-2 shadow-sm active-press"
            >
              <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M12 6.253v13m0-13C10.832 5.477 9.246 5 7.5 5S4.168 5.477 3 6.253v13C4.168 18.477 5.754 18 7.5 18s3.332.477 4.5 1.253m0-13C13.168 5.477 14.754 5 16.5 5c1.747 0 3.332.477 4.5 1.253v13C19.832 18.247 18.247 18 16.5 18c-1.746 0-3.332.477-4.5 1.253" /></svg>
              നിയമങ്ങൾ
            </button>
            <button 
              onClick={() => setStep(AppStep.SELECTION)} 
              className="flex-[2] bg-[#1E2E4F]/90 text-white h-14 rounded-2xl font-black text-base malayalam active-press shadow-xl"
            >
              മാറ്റങ്ങൾ വരുത്തുക
            </button>
          </div>
          <button 
            onClick={reset} 
            className="w-full text-slate-400 font-bold text-[13px] malayalam py-2 hover:text-[#006B46] transition-colors active-press"
          >
            പുതിയ കണക്ക് തുടങ്ങുക
          </button>
        </div>
      </div>
    );
  }

  return null;
};

export default App;

