              return (
                <div key={type} className={`p-6 rounded-[20px] border flex items-center justify-between transition-all duration-500 backdrop-blur-md ${count > 0 ? 'bg-[#006B46]/85 border-white/40 text-white shadow-2xl shadow-emerald-900/20 scale-[1.01]' : 'bg-white/50 border-white/70 shadow-sm'}`}>
                  <div className="flex flex-col gap-0.5">
                    <span className="font-black malayalam text-[17px] leading-tight tracking-tight">{meta.ml}</span>
