                className="w-full bg-[#006B46]/90 text-white h-16 rounded-[20px] font-black text-xl malayalam py-4 shadow-2xl shadow-[#006B46]/30 active-press transition-all disabled:opacity-30 flex items-center justify-center gap-3 backdrop-blur-lg border border-white/10"
