                  <p className="font-black text-[#1E2E4F] text-[18px] malayalam leading-tight tracking-tight group-hover:text-[#006B46] transition-colors">{share.label}</p>
                  <p className="text-[11px] text-slate-400 font-black tracking-[0.2em] uppercase">{share.percentage}</p>
                </div>
                <div className="text-right flex flex-col items-end gap-2">
                  <div className="bg-white/60 text-[#006B46] px-6 py-2 rounded-2xl font-black text-[17px] border border-emerald-100/60 shadow-inner backdrop-blur-md">{share.fraction}</div>
                  {share.amount !== undefined && <p className="text-[13px] font-black text-[#D89F37] tracking-tight">₹{share.amount.toLocaleString()}</p>}
                </div>
              </div>
            ))}
          </div>
        </div>

        <div className="px-5 pb-8 pt-5 glass rounded-t-[20px] space-y-4 shadow-[0_-16px_40px_rgba(0,0,0,0.1)]">
          <div className="flex gap-4">
            <button 
              onClick={() => setShowRules(true)} 
              className="flex-1 bg-white/50 backdrop-blur-md text-[#006B46] border border-emerald-100/60 h-16 rounded-[20px] font-black text-sm malayalam flex items-center justify-center gap-2.5 shadow-sm active-press hover:bg-white/70 transition-all"
            >
              <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M12 6.253v13m0-13C10.832 5.477 9.246 5 7.5 5S4.168 5.477 3 6.253v13C4.168 18.477 5.754 18 7.5 18s3.332.477 4.5 1.253m0-13C13.168 5.477 14.754 5 16.5 5c1.747 0 3.332.477 4.5 1.253v13C19.832 18.247 18.247 18 16.5 18c-1.746 0-3.332.477-4.5 1.253" /></svg>
              നിയമങ്ങൾ
            </button>
            <button 
              onClick={() => setStep(AppStep.SELECTION)} 
              className="flex-[1.8] bg-[#1E2E4F]/90 backdrop-blur-lg text-white h-16 rounded-[20px] font-black text-lg malayalam active-press shadow-2xl border border-white/10"
            >
              മാറ്റങ്ങൾ
            </button>
          </div>
          <button 
            onClick={reset} 
            className="w-full text-slate-400 font-bold text-[14px] malayalam py-2 hover:text-[#006B46] transition-colors active-press opacity-70"
          >
            പുതിയ കണക്ക് തുടങ്ങുക
          </button>
        </div>
      </div>
    );
  }

  return null;
};

export default App;

import React, { useState, useMemo } from 'react';
import { AppStep, Heir, HeirType, CalculationResult, HEIR_METADATA, EstateData } from './types';
import { calculateShares } from './logic/faraidEngine';

/** 
 * Enhanced Screen Wrapper with fixed Header/Footer and independent content scrolling
 */
interface ScreenWrapperProps {
  children: React.ReactNode;
  currentStep: AppStep;
  nextStep?: AppStep;
  prevStep?: AppStep;
  setStep: (step: AppStep) => void;
  nextLabel?: string;
  disabled?: boolean;
}

const stepsOrder = [
  AppStep.DESCRIPTION,
  AppStep.HADITH,
  AppStep.AYAH,
  AppStep.ASSETS,
  AppStep.GENDER,
  AppStep.SELECTION,
  AppStep.RESULT
];

const ScreenWrapper: React.FC<ScreenWrapperProps> = ({ 
  children, 
  currentStep,
  nextStep, 
  prevStep, 
  setStep, 
  nextLabel = "അടുത്തത്", 
  disabled = false 
}) => {
  const stepIndex = stepsOrder.indexOf(currentStep);

  return (
    <div className="h-full flex flex-col relative overflow-hidden bg-transparent">
      {/* Progress Bar */}
      {stepIndex >= 0 && (
        <div className="fixed top-0 left-0 right-0 h-1 bg-slate-900/5 z-[70]">
          <div 
            className="h-full bg-[#D89F37] transition-all duration-700 ease-out shadow-[0_0_12px_rgba(216,159,55,0.6)]" 
            style={{ width: `${((stepIndex + 1) / stepsOrder.length) * 100}%` }}
          />
        </div>
      )}

      {/* Main Content Area: Padding top 24px, padding sides 16px for safety pattern gap */}
      <main className="flex-1 min-h-0 relative z-10 flex flex-col max-w-md mx-auto w-full px-4 pt-6">
        {children}
      </main>

      {/* Persistent Glass Footer: Buttons separate from main card shadow area */}
      <div className="px-4 pt-5 pb-6 glass flex justify-center gap-3 shrink-0 rounded-t-[24px] shadow-[0_-12px_40px_rgba(0,0,0,0.08)] mb-[env(safe-area-inset-bottom)]">
        {prevStep && (
          <button 
