                <span className={`text-[12px] font-black uppercase tracking-[0.35em] ${deceasedGender === opt.id ? 'text-[#D89F37]' : 'opacity-30'}`}>{opt.sub}</span>
                {deceasedGender === opt.id && (
                  <div className="absolute top-6 right-6 text-[#D89F37] animate-in scale-110">
                    <svg className="w-8 h-8" fill="currentColor" viewBox="0 0 24 24"><path d="M12 2C6.48 2 2 6.48 2 12s4.48 10 10 10 10-4.48 10-10S17.52 2 12 2zm-2 15l-5-5 1.41-1.41L10 14.17l7.59-7.59L19 8l-9 9z"/></svg>
                  </div>
                )}
              </button>
            ))}
          </div>
        </div>
      </ScreenWrapper>
    );
  }

  if (step === AppStep.SELECTION) {
    const categories = Object.keys(heirCategories);
    return (
      <ScreenWrapper currentStep={step} nextStep={undefined} prevStep={AppStep.GENDER} setStep={setStep} disabled={heirs.length === 0} nextLabel="കണക്കാക്കുക">
        <header className="py-8 text-center shrink-0">
          <h2 className="text-3xl font-black text-[#1E2E4F] malayalam tracking-tight leading-tight">അവകാശികൾ</h2>
          <p className="text-slate-500 text-[13px] malayalam font-bold mt-1.5 opacity-50">ബന്ധുക്കളുടെ എണ്ണം ചേർക്കുക</p>
        </header>

        <div className="flex gap-2.5 overflow-x-auto scroll-container hide-scrollbar shrink-0 px-2 pb-5">
          {categories.map(cat => (
            <button
              key={cat}
              onClick={() => setActiveCategory(cat)}
              className={`px-6 py-3 rounded-full text-[11px] font-black uppercase tracking-widest whitespace-nowrap transition-all active-press backdrop-blur-md border ${activeCategory === cat ? 'bg-[#1E2E4F]/90 text-white border-[#1E2E4F]/40 shadow-xl' : 'bg-white/40 text-slate-500 border-white/70 shadow-sm'}`}
            >
              {cat}
            </button>
          ))}
        </div>

        <div className="flex-1 min-h-0 scroll-container hide-scrollbar space-y-4 pb-12 pt-2">
          {heirCategories[activeCategory]?.filter(t => (t === 'Husband' ? deceasedGender === 'Female' : t === 'Wife' ? deceasedGender === 'Male' : true))
            .map(type => {
              const count = getHeirCount(type);
              const meta = HEIR_METADATA[type];
              return (
                <div key={type} className={`p-6 rounded-[24px] border flex items-center justify-between transition-all duration-500 backdrop-blur-md ${count > 0 ? 'bg-[#006B46]/85 border-white/40 text-white shadow-2xl shadow-emerald-900/20 scale-[1.01]' : 'bg-white/50 border-white/70 shadow-sm'}`}>
                  <div className="flex flex-col gap-0.5">
                    <span className="font-black malayalam text-[17px] leading-tight tracking-tight">{meta.ml}</span>
                    <span className={`text-[10px] font-black uppercase tracking-widest ${count > 0 ? 'text-white/50' : 'text-slate-400'}`}>{type}</span>
                  </div>
                  <div className={`flex items-center gap-4 p-2 rounded-2xl ${count > 0 ? 'bg-black/25 shadow-inner' : 'bg-slate-200/40 shadow-inner'}`}>
                    <button 
                      onClick={() => updateHeirCount(type, -1)} 
                      className={`w-10 h-10 rounded-xl flex items-center justify-center transition-all active-press backdrop-blur-md ${count > 0 ? 'bg-white/20 text-white shadow-sm border border-white/20' : 'bg-white/70 text-slate-300 border border-white/60'}`}
                    >
                      <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M20 12H4" /></svg>
                    </button>
                    <span className="w-6 text-center font-black text-lg">{count}</span>
                    <button 
                      disabled={meta.max ? count >= meta.max : false} 
                      onClick={() => updateHeirCount(type, 1)} 
                      className={`w-10 h-10 rounded-xl flex items-center justify-center transition-all active-press backdrop-blur-md ${count > 0 ? 'bg-white/20 text-white shadow-sm border border-white/20' : 'bg-white/70 text-[#006B46] border border-white/60'}`}
                    >
                      <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M12 4v16m8-8H4" /></svg>
                    </button>
                  </div>
                </div>
              );
            })}
        </div>

        <div className="pt-3 pb-6">
            <button 
                disabled={heirs.length === 0} 
                onClick={handleCalculate} 
                className="w-full bg-[#006B46]/90 text-white h-16 rounded-[24px] font-black text-xl malayalam py-4 shadow-2xl shadow-[#006B46]/30 active-press transition-all disabled:opacity-30 flex items-center justify-center gap-3 backdrop-blur-lg border border-white/10"
            >
