            <div className="flex items-center gap-5 w-full opacity-40 mt-6 px-4">
              <div className="h-px flex-1 bg-[#D89F37]"></div>
              <div className="w-3 h-3 rotate-45 border-2 border-[#D89F37] bg-white"></div>
              <div className="h-px flex-1 bg-[#D89F37]"></div>
            </div>

            <p className="text-lg text-[#006B46] font-black malayalam text-center leading-relaxed mt-5 px-2">
              "അവകാശവിഹിതങ്ങൾ അർഹരായവർക്ക് എത്തിക്കുക. ബാക്കി വരുന്നത് ഏറ്റവും അടുത്ത പുരുഷ ബന്ധുവിനുള്ളതാണ്."
            </p>

            <div className="flex justify-center mt-6 mb-2">
              <span className="px-6 py-3 bg-white/40 text-[#D89F37] rounded-2xl text-[11px] font-black uppercase tracking-[0.25em] border border-[#D89F37]/30 shadow-sm backdrop-blur-md">
                സ്വഹീഹുൽ ബുഖാരി
              </span>
            </div>
          </div>
        </div>
      </ScreenWrapper>
    );
  }

  if (step === AppStep.AYAH) {
    return (
      <ScreenWrapper currentStep={step} nextStep={AppStep.ASSETS} prevStep={AppStep.HADITH} setStep={setStep}>
        <div className="flex flex-col items-center justify-center flex-1 py-4">
          <div className="glass-card p-6 w-full flex flex-col items-center animate-in">
             <div className="w-16 h-16 rounded-[20px] bg-[#006B46]/10 flex items-center justify-center text-[#006B46] shadow-inner border border-[#006B46]/10 backdrop-blur-md">
               <svg className="w-8 h-8" fill="currentColor" viewBox="0 0 24 24"><path d="M12 2L4.5 20.29l.71.71L12 18l6.79 3 .71-.71L12 2z"/></svg>
             </div>

            <div className="arabic text-[26px] text-[#1E2E4F] font-semibold leading-[1.85] word-ready-text drop-shadow-sm mt-5">
              يُوصِيكُمُ اللَّهُ فِي അَوْല‌ാദ‌ിക‌ുമ് ല‌ില്ല‌കറ‌ി മ‌ിസ‌്ല‌ു ഹസ‌്സ‌ില‌് അന‌്സ‌യയ‌ൈന‌്
            </div>

            <div className="w-full flex justify-center gap-2.5 opacity-40 mt-6">
              <div className="w-2.5 h-2.5 rounded-full bg-[#D89F37]"></div>
              <div className="w-2.5 h-2.5 rounded-full bg-[#D89F37] opacity-60"></div>
              <div className="w-2.5 h-2.5 rounded-full bg-[#D89F37] opacity-30"></div>
            </div>

            <p className="text-xl text-[#1E2E4F] font-black malayalam text-center leading-relaxed word-ready-text px-2 mt-5">
              "നിങ്ങളുടെ മക്കളുടെ കാര്യത്തിൽ അല്ലാഹു കൽപ്പിക്കുന്നു; ആണിന് രണ്ട് പെണ്ണിന്റെ വിഹിതത്തിന് തുല്യമായതുണ്ട്."
            </p>

            <div className="flex justify-center mt-6 mb-2">
                <span className="px-6 py-3 bg-[#1E2E4F]/90 text-white rounded-[20px] text-[11px] font-bold tracking-[0.2em] shadow-xl shadow-navy-900/10 backdrop-blur-md border border-white/10">
                  സൂറത്ത് അന്നിസാഅ് 4:11
                </span>
            </div>
          </div>
        </div>
      </ScreenWrapper>
    );
  }

  if (step === AppStep.ASSETS) {
    return (
      <ScreenWrapper currentStep={step} nextStep={AppStep.GENDER} prevStep={AppStep.AYAH} setStep={setStep}>
        <header className="py-8 text-center shrink-0">
          <h2 className="text-3xl font-black text-[#1E2E4F] malayalam tracking-tight leading-tight">സ്വത്ത് വിവരങ്ങൾ</h2>
