export type HeirType = keyof typeof HEIR_METADATA;

export interface Heir {
  type: HeirType;
  count: number;
}

export interface EstateData {
  totalAssets: number;
  debts: number;
  funeral: number;
  will: number;
}

export interface CalculationResult {
  shares: Array<{ label: string, fraction: string, percentage: string, amount?: number }>;
  netEstate: number;
  complex: boolean;
  warnings: string[];
}

import React, { useState } from 'react';
import { AppStep, Heir, HeirType, CalculationResult, HEIR_METADATA, HEIR_ORDER, EstateData } from './types';
import { calculateShares } from './logic/faraidEngine';

/** 
 * ScreenWrapper provides consistent layout, background, and navigation
 */
interface ScreenWrapperProps {
  children: React.ReactNode;
  currentStep: AppStep;
  nextStep?: AppStep;
  prevStep?: AppStep;
  setStep: (step: AppStep) => void;
  nextLabel?: string;
  disabled?: boolean;
  hideFooter?: boolean;
}

const stepsOrder = [
  AppStep.DESCRIPTION,
  AppStep.HADITH,
  AppStep.AYAH,
  AppStep.ASSETS,
  AppStep.GENDER,
  AppStep.SELECTION,
  AppStep.RESULT
];

const ScreenWrapper: React.FC<ScreenWrapperProps> = ({ 
  children, 
  currentStep,
  nextStep, 
  prevStep, 
  setStep, 
  nextLabel = "തുടരുക", 
  disabled = false,
  hideFooter = false
}) => {
  const stepIndex = stepsOrder.indexOf(currentStep);

  return (
    <div className="h-full flex flex-col relative overflow-hidden bg-transparent">
      {/* Progress Line */}
      {stepIndex >= 0 && (
        <div className="fixed top-0 left-0 right-0 h-1.5 bg-slate-200 z-[70]">
          <div 
            className="h-full bg-[#D89F37] transition-all duration-700 ease-in-out shadow-[0_0_8px_rgba(216,159,55,0.4)]" 
            style={{ width: `${((stepIndex + 1) / stepsOrder.length) * 100}%` }}
          />
        </div>
      )}

      <main className="flex-1 min-h-0 relative z-10 flex flex-col max-w-md mx-auto w-full px-5 pt-8">
        {children}
      </main>

      {!hideFooter && (
        <div className="px-6 py-6 glass flex justify-center gap-4 shrink-0 rounded-t-[32px] shadow-2xl mb-[env(safe-area-inset-bottom)]">
          {prevStep && (
            <button 
              onClick={() => setStep(prevStep)} 
              className="w-14 h-14 rounded-2xl flex items-center justify-center bg-white border border-slate-200 text-[#1E2E4F] active-press transition-all shadow-sm"
            >
              <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M15 19l-7-7 7-7" /></svg>
            </button>
          )}
          {nextStep && (
            <button 
              disabled={disabled} 
              onClick={() => setStep(nextStep)} 
              className="flex-1 h-14 bg-[#006B46] text-white rounded-2xl font-bold text-lg transition-all active-press shadow-lg shadow-[#006B46]/20 malayalam disabled:opacity-40"
            >
              {nextLabel}
            </button>
          )}
        </div>
      )}
    </div>
  );
};

const App: React.FC = () => {
  const [step, setStep] = useState<AppStep>(AppStep.WELCOME);
  const [deceasedGender, setDeceasedGender] = useState<'Male' | 'Female' | null>(null);
  const [heirs, setHeirs] = useState<Heir[]>([]);
  const [estate, setEstate] = useState<EstateData>({ totalAssets: 0, debts: 0, funeral: 0, will: 0 });
  const [result, setResult] = useState<CalculationResult | null>(null);

  const updateHeirCount = (type: HeirType, delta: number) => {
    const meta = HEIR_METADATA[type as string];
    setHeirs(prev => {
      const existing = prev.find(h => h.type === type);
      if (existing) {
        let newCount = Math.max(0, existing.count + delta);
        if (meta.max) newCount = Math.min(newCount, meta.max);
        if (newCount === 0) return prev.filter(h => h.type !== type);
        return prev.map(h => h.type === type ? { ...h, count: newCount } : h);
      } else if (delta > 0) return [...prev, { type, count: 1 }];
      return prev;
    });
  };

  const getHeirCount = (type: HeirType) => heirs.find(h => h.type === type)?.count || 0;

  const handleCalculate = () => {
    if (deceasedGender) {
      setResult(calculateShares(heirs, deceasedGender, estate));
      setStep(AppStep.RESULT);
    }
  };

  const reset = () => {
    setHeirs([]);
    setDeceasedGender(null);
    setEstate({ totalAssets: 0, debts: 0, funeral: 0, will: 0 });
    setResult(null);
    setStep(AppStep.WELCOME);
  };

  if (step === AppStep.WELCOME) {
    return (
      <div className="h-full bg-[#1E2E4F] flex flex-col items-center justify-center p-10 text-white text-center relative overflow-hidden">
        <div className="absolute top-0 right-0 w-64 h-64 bg-[#006B46]/20 rounded-full -mr-32 -mt-32 blur-3xl"></div>
        <div className="absolute bottom-0 left-0 w-64 h-64 bg-[#D89F37]/10 rounded-full -ml-32 -mb-32 blur-3xl"></div>

        <div className="relative z-10 animate-in space-y-8">
          <div className="w-32 h-32 bg-white/10 backdrop-blur-xl rounded-[40px] flex items-center justify-center mx-auto shadow-2xl border border-white/20">
            <svg className="w-16 h-16 text-[#D89F37]" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1.5} d="M12 6.253v13m0-13C10.832 5.477 9.246 5 7.5 5S4.168 5.477 3 6.253v13C4.168 18.477 5.754 18 7.5 18s3.332.477 4.5 1.253m0-13C13.168 5.477 14.754 5 16.5 5c1.747 0 3.332.477 4.5 1.253v13C19.832 18.247 18.247 18 16.5 18c-1.746 0-3.332.477-4.5 1.253" />
            </svg>
          </div>

          <div className="space-y-4">
            <h1 className="text-4xl font-extrabold malayalam tracking-tight text-white drop-shadow-md">ഫറാഇദ് കാൽക്കുലേറ്റർ</h1>
            <p className="text-slate-300 text-lg malayalam opacity-80 font-medium">ഇസ്‌ലാമിക അനന്തരാവകാശ വിഹിതം കൃത്യമായും ലളിതമായും കണ്ടെത്താം.</p>
          </div>

          <button 
            onClick={() => setStep(AppStep.DESCRIPTION)} 
            className="w-full bg-[#006B46] text-white py-5 rounded-2xl font-bold text-xl active-press shadow-2xl malayalam"
          >
            തുടങ്ങുക
          </button>
        </div>
      </div>
    );
  }

  if (step === AppStep.DESCRIPTION) {
    return (
      <ScreenWrapper currentStep={step} nextStep={AppStep.HADITH} prevStep={AppStep.WELCOME} setStep={setStep}>
        <div className="space-y-8 animate-in text-center">
          <h2 className="text-3xl font-black text-[#1E2E4F] malayalam">എന്താണ് ഫറാഇദ്?</h2>
          <div className="glass-card p-8 space-y-6 text-slate-700 malayalam text-lg leading-relaxed">
            <p>മരണപ്പെട്ട വ്യക്തിയുടെ സ്വത്ത് അർഹരായ അവകാശികൾക്ക് വീതിച്ചു നൽകുന്ന നിയമവ്യവസ്ഥയാണ് ഫറാഇദ്.</p>
            <p>വിശുദ്ധ ഖുർആൻ കൃത്യമായി നിർദ്ദേശിച്ച ഈ വിഹിതങ്ങൾ ഒരു വിശ്വാസിയുടെ ജീവിതത്തിലെ സുപ്രധാന ബാധ്യതയാണ്.</p>
            <div className="pt-4 flex justify-center">
              <div className="w-16 h-1.5 bg-[#D89F37]/30 rounded-full"></div>
            </div>
          </div>
        </div>
      </ScreenWrapper>
    );
  }

  if (step === AppStep.HADITH) {
    return (
      <ScreenWrapper currentStep={step} nextStep={AppStep.AYAH} prevStep={AppStep.DESCRIPTION} setStep={setStep}>
        <div className="space-y-8 animate-in flex flex-col items-center">
          <div className="w-16 h-16 bg-[#006B46]/10 rounded-full flex items-center justify-center text-[#006B46]">
            <svg className="w-8 h-8" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5 13l4 4L19 7" /></svg>
          </div>
          <div className="glass-card p-10 w-full relative overflow-hidden">
            <div className="absolute top-0 right-0 p-4 opacity-5">
              <svg className="w-32 h-32" fill="currentColor" viewBox="0 0 24 24"><path d="M13 14.725c0-5.141 3.892-10.519 10-10.519l.716 2.185c-3.136 1.054-5.136 3.054-5.136 5.484 0 1.656.804 2.185 1.512 2.185 1.275 0 2.374 1.108 2.374 2.538 0 1.532-1.22 2.538-2.625 2.538-2.146 0-6.841-1.603-6.841-6.411zm-13 0c0-5.141 3.892-10.519 10-10.519l.716 2.185c-3.136 1.054-5.136 3.054-5.136 5.484 0 1.656.804 2.185 1.512 2.185 1.275 0 2.374 1.108 2.374 2.538 0 1.532-1.22 2.538-2.625 2.538-2.146 0-6.841-1.603-6.841-6.411z"/></svg>
            </div>
            <div className="arabic mb-8">أَلْحِقُوا الْفَرَائِضَ بِأَهْلِهَا فَمَا بَقِيَ فَهُوَ لِأَوْلَى رَجُلٍ ذَكَرٍ</div>
            <p className="malayalam text-center text-[#1E2E4F] font-bold text-lg leading-relaxed">
              "അവകാശവിഹിതങ്ങൾ അർഹരായവർക്ക് എത്തിക്കുക. ബാക്കി വരുന്നത് ഏറ്റവും അടുത്ത പുരുഷ ബന്ധുവിനുള്ളതാണ്."
            </p>
            <p className="mt-8 text-center text-slate-400 font-bold text-sm tracking-widest uppercase">സ്വഹീഹുൽ ബുഖാരി</p>
          </div>
        </div>
      </ScreenWrapper>
    );
  }

  if (step === AppStep.AYAH) {
    return (
      <ScreenWrapper currentStep={step} nextStep={AppStep.ASSETS} prevStep={AppStep.HADITH} setStep={setStep}>
        <div className="space-y-8 animate-in flex flex-col items-center">
          <div className="w-16 h-16 bg-[#D89F37]/10 rounded-full flex items-center justify-center text-[#D89F37]">
             <svg className="w-8 h-8" fill="currentColor" viewBox="0 0 24 24"><path d="M12 2L4.5 20.29l.71.71L12 18l6.79 3 .71-.71L12 2z"/></svg>
          </div>
          <div className="glass-card p-10 w-full">
            <div className="arabic mb-8">يُوصِيكُمُ اللَّهُ فِي أَوْلَادِكُمْ لِلذَّكَرِ مِثْلُ حَظِّ الْأُنْثَيَيْنِ</div>
            <p className="malayalam text-center text-[#1E2E4F] font-bold text-lg leading-relaxed">
              "നിങ്ങളുടെ മക്കളുടെ കാര്യത്തിൽ അല്ലാഹു കൽപ്പിക്കുന്നു; ആണിന് രണ്ട് പെണ്ണിന്റെ വിഹിതത്തിന് തുല്യമായതുണ്ട്."
            </p>
            <p className="mt-8 text-center text-slate-400 font-bold text-sm tracking-widest uppercase">സൂറത്ത് അന്നിസാഅ് 4:11</p>
          </div>
        </div>
      </ScreenWrapper>
    );
  }

  if (step === AppStep.ASSETS) {
    return (
      <ScreenWrapper currentStep={step} nextStep={AppStep.GENDER} prevStep={AppStep.AYAH} setStep={setStep}>
        <div className="space-y-6 animate-in">
          <header className="text-center space-y-2">
            <h2 className="text-3xl font-black text-[#1E2E4F] malayalam">സ്വത്ത് വിവരങ്ങൾ</h2>
            <p className="text-slate-500 font-bold malayalam">മൊത്തം ആസ്തിയും ബാധ്യതകളും</p>
          </header>

          <div className="space-y-4 pb-10">
            {[
              { label: 'മൊത്തം ആസ്തി', key: 'totalAssets', icon: '💰' },
              { label: 'കടബാധ്യതകൾ', key: 'debts', icon: '📉' },
              { label: 'മരണാനന്തര ചിലവ്', key: 'funeral', icon: '🕯️' },
              { label: 'വസീയ്യത്ത് (പരമാവധി 1/3)', key: 'will', icon: '📜' }
            ].map(f => (
              <div key={f.key} className="glass-card p-6 space-y-3 shadow-sm">
                <div className="flex items-center gap-3">
                  <span className="text-xl">{f.icon}</span>
                  <label className="text-sm font-bold malayalam text-slate-500 uppercase tracking-wider">{f.label}</label>
                </div>
                <div className="relative">
                  <span className="absolute left-0 top-1/2 -translate-y-1/2 text-2xl font-black text-slate-300 ml-1">₹</span>
                  <input 
                    type="number"
                    inputMode="numeric"
                    placeholder="0"
                    value={(estate as any)[f.key] || ''}
                    onChange={e => setEstate({...estate, [f.key]: Math.max(0, Number(e.target.value))})}
                    className="w-full bg-transparent border-b-2 border-slate-100 py-3 pl-8 text-2xl font-black text-[#1E2E4F] outline-none focus:border-[#006B46] transition-colors"
                  />
                </div>
              </div>
            ))}
          </div>
        </div>
      </ScreenWrapper>
    );
  }

  if (step === AppStep.GENDER) {
    return (
      <ScreenWrapper currentStep={step} nextStep={deceasedGender ? AppStep.SELECTION : undefined} prevStep={AppStep.ASSETS} setStep={setStep} disabled={!deceasedGender}>
        <div className="space-y-12 animate-in flex flex-col items-center py-10">
          <header className="text-center space-y-4">
            <h2 className="text-4xl font-black text-[#1E2E4F] malayalam">മരണപ്പെട്ട വ്യക്തി</h2>
            <p className="text-slate-500 font-bold malayalam text-lg">ലിംഗഭേദം തിരഞ്ഞെടുക്കുക</p>
          </header>

          <div className="grid grid-cols-1 gap-6 w-full max-w-xs">
            {['Male', 'Female'].map(g => (
              <button 
                key={g}
                onClick={() => setDeceasedGender(g as any)}
                className={`p-12 rounded-[40px] font-black text-3xl malayalam transition-all active-press border-4 flex flex-col items-center gap-4 ${deceasedGender === g ? 'bg-[#1E2E4F] text-white border-[#D89F37] shadow-2xl scale-105' : 'bg-white text-slate-400 border-white'}`}
              >
                <span>{g === 'Male' ? 'പുരുഷൻ' : 'സ്ത്രീ'}</span>
                <span className="text-xs tracking-widest uppercase opacity-40">{g}</span>
              </button>
            ))}
          </div>
        </div>
      </ScreenWrapper>
    );
  }

  if (step === AppStep.SELECTION) {
    return (
      <ScreenWrapper currentStep={step} setStep={setStep} hideFooter={true}>
        <header className="py-4 text-center shrink-0">
          <h2 className="text-2xl font-black text-[#1E2E4F] malayalam">അവകാശികൾ</h2>
          <p className="text-slate-500 font-bold malayalam text-sm">എണ്ണം രേഖപ്പെടുത്തുക</p>
        </header>

        <div className="flex-1 min-h-0 scroll-container hide-scrollbar space-y-4 pb-10">
          <div className="glass-card overflow-hidden">
            {HEIR_ORDER.map((type, idx) => {
              const meta = HEIR_METADATA[type];
              if (type === 'Husband' && deceasedGender !== 'Female') return null;
              if (type === 'Wives' && deceasedGender !== 'Male') return null;

              const count = getHeirCount(type as HeirType);

              return (
                <div key={type} className="flex flex-col">
                  <div className="flex items-center justify-between p-6 h-[80px]">
                    <div className="flex flex-col">
                      <span className="font-bold text-[#1E2E4F]">{type}</span>
                      <span className="text-[12px] malayalam text-slate-400">{meta.ml}</span>
                    </div>
                    <div className="flex items-center gap-4 bg-slate-50 p-2 rounded-2xl shadow-inner">
                      <button 
                        onClick={() => updateHeirCount(type as HeirType, -1)} 
                        className={`w-10 h-10 rounded-xl flex items-center justify-center transition-all ${count > 0 ? 'bg-white text-rose-500 shadow-sm' : 'text-slate-300'}`}
                      >
                        <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M20 12H4" /></svg>
                      </button>
                      <span className="w-6 text-center font-black text-lg">{count}</span>
                      <button 
                        disabled={meta.max ? count >= meta.max : false}
                        onClick={() => updateHeirCount(type as HeirType, 1)} 
                        className="w-10 h-10 rounded-xl bg-white text-[#006B46] flex items-center justify-center shadow-sm disabled:opacity-20"
                      >
                        <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M12 4v16m8-8H4" /></svg>
                      </button>
                    </div>
                  </div>
                  {idx < HEIR_ORDER.length - 1 && <div className="h-px bg-slate-100 mx-6" />}
                </div>
              );
            })}
          </div>

          <div className="pt-4 flex flex-col gap-4">
            <button 
              onClick={handleCalculate} 
              className="w-full bg-[#006B46] text-white py-5 rounded-2xl font-black text-xl active-press shadow-2xl malayalam flex items-center justify-center gap-3"
            >
              കണക്കാക്കുക
              <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M13 5l7 7-7 7M5 5l7 7-7 7" /></svg>
            </button>
            <button 
              onClick={() => setStep(AppStep.GENDER)} 
              className="w-full h-14 rounded-2xl font-bold text-[#1E2E4F] bg-white border border-slate-200 active-press malayalam"
            >
              പുറകോട്ട്
            </button>
          </div>
        </div>
      </ScreenWrapper>
    );
  }

  if (step === AppStep.RESULT && result) {
    return (
      <div className="h-full flex flex-col overflow-hidden pt-8">
        <header className="px-6 text-center space-y-6 shrink-0">
          <h2 className="text-4xl font-black text-[#1E2E4F] malayalam">വിതരണ വിഹിതം</h2>
          <div className="glass-navy p-10 text-white space-y-2">
            <p className="text-xs font-bold uppercase tracking-[0.3em] opacity-60">വിതരണത്തിനുള്ള തുക</p>
            <p className="text-4xl font-black text-[#D89F37]">₹{result.netEstate.toLocaleString()}</p>
          </div>
        </header>

        <div className="flex-1 min-h-0 scroll-container hide-scrollbar px-6 py-8 space-y-4">
          {result.warnings.length > 0 && result.warnings.map((w, i) => (
             <div key={i} className="bg-amber-50 border border-amber-100 p-5 rounded-2xl text-amber-800 text-sm font-bold malayalam flex gap-3">
               <span className="text-lg">⚠️</span> {w}
             </div>
          ))}

          <div className="space-y-3 pb-10">
            {result.shares.map((s, i) => (
              <div key={i} className="glass-card p-6 flex items-center justify-between border-l-8 border-l-[#006B46]">
                <div className="space-y-1">
                  <p className="font-black text-[#1E2E4F] text-lg malayalam">{s.label}</p>
                  <p className="text-xs font-bold text-slate-400 uppercase tracking-widest">{s.fraction} • {s.percentage}</p>
                </div>
                <div className="text-right">
                  <p className="text-xl font-black text-[#006B46]">₹{s.amount?.toLocaleString()}</p>
                </div>
              </div>
            ))}
          </div>
        </div>

        <div className="px-6 py-8 glass rounded-t-[40px] shadow-2xl">
          <button 
            onClick={reset} 
            className="w-full bg-[#1E2E4F] text-white py-5 rounded-2xl font-black text-xl active-press malayalam"
          >
            പുതിയ കണക്ക്
          </button>
        </div>
      </div>
    );
  }

  return null;
};

export default App;

export enum AppStep {
  WELCOME = 'WELCOME',
  DESCRIPTION = 'DESCRIPTION',
  HADITH = 'HADITH',
  AYAH = 'AYAH',
  RULES = 'RULES',
  ASSETS = 'ASSETS',
  GENDER = 'GENDER',
  SELECTION = 'SELECTION',
  RESULT = 'RESULT'
}

export const HEIR_ORDER: string[] = [
  'Husband', 'Wives', 'Sons', 'Daughters', 'Grandsons', 'Granddaughters',
  'Father', 'Mother', 'Grandfather', 'Paternal Grandmother', 'Maternal Grandmother',
  'Full Brothers', 'Full Sisters', 'Paternal Brothers', 'Paternal Sisters',
  'Maternal Brothers', 'Maternal Sisters', 'Full Nephews', 'Paternal Nephews',
  'Full Nephew’s Sons', 'Paternal Nephew’s Sons', 'Full Paternal Uncles',
  'Paternal Paternal Uncles', 'Full Cousins', 'Paternal Cousins',
  'Full Cousin’s Sons', 'Paternal Cousin’s Sons', 'Full Cousin’s Grandsons',
  'Paternal Cousin’s Grandsons'
];

export const HEIR_METADATA: Record<string, { ml: string, max?: number }> = {
  'Husband': { ml: 'ഭർത്താവ്', max: 1 },
  'Wives': { ml: 'ഭാര്യമാർ', max: 4 },
  'Sons': { ml: 'പുത്രന്മാർ' },
  'Daughters': { ml: 'പുത്രിമാർ' },
