const stepsOrder = [
  AppStep.DESCRIPTION,
  AppStep.HADITH,
  AppStep.AYAH,
  AppStep.ASSETS,
  AppStep.GENDER,
  AppStep.SELECTION,
  AppStep.RESULT
];

const ScreenWrapper: React.FC<ScreenWrapperProps> = ({ 
  children, 
  currentStep,
  nextStep, 
  prevStep, 
  setStep, 
  nextLabel = "തുടരുക", 
  disabled = false,
  hideFooter = false
}) => {
  const stepIndex = stepsOrder.indexOf(currentStep);

  return (
    <div className="h-full flex flex-col relative overflow-hidden bg-transparent">
      {/* Progress Line */}
      {stepIndex >= 0 && (
        <div className="fixed top-0 left-0 right-0 h-1.5 bg-slate-200 z-[70]">
          <div 
            className="h-full bg-[#D89F37] transition-all duration-700 ease-in-out shadow-[0_0_8px_rgba(216,159,55,0.4)]" 
            style={{ width: `${((stepIndex + 1) / stepsOrder.length) * 100}%` }}
          />
        </div>
      )}

      <main className="flex-1 min-h-0 relative z-10 flex flex-col max-w-md mx-auto w-full px-5 pt-8">
        {children}
      </main>

      {!hideFooter && (
        <div className="px-6 py-6 glass flex justify-center gap-4 shrink-0 rounded-t-[32px] shadow-2xl mb-[env(safe-area-inset-bottom)]">
          {prevStep && (
            <button 
              onClick={() => setStep(prevStep)} 
              className="w-14 h-14 rounded-2xl flex items-center justify-center bg-white border border-slate-200 text-[#1E2E4F] active-press transition-all shadow-sm"
            >
              <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M15 19l-7-7 7-7" /></svg>
            </button>
          )}
          {nextStep && (
            <button 
              disabled={disabled} 
              onClick={() => setStep(nextStep)} 
              className="flex-1 h-14 bg-[#006B46] text-white rounded-2xl font-bold text-lg transition-all active-press shadow-lg shadow-[#006B46]/20 malayalam disabled:opacity-40"
            >
              {nextLabel}
            </button>
          )}
        </div>
      )}
    </div>
  );
};

const App: React.FC = () => {
  const [step, setStep] = useState<AppStep>(AppStep.WELCOME);
  const [deceasedGender, setDeceasedGender] = useState<'Male' | 'Female' | null>(null);
  const [heirs, setHeirs] = useState<Heir[]>([]);
  const [estate, setEstate] = useState<EstateData>({ totalAssets: 0, debts: 0, funeral: 0, will: 0 });
  const [result, setResult] = useState<CalculationResult | null>(null);

  const updateHeirCount = (type: HeirType, delta: number) => {
    const meta = HEIR_METADATA[type as string];
    setHeirs(prev => {
      const existing = prev.find(h => h.type === type);
      if (existing) {
        let newCount = Math.max(0, existing.count + delta);
        if (meta.max) newCount = Math.min(newCount, meta.max);
        if (newCount === 0) return prev.filter(h => h.type !== type);
        return prev.map(h => h.type === type ? { ...h, count: newCount } : h);
      } else if (delta > 0) return [...prev, { type, count: 1 }];
      return prev;
    });
  };

  const getHeirCount = (type: HeirType) => heirs.find(h => h.type === type)?.count || 0;

  const handleCalculate = () => {
    if (deceasedGender) {
      setResult(calculateShares(heirs, deceasedGender, estate));
      setStep(AppStep.RESULT);
    }
  };

  const reset = () => {
    setHeirs([]);
    setDeceasedGender(null);
