  children, 
  currentStep,
  nextStep, 
  prevStep, 
  setStep, 
  nextLabel = "തുടരുക", 
  disabled = false,
  hideFooter = false
}) => {
  const stepIndex = stepsOrder.indexOf(currentStep);

  return (
    <div className="h-full flex flex-col relative overflow-hidden bg-transparent pt-safe">
