            <div className="arabic mb-8">يُوصِيكُمُ اللَّهُ فِي أَوْلَادِكُمْ لِلذَّكَرِ مِثْلُ حَظِّ الْأُنْثَيَيْنِ</div>
            <p className="malayalam text-center text-[#1E2E4F] font-bold text-lg leading-relaxed">
              "നിങ്ങളുടെ മക്കളുടെ കാര്യത്തിൽ അല്ലാഹു കൽപ്പിക്കുന്നു; ആണിന് രണ്ട് പെണ്ണിന്റെ വിഹിതത്തിന് തുല്യമായതുണ്ട്."
            </p>
            <p className="mt-8 text-center text-slate-400 font-bold text-sm tracking-widest uppercase">സൂറത്ത് അന്നിസാഅ് 4:11</p>
          </div>
        </div>
      </ScreenWrapper>
    );
  }

  if (step === AppStep.ASSETS) {
    return (
      <ScreenWrapper currentStep={step} nextStep={AppStep.GENDER} prevStep={AppStep.AYAH} setStep={setStep}>
        <header className="shrink-0 py-6 text-center space-y-2">
          <h2 className="text-3xl font-black text-[#1E2E4F] malayalam">സ്വത്ത് വിവരങ്ങൾ</h2>
          <p className="text-slate-500 font-bold malayalam">മൊത്തം ആസ്തിയും ബാധ്യതകളും</p>
        </header>

        <div className="flex-1 overflow-y-auto scroll-container hide-scrollbar space-y-5 pb-8">
          {[
            { label: 'മൊത്തം ആസ്തി', key: 'totalAssets', icon: '💰' },
            { label: 'കടബാധ്യതകൾ', key: 'debts', icon: '📉' },
            { label: 'മരണാനന്തര ചിലവ്', key: 'funeral', icon: '🕯️' },
            { label: 'വസീയ്യത്ത് (പരമാവധി 1/3)', key: 'will', icon: '📜' }
          ].map(f => (
            <div key={f.key} className="glass-card p-6 space-y-3 shadow-md hover:border-[#006B46]/30 transition-all">
              <div className="flex items-center gap-3">
                <span className="text-xl">{f.icon}</span>
                <label className="text-xs font-bold malayalam text-slate-400 uppercase tracking-widest">{f.label}</label>
              </div>
              <div className="relative">
                <span className="absolute left-0 top-1/2 -translate-y-1/2 text-2xl font-black text-slate-300 ml-1">₹</span>
                <input 
                  type="number"
                  inputMode="numeric"
                  placeholder="0"
                  value={(estate as any)[f.key] || ''}
                  onChange={e => setEstate({...estate, [f.key]: Math.max(0, Number(e.target.value))})}
                  className="w-full bg-transparent border-b-2 border-slate-100 py-3 pl-8 text-2xl font-black text-[#1E2E4F] outline-none focus:border-[#006B46] transition-colors"
                />
              </div>
            </div>
          ))}
        </div>
      </ScreenWrapper>
    );
  }

  if (step === AppStep.GENDER) {
    return (
      <ScreenWrapper currentStep={step} nextStep={deceasedGender ? AppStep.SELECTION : undefined} prevStep={AppStep.ASSETS} setStep={setStep} disabled={!deceasedGender}>
        <div className="flex-1 flex flex-col items-center justify-center py-10 space-y-12 animate-in">
          <header className="text-center space-y-4">
            <h2 className="text-4xl font-black text-[#1E2E4F] malayalam">മരണപ്പെട്ട വ്യക്തി</h2>
            <p className="text-slate-500 font-bold malayalam text-lg opacity-60">ലിംഗഭേദം തിരഞ്ഞെടുക്കുക</p>
          </header>

          <div className="grid grid-cols-1 gap-6 w-full max-w-xs">
            {['Male', 'Female'].map(g => (
              <button 
                key={g}
                onClick={() => setDeceasedGender(g as any)}
                className={`p-10 rounded-[40px] font-black text-3xl malayalam transition-all active-press border-4 flex flex-col items-center gap-4 ${deceasedGender === g ? 'bg-[#1E2E4F] text-white border-[#D89F37] shadow-2xl scale-105' : 'bg-white text-slate-400 border-white shadow-lg'}`}
              >
                <span>{g === 'Male' ? 'പുരുഷൻ' : 'സ്ത്രീ'}</span>
                <span className="text-xs tracking-widest uppercase opacity-40">{g}</span>
              </button>
            ))}
          </div>
        </div>
      </ScreenWrapper>
    );
  }

  if (step === AppStep.SELECTION) {
    return (
      <ScreenWrapper currentStep={step} setStep={setStep} hideFooter={true}>
        <header className="shrink-0 pt-6 pb-4 text-center">
          <h2 className="text-2xl font-black text-[#1E2E4F] malayalam">അവകാശികൾ</h2>
          <p className="text-slate-500 font-bold malayalam text-sm opacity-50">എണ്ണം രേഖപ്പെടുത്തുക</p>
        </header>

        {/* Scrollable Relatives List */}
        <div className="flex-1 min-h-0 overflow-y-auto scroll-container hide-scrollbar space-y-4 mb-4">
          <div className="glass-card overflow-hidden shadow-xl border border-white/60">
            {HEIR_ORDER.map((type, idx) => {
              const meta = HEIR_METADATA[type];
              if (type === 'Husband' && deceasedGender !== 'Female') return null;
              if (type === 'Wives' && deceasedGender !== 'Male') return null;

              const count = getHeirCount(type as HeirType);

              return (
                <div key={type} className="flex flex-col">
                  <div className="flex items-center justify-between p-5 h-[80px]">
                    <div className="flex flex-col gap-0.5">
                      <span className="font-bold text-[#1E2E4F] tracking-tight">{type}</span>
                      <span className="text-[11px] malayalam text-slate-400 font-medium">{meta.ml}</span>
                    </div>
                    <div className="flex items-center gap-3 bg-slate-100/50 p-1.5 rounded-2xl shadow-inner border border-white/20">
                      <button 
                        onClick={() => updateHeirCount(type as HeirType, -1)} 
                        className={`w-10 h-10 rounded-xl flex items-center justify-center transition-all active-press ${count > 0 ? 'bg-white text-rose-500 shadow-sm border border-slate-200' : 'text-slate-300'}`}
                      >
                        <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M20 12H4" /></svg>
                      </button>
                      <span className={`w-6 text-center font-black text-lg ${count > 0 ? 'text-[#006B46]' : 'text-slate-300'}`}>{count}</span>
                      <button 
                        disabled={meta.max ? count >= meta.max : false}
                        onClick={() => updateHeirCount(type as HeirType, 1)} 
                        className="w-10 h-10 rounded-xl bg-white text-[#006B46] flex items-center justify-center shadow-sm border border-slate-200 transition-all active-press disabled:opacity-20"
                      >
                        <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M12 4v16m8-8H4" /></svg>
                      </button>
                    </div>
                  </div>
                  {idx < HEIR_ORDER.length - 1 && <div className="h-px bg-slate-100/60 mx-5" />}
                </div>
              );
            })}
          </div>
        </div>

        {/* Footer Actions inside the selection layout to ensure visibility */}
        <div className="shrink-0 pb-8 flex flex-col gap-3">
          <button 
            onClick={handleCalculate} 
            className="w-full bg-[#006B46] text-white py-5 rounded-2xl font-black text-xl active-press shadow-2xl malayalam flex items-center justify-center gap-3 shadow-[#006B46]/20"
          >
            കണക്കാക്കുക
            <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M13 5l7 7-7 7" /></svg>
          </button>
          <button 
            onClick={() => setStep(AppStep.GENDER)} 
            className="w-full h-14 rounded-2xl font-bold text-[#1E2E4F] bg-white/60 border border-slate-200 active-press malayalam text-base shadow-sm backdrop-blur-md"
          >
            പുറകോട്ട്
          </button>
        </div>
      </ScreenWrapper>
    );
  }

  if (step === AppStep.RESULT && result) {
    return (
      <div className="h-full flex flex-col overflow-hidden bg-transparent pt-safe">
        {/* Fixed Results Header */}
        <header className="px-6 py-6 text-center space-y-6 shrink-0">
          <h2 className="text-3xl font-black text-[#1E2E4F] malayalam tracking-tight">വിതരണ വിഹിതം</h2>
          <div className="glass-navy p-8 text-white space-y-1 shadow-2xl">
            <p className="text-[10px] font-black uppercase tracking-[0.3em] opacity-40">മൊത്തം വിതരണ തുക</p>
            <p className="text-4xl font-black text-[#D89F37]">₹{result.netEstate.toLocaleString()}</p>
          </div>
        </header>

        {/* Scrollable Results Content */}
        <div className="flex-1 min-h-0 overflow-y-auto scroll-container hide-scrollbar px-6 py-4 space-y-6">
          {/* Summary Stats */}
          <div className="bg-emerald-50/50 border border-emerald-100 p-6 rounded-[28px] space-y-4 shadow-sm backdrop-blur-md">
              <h3 className="font-bold text-[#006B46] text-xs uppercase tracking-widest malayalam opacity-60">വിഹിത സംഗ്രഹം</h3>
              <div className="grid grid-cols-2 gap-4">
                  <div className="space-y-1 border-r border-emerald-100 pr-2">
                      <p className="text-[9px] text-slate-400 font-bold uppercase tracking-widest">Fixed (Furudh)</p>
                      <p className="text-xl font-black text-[#1E2E4F]">{ (result.summary.fixedTotal * 100).toFixed(1) }%</p>
                  </div>
                  <div className="space-y-1">
                      <p className="text-[9px] text-slate-400 font-bold uppercase tracking-widest">Residue (Asabah)</p>
                      <p className="text-xl font-black text-[#1E2E4F]">{ (result.summary.residueTotal * 100).toFixed(1) }%</p>
                  </div>
              </div>
          </div>

          {/* Logic Warnings */}
          {result.warnings.length > 0 && result.warnings.map((w, i) => (
             <div key={i} className="bg-amber-50/70 border border-amber-100 p-5 rounded-2xl text-amber-800 text-[13px] font-bold malayalam flex gap-3 shadow-sm animate-in backdrop-blur-sm">
               <span className="text-lg">⚠️</span> {w}
             </div>
          ))}

          {/* Individual Shares List */}
          <div className="space-y-4 pb-12">
            <h3 className="px-2 font-black text-[#1E2E4F] malayalam text-[13px] uppercase tracking-widest opacity-40">വ്യക്തിഗത വിഹിതങ്ങൾ</h3>
            {result.shares.map((s, i) => (
              <div key={i} className="glass-card p-6 flex flex-col gap-4 border-l-8 border-l-[#006B46] animate-in shadow-md hover:scale-[1.01] transition-all">
                <div className="flex items-center justify-between">
                    <div className="space-y-0.5">
                        <p className="font-black text-[#1E2E4F] text-lg malayalam leading-tight">{s.label}</p>
                        <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">{s.type} • {s.symbol}</p>
                    </div>
                    <div className="bg-white/60 px-3 py-1.5 rounded-xl text-[10px] font-black text-slate-500 border border-slate-100">{s.count} പേർ</div>
                </div>

                <div className="h-px bg-slate-100/50 w-full" />

                <div className="flex items-center justify-between">
                    <div className="space-y-0.5">
                        <p className="text-[9px] font-bold text-slate-400 uppercase tracking-widest">വിഹിതം (Share)</p>
                        <p className="text-sm font-black text-[#1E2E4F]">{s.fraction} <span className="text-[10px] opacity-40">({s.percentage})</span></p>
                    </div>
                    <div className="text-right space-y-0.5">
                        <p className="text-[9px] font-bold text-slate-400 uppercase tracking-widest">ഒരാൾക്ക് (Per Person)</p>
                        <p className="text-2xl font-black text-[#006B46]">₹{Math.floor(s.amountEach).toLocaleString()}</p>
                    </div>
                </div>
              </div>
            ))}
          </div>
        </div>

        {/* Fixed Result Footer */}
        <div className="px-6 py-8 glass rounded-t-[40px] shadow-2xl shrink-0 pb-safe">
          <button 
            onClick={reset} 
            className="w-full bg-[#1E2E4F] text-white py-5 rounded-2xl font-black text-xl active-press malayalam shadow-xl shadow-[#1E2E4F]/20"
          >
            പുതിയ കണക്ക് തുടങ്ങുക
          </button>
        </div>
      </div>
    );
  }

  return null;
};

export default App;

