            {t('back')}
          </button>
        </div>
      </ScreenWrapper>
    );
  }

  if (step === AppStep.RESULT && result) {
    const isRtl = lang === 'ar';
    return (
      <div className="h-full flex flex-col overflow-hidden bg-transparent pt-safe" dir={isRtl ? 'rtl' : 'ltr'}>
