              <div key={i} className={`glass-card p-6 flex flex-col gap-4 border-${isRtl ? 'r' : 'l'}-8 border-${isRtl ? 'r' : 'l'}--[#006B46] animate-in shadow-md hover:scale-[1.01] transition-all`}>
