import { Heir, CalculationResult, HeirType, EstateData, HEIR_METADATA, HEIR_ORDER, Language } from '../types';

/**
 * Shāfiʿī Faraid Engine
 * Strictly follows Shāfiʿī rules for Zawil Furud, Asabah, Hijb, Aul, and Radd.
 */
export const calculateShares = (heirs: Heir[], deceasedGender: 'Male' | 'Female', estate: EstateData, lang: Language = 'en'): CalculationResult => {
  // Validate basic estate data
  const totalLiabilitiesBeforeWill = estate.debts + estate.funeral;
  const remainingAfterBasicLiabilities = Math.max(0, estate.totalAssets - totalLiabilitiesBeforeWill);

  // Wasiyyah (Will) rule: Cannot exceed 1/3 of the remaining estate after debts and funeral expenses
  const maxWillAllowed = remainingAfterBasicLiabilities / 3;
  const actualWill = Math.min(estate.will, maxWillAllowed);

  const netEstate = Math.max(0, remainingAfterBasicLiabilities - actualWill);

  const hMap = heirs.reduce((acc, h) => {
    acc[h.type] = h.count;
    return acc;
  }, {} as Record<string, number>);

  const getCount = (t: string) => hMap[t] || 0;

  // --- 1. HIJB (BLOCKING) ---
  const blocked = new Set<string>();

  const sons = getCount('Sons');
  const daughters = getCount('Daughters');
  const gsons = getCount('Grandsons');
  const gdaughters = getCount('Granddaughters');
  const father = getCount('Father');
  const mother = getCount('Mother');
  const gfather = getCount('Grandfather');

  const hasDescendant = sons > 0 || daughters > 0 || gsons > 0 || gdaughters > 0;

  // Rule 1: Father blocks Grandfather, Paternal Grandmother
  if (father > 0) {
    blocked.add('Grandfather');
    blocked.add('Paternal Grandmother');
    blocked.add('Full Brothers');
    blocked.add('Full Sisters');
    blocked.add('Paternal Brothers');
    blocked.add('Paternal Sisters');
    blocked.add('Maternal Brothers');
    blocked.add('Maternal Sisters');
  }

  // Rule 2: Mother blocks all Grandmothers
  if (mother > 0) {
    blocked.add('Paternal Grandmother');
    blocked.add('Maternal Grandmother');
  }

  // Rule 3: Sons block GSons, GDaughters, Siblings, Nephews, Uncles, Cousins
  if (sons > 0) {
    blocked.add('Grandsons');
    blocked.add('Granddaughters');
    blocked.add('Full Brothers');
    blocked.add('Full Sisters');
    blocked.add('Paternal Brothers');
    blocked.add('Paternal Sisters');
    blocked.add('Maternal Brothers');
    blocked.add('Maternal Sisters');
    blocked.add('Full Nephews');
    blocked.add('Paternal Nephews');
    blocked.add('Full Nephew’s Sons');
    blocked.add('Paternal Nephew’s Sons');
    blocked.add('Full Paternal Uncles');
    blocked.add('Paternal Paternal Uncles');
    blocked.add('Full Cousins');
    blocked.add('Paternal Cousins');
    blocked.add('Full Cousin’s Sons');
    blocked.add('Paternal Cousin’s Sons');
    blocked.add('Full Cousin’s Grandsons');
    blocked.add('Paternal Cousin’s Grandsons');
  }

  if (hasDescendant) {
    blocked.add('Maternal Brothers');
    blocked.add('Maternal Sisters');
  }

  if (gsons > 0) {
    blocked.add('Full Brothers');
    blocked.add('Full Sisters');
    blocked.add('Paternal Brothers');
    blocked.add('Paternal Sisters');
    blocked.add('Full Nephews');
    blocked.add('Paternal Nephews');
  }

  // --- 2. FIXED SHARES (Zawil Furud) ---
  const sharers: Array<{ type: string, num: number, den: number, symbol: string }> = [];

  if (deceasedGender === 'Female' && getCount('Husband') > 0) {
    sharers.push({ type: 'Husband', num: 1, den: hasDescendant ? 4 : 2, symbol: '1/4 | 1/2' });
  }
  if (deceasedGender === 'Male' && getCount('Wives') > 0) {
    sharers.push({ type: 'Wives', num: 1, den: hasDescendant ? 8 : 4, symbol: '1/8 | 1/4' });
  }
  if (mother > 0) {
    const sibCount = (getCount('Full Brothers') + getCount('Full Sisters') + getCount('Paternal Brothers') + getCount('Paternal Sisters') + getCount('Maternal Brothers') + getCount('Maternal Sisters'));
    sharers.push({ type: 'Mother', num: 1, den: (hasDescendant || sibCount >= 2) ? 6 : 3, symbol: '1/6 | 1/3' });
  }
  if (father > 0 && hasDescendant) {
    sharers.push({ type: 'Father', num: 1, den: 6, symbol: '1/6' });
  }
  if (gfather > 0 && !blocked.has('Grandfather') && hasDescendant) {
    sharers.push({ type: 'Grandfather', num: 1, den: 6, symbol: '1/6' });
  }
  if (daughters > 0 && sons === 0) {
    sharers.push({ type: 'Daughters', num: (daughters === 1 ? 1 : 2), den: (daughters === 1 ? 2 : 3), symbol: '1/2 | 2/3' });
  }
  if (gdaughters > 0 && sons === 0 && daughters < 2 && !blocked.has('Granddaughters')) {
     if (daughters === 0) {
        sharers.push({ type: 'Granddaughters', num: (gdaughters === 1 ? 1 : 2), den: (gdaughters === 1 ? 2 : 3), symbol: '1/2 | 2/3' });
     } else {
        sharers.push({ type: 'Granddaughters', num: 1, den: 6, symbol: '1/6' });
     }
  }
  const hasGm = (getCount('Paternal Grandmother') > 0 && !blocked.has('Paternal Grandmother')) || (getCount('Maternal Grandmother') > 0 && !blocked.has('Maternal Grandmother'));
  if (hasGm) {
    sharers.push({ type: 'Grandmothers_Combined', num: 1, den: 6, symbol: '1/6' });
  }
  const matSibCount = getCount('Maternal Brothers') + getCount('Maternal Sisters');
  if (matSibCount > 0 && !blocked.has('Maternal Brothers')) {
    sharers.push({ type: 'Maternal_Siblings_Combined', num: (matSibCount === 1 ? 1 : 1), den: (matSibCount === 1 ? 6 : 3), symbol: '1/6 | 1/3' });
  }

  const gcd = (a: number, b: number): number => b === 0 ? a : gcd(b, a % b);
  const lcm = (a: number, b: number): number => (a * b) / gcd(a, b);

  const commonDenom = sharers.length > 0 ? sharers.reduce((acc, s) => lcm(acc, s.den), 1) : 1;
  let totalNum = sharers.reduce((acc, s) => acc + (s.num * (commonDenom / s.den)), 0);

  const aulApplied = totalNum > commonDenom;
  const finalDenom = aulApplied ? totalNum : commonDenom;

  const result: CalculationResult = {
    shares: [],
    netEstate,
    summary: { fixedTotal: 0, residueTotal: 0, aulApplied, raddApplied: false },
    warnings: []
  };

  // Warning for Will reduction
  if (estate.will > maxWillAllowed) {
    result.warnings.push('error_will_limit');
  }

  sharers.forEach(s => {
    let actualCount = 1;
    if (s.type === 'Grandmothers_Combined') {
        const pgm = getCount('Paternal Grandmother');
        const mgm = getCount('Maternal Grandmother');
        actualCount = (pgm > 0 ? 1 : 0) + (mgm > 0 ? 1 : 0);
    } else if (s.type === 'Maternal_Siblings_Combined') {
        actualCount = matSibCount;
    } else {
        actualCount = getCount(s.type);
    }

    const shareTotal = (s.num * (commonDenom / s.den)) / finalDenom;
    const amount = netEstate * shareTotal;

    if (s.type === 'Grandmothers_Combined') {
        if (getCount('Maternal Grandmother') > 0) result.shares.push(createShareObj('Maternal Grandmother', 'Fixed', s.symbol, amount/actualCount, 1, shareTotal/actualCount, lang));
        if (getCount('Paternal Grandmother') > 0 && !blocked.has('Paternal Grandmother')) result.shares.push(createShareObj('Paternal Grandmother', 'Fixed', s.symbol, amount/actualCount, 1, shareTotal/actualCount, lang));
    } else if (s.type === 'Maternal_Siblings_Combined') {
        if (getCount('Maternal Brothers') > 0) result.shares.push(createShareObj('Maternal Brothers', 'Fixed', s.symbol, (amount/actualCount) * getCount('Maternal Brothers'), getCount('Maternal Brothers'), (shareTotal/actualCount) * getCount('Maternal Brothers'), lang));
        if (getCount('Maternal Sisters') > 0) result.shares.push(createShareObj('Maternal Sisters', 'Fixed', s.symbol, (amount/actualCount) * getCount('Maternal Sisters'), getCount('Maternal Sisters'), (shareTotal/actualCount) * getCount('Maternal Sisters'), lang));
    } else {
        result.shares.push(createShareObj(s.type, 'Fixed', s.symbol, amount, actualCount, shareTotal, lang));
    }
    result.summary.fixedTotal += shareTotal;
  });

  let residueRatio = 1 - result.summary.fixedTotal;
  if (residueRatio > 0.000001) {
    let asabaAssigned = false;

    if (sons > 0) {
      const units = (sons * 2) + daughters;
      const sonPart = (residueRatio * (2 / units));
      const daughterPart = (residueRatio * (1 / units));
      result.shares.push(createShareObj('Sons', 'Asabah', 'Asaba (2:1)', netEstate * sonPart * sons, sons, sonPart * sons, lang));
      if (daughters > 0) result.shares.push(createShareObj('Daughters', 'Asabah', 'Asaba (2:1)', netEstate * daughterPart * daughters, daughters, daughterPart * daughters, lang));
      asabaAssigned = true;
    } else if (gsons > 0) {
      const units = (gsons * 2) + gdaughters;
      const gsonPart = (residueRatio * (2 / units));
      const gdaughterPart = (residueRatio * (1 / units));
      result.shares.push(createShareObj('Grandsons', 'Asabah', 'Asaba (2:1)', netEstate * gsonPart * gsons, gsons, gsonPart * gsons, lang));
      if (gdaughters > 0) result.shares.push(createShareObj('Granddaughters', 'Asabah', 'Asaba (2:1)', netEstate * gdaughterPart * gdaughters, gdaughters, gdaughterPart * gdaughters, lang));
      asabaAssigned = true;
    } else if (father > 0) {
      result.shares.push(createShareObj('Father', 'Asabah', 'Asaba (F)', netEstate * residueRatio, 1, residueRatio, lang));
      asabaAssigned = true;
    } else if (gfather > 0 && !blocked.has('Grandfather')) {
        result.shares.push(createShareObj('Grandfather', 'Asabah', 'Asaba (F)', netEstate * residueRatio, 1, residueRatio, lang));
        asabaAssigned = true;
    } else if (getCount('Full Brothers') > 0) {
        const b = getCount('Full Brothers');
        const s = getCount('Full Sisters');
        const units = (b * 2) + s;
        const bPart = (residueRatio * (2 / units));
        const sPart = (residueRatio * (1 / units));
        result.shares.push(createShareObj('Full Brothers', 'Asabah', 'Asaba (2:1)', netEstate * bPart * b, b, bPart * b, lang));
        if (s > 0) result.shares.push(createShareObj('Full Sisters', 'Asabah', 'Asaba (2:1)', netEstate * sPart * s, s, sPart * s, lang));
        asabaAssigned = true;
    } else {
        const otherAsabaOrder = [
            'Paternal Brothers', 'Full Nephews', 'Paternal Nephews', 'Full Nephew’s Sons', 
            'Paternal Nephew’s Sons', 'Full Paternal Uncles', 'Paternal Paternal Uncles', 
            'Full Cousins', 'Paternal Cousins', 'Full Cousin’s Sons', 'Paternal Cousin’s Sons',
            'Full Cousin’s Grandsons', 'Paternal Cousin’s Grandsons'
        ];
        for (const type of otherAsabaOrder) {
            if (getCount(type) > 0 && !blocked.has(type)) {
                result.shares.push(createShareObj(type, 'Asabah', 'Asaba', netEstate * residueRatio, getCount(type), residueRatio, lang));
                asabaAssigned = true;
                break;
            }
        }
    }

    if (asabaAssigned) {
        result.summary.residueTotal = residueRatio;
    } else {
        const nonSpouseSharers = result.shares.filter(s => {
          const m = Object.values(HEIR_METADATA).find(x => x[lang] === s.label);
          const isHusband = m === HEIR_METADATA['Husband'];
          const isWife = m === HEIR_METADATA['Wives'];
          return !isHusband && !isWife && s.amount > 0;
        });
        if (nonSpouseSharers.length > 0) {
            result.summary.raddApplied = true;
            const totalSharerRatio = nonSpouseSharers.reduce((acc, s) => acc + (s.amount / netEstate), 0);
            nonSpouseSharers.forEach(s => {
                const added = (s.amount / (netEstate * totalSharerRatio)) * residueRatio;
                s.amount += netEstate * added;
                s.amountEach = s.amount / s.count;
                s.percentage = `${((s.amount / netEstate) * 100).toFixed(2)}%`;
            });
        }
    }
  }

  HEIR_ORDER.forEach(type => {
      if (getCount(type) > 0 && !result.shares.some(s => s.label === HEIR_METADATA[type][lang])) {
          result.shares.push({
              label: HEIR_METADATA[type][lang],
              type: 'Excluded',
              symbol: 'U',
              fraction: '0',
              percentage: '0%',
              amount: 0,
              count: getCount(type),
              amountEach: 0
          });
      }
  });

  return result;
};

const createShareObj = (type: string, sType: string, symbol: string, totalAmount: number, count: number, ratio: number, lang: Language) => {
    return {
        label: HEIR_METADATA[type] ? HEIR_METADATA[type][lang] : type,
        type: sType,
        symbol,
        fraction: ratioToFraction(ratio),
        percentage: `${(ratio * 100).toFixed(2)}%`,
        amount: totalAmount,
        count: count,
        amountEach: totalAmount / count
    };
};

const ratioToFraction = (r: number): string => {
    if (r === 0) return '0';
    const tolerance = 1.0e-6;
    let h1 = 1, h2 = 0, k1 = 0, k2 = 1;
    let b = r;
    do {
        let a = Math.floor(b);
        let aux = h1; h1 = a * h1 + h2; h2 = aux;
        aux = k1; k1 = a * k1 + k2; k2 = aux;
        b = 1 / (b - a);
    } while (Math.abs(r - h1 / k1) > r * tolerance);
    return `${h1}/${k1}`;
};

import React, { useState, useEffect } from 'react';
import { AppStep, Heir, HeirType, CalculationResult, HEIR_METADATA, HEIR_ORDER, EstateData, Language } from './types';
import { calculateShares } from './logic/faraidEngine';
import { translations } from './translations';
import { QRCodeCanvas } from 'qrcode.react';

/** 
 * ScreenWrapper provides a strict layout grid to prevent UI intersections
 */
interface ScreenWrapperProps {
  children: React.ReactNode;
  currentStep: AppStep;
  nextStep?: AppStep;
  prevStep?: AppStep;
  setStep: (step: AppStep) => void;
  nextLabel?: string;
  disabled?: boolean;
  hideFooter?: boolean;
  lang: Language;
}

const stepsOrder = [
  AppStep.LANGUAGE_SELECT,
  AppStep.WELCOME,
  AppStep.DESCRIPTION,
  AppStep.HADITH,
  AppStep.AYAH,
  AppStep.RULES,
  AppStep.ASSETS,
  AppStep.GENDER,
  AppStep.SELECTION,
  AppStep.RESULT
];

const ScreenWrapper: React.FC<ScreenWrapperProps> = ({ 
  children, 
  currentStep,
  nextStep, 
  prevStep, 
  setStep, 
  nextLabel, 
  disabled = false,
  hideFooter = false,
  lang
}) => {
  const stepIndex = stepsOrder.indexOf(currentStep);
  const t = (key: string) => (translations[lang] as any)[key] || key;
  const isRtl = lang === 'ar';

  return (
    <div className="h-full flex flex-col relative overflow-hidden bg-transparent pt-safe" dir={isRtl ? 'rtl' : 'ltr'}>
      {/* Fixed Progress Header */}
      <div className="shrink-0 z-[70]">
        {stepIndex >= 1 && (
          <div className="h-1.5 bg-slate-200/50 w-full">
            <div 
              className="h-full bg-[#D89F37] transition-all duration-700 ease-in-out shadow-[0_0_8px_rgba(216,159,55,0.4)]" 
              style={{ 
                width: `${((stepIndex) / (stepsOrder.length - 1)) * 100}%`,
                [isRtl ? 'right' : 'left']: 0 
              }}
            />
          </div>
        )}
      </div>

      {/* Main Content Area - Strictly non-overlapping */}
      <main className="flex-1 min-h-0 relative z-10 flex flex-col max-w-md mx-auto w-full px-5 overflow-hidden">
        {children}
      </main>

      {/* Persistent Glass Footer */}
      {!hideFooter && (
        <div className="px-6 py-6 glass flex justify-center gap-4 shrink-0 rounded-t-[32px] shadow-[0_-8px_30px_rgba(0,0,0,0.05)] pb-safe">
          {prevStep && (
            <button 
              onClick={() => setStep(prevStep)} 
              className="w-14 h-14 rounded-2xl flex items-center justify-center bg-white border border-slate-200 text-[#1E2E4F] active-press transition-all shadow-sm"
            >
              <svg className={`w-6 h-6 ${isRtl ? 'rotate-180' : ''}`} fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M15 19l-7-7 7-7" /></svg>
            </button>
          )}
          {nextStep && (
            <button 
              disabled={disabled} 
              onClick={() => setStep(nextStep)} 
              className="flex-1 h-14 bg-[#006B46] text-white rounded-2xl font-bold text-lg transition-all active-press shadow-lg shadow-[#006B46]/20 disabled:opacity-40"
            >
              {nextLabel || t('continue')}
            </button>
          )}
        </div>
      )}
    </div>
  );
};

const App: React.FC = () => {
  const [step, setStep] = useState<AppStep>(AppStep.LANGUAGE_SELECT);
  const [lang, setLang] = useState<Language>('en');
  const [deceasedGender, setDeceasedGender] = useState<'Male' | 'Female' | null>(null);
  const [heirs, setHeirs] = useState<Heir[]>([]);
  const [estate, setEstate] = useState<EstateData>({ totalAssets: 0, debts: 0, funeral: 0, will: 0 });
  const [result, setResult] = useState<CalculationResult | null>(null);
  const [showQR, setShowQR] = useState(false);
  const [uiError, setUiError] = useState<string | null>(null);

  useEffect(() => {
    const savedLang = localStorage.getItem('appLanguage') as Language;
    if (savedLang && Object.keys(translations).includes(savedLang)) {
      setLang(savedLang);
      setStep(AppStep.WELCOME);
    }
  }, []);

  const handleLangSelect = (l: Language) => {
    setLang(l);
    localStorage.setItem('appLanguage', l);
    setStep(AppStep.WELCOME);
  };

  const t = (key: string) => (translations[lang] as any)[key] || key;

  const updateHeirCount = (type: HeirType, delta: number) => {
    const meta = HEIR_METADATA[type as string];
    setHeirs(prev => {
      const existing = prev.find(h => h.type === type);
      if (existing) {
        let newCount = Math.max(0, existing.count + delta);
        if (meta.max) newCount = Math.min(newCount, meta.max);
        if (newCount === 0) return prev.filter(h => h.type !== type);
        return prev.map(h => h.type === type ? { ...h, count: newCount } : h);
      } else if (delta > 0) return [...prev, { type, count: 1 }];
      return prev;
    });
  };

  const getHeirCount = (type: HeirType) => heirs.find(h => h.type === type)?.count || 0;

  const handleCalculate = () => {
    setUiError(null);

    // 1. Validation: No heirs selected
    if (heirs.length === 0) {
      setUiError(t('error_no_heirs'));
      return;
    }

    // 2. Validation: Estate Assets <= Liabilities
    const totalLiabilities = estate.debts + estate.funeral + estate.will;
    if (estate.totalAssets <= (estate.debts + estate.funeral)) {
      setUiError(t('error_liabilities_exceed_assets'));
      return;
    }

    if (estate.totalAssets <= 0) {
      setUiError(t('error_invalid_assets'));
      return;
    }

    try {
      if (deceasedGender) {
        setResult(calculateShares(heirs, deceasedGender, estate, lang));
        setStep(AppStep.RESULT);
      }
    } catch (e) {
      console.error(e);
      setUiError(t('error_general'));
    }
  };

  const reset = () => {
    setHeirs([]);
    setDeceasedGender(null);
    setEstate({ totalAssets: 0, debts: 0, funeral: 0, will: 0 });
    setResult(null);
    setShowQR(false);
    setUiError(null);
    setStep(AppStep.WELCOME);
  };

  const getShareSummary = () => {
    if (!result) return "";
    let summary = `*${t('distribution_result')}*\n`;
    summary += `${t('net_estate')}: ₹${result.netEstate.toLocaleString()}\n\n`;
    result.shares.forEach(s => {
      if (s.amountEach > 0) {
        summary += `• ${s.label} (${s.count}): ₹${Math.floor(s.amountEach).toLocaleString()} ${t('per_person')}\n`;
      }
    });
    return summary;
  };

  if (step === AppStep.LANGUAGE_SELECT) {
    return (
      <div className="h-full bg-[#1E2E4F] flex flex-col items-center justify-center p-8 space-y-12 overflow-hidden text-center">
        <div className="space-y-4">
          <h1 className="text-3xl font-black text-white">Select Language</h1>
          <h1 className="text-2xl font-black text-white/80 malayalam">ഭാഷ തിരഞ്ഞെടുക്കുക</h1>
          <h1 className="text-2xl font-black text-white/70 arabic" dir="rtl">اختر اللغة</h1>
        </div>

        <div className="grid grid-cols-2 gap-4 w-full max-sm:px-4 max-w-sm mx-auto">
          {[
            { id: 'en', label: 'English' },
            { id: 'ml', label: 'മലയാളം' },
            { id: 'ta', label: 'தமிழ்' },
            { id: 'ar', label: 'العربية' }
          ].map(l => (
            <button 
              key={l.id} 
              onClick={() => handleLangSelect(l.id as Language)}
              className="glass-card p-6 flex flex-col items-center justify-center gap-2 border-white/20 hover:bg-white/20 transition-all active-press"
            >
              <span className="text-white font-bold text-lg">{l.label}</span>
              <span className="text-white/40 text-[10px] uppercase tracking-widest">{l.id}</span>
            </button>
          ))}
          <button className="col-span-2 py-4 text-white/30 text-xs font-bold uppercase tracking-widest border border-white/5 rounded-2xl">
            More Languages (Future)
          </button>
        </div>
      </div>
    );
  }

  if (step === AppStep.WELCOME) {
    return (
      <div className="h-full bg-[#1E2E4F] flex flex-col items-center justify-center p-10 text-white text-center relative overflow-hidden" dir={lang === 'ar' ? 'rtl' : 'ltr'}>
        <div className="absolute top-0 right-0 w-64 h-64 bg-[#006B46]/20 rounded-full -mr-32 -mt-32 blur-3xl"></div>
        <div className="absolute bottom-0 left-0 w-64 h-64 bg-[#D89F37]/10 rounded-full -ml-32 -mb-32 blur-3xl"></div>

        <div className="relative z-10 animate-in space-y-12 w-full">
          <div className="w-32 h-32 bg-white/10 backdrop-blur-xl rounded-[40px] flex items-center justify-center mx-auto shadow-2xl border border-white/20">
            <svg className="w-16 h-16 text-[#D89F37]" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1.5} d="M12 6.253v13m0-13C10.832 5.477 9.246 5 7.5 5S4.168 5.477 3 6.253v13C4.168 18.477 5.754 18 7.5 18s3.332.477 4.5 1.253m0-13C13.168 5.477 14.754 5 16.5 5c1.747 0 3.332.477 4.5 1.253v13C19.832 18.247 18.247 18 16.5 18c-1.746 0-3.332.477-4.5 1.253" />
            </svg>
          </div>

          <div className="space-y-4">
            <h1 className="text-4xl font-extrabold tracking-tight text-white drop-shadow-md">{t('app_title')}</h1>
            <p className="text-slate-300 text-lg opacity-80 font-medium">{t('app_subtitle')}</p>
          </div>

          <div className="flex flex-col gap-4 max-w-xs mx-auto w-full">
            <button 
              onClick={() => setStep(AppStep.DESCRIPTION)} 
              className="w-full bg-[#006B46] text-white py-5 rounded-2xl font-bold text-xl active-press shadow-2xl"
            >
              {t('start')}
            </button>
            <button 
              onClick={() => setStep(AppStep.LANGUAGE_SELECT)} 
              className="text-white/40 text-xs font-bold uppercase tracking-widest underline decoration-white/10"
            >
              Change Language
            </button>
          </div>
        </div>
      </div>
    );
  }

  if (step === AppStep.DESCRIPTION) {
    return (
      <ScreenWrapper lang={lang} currentStep={step} nextStep={AppStep.HADITH} prevStep={AppStep.WELCOME} setStep={setStep}>
        <div className="flex-1 overflow-y-auto scroll-container hide-scrollbar py-8 space-y-8 animate-in text-center">
          <h2 className="text-3xl font-black text-[#1E2E4F]">{t('what_is_faraid')}</h2>
          <div className="glass-card p-8 space-y-6 text-slate-700 text-lg leading-relaxed shadow-lg">
            <p>{t('faraid_desc_1')}</p>
            <p>{t('faraid_desc_2')}</p>
            <div className="pt-4 flex justify-center">
              <div className="w-16 h-1.5 bg-[#D89F37]/30 rounded-full"></div>
            </div>
          </div>
        </div>
      </ScreenWrapper>
    );
  }

  if (step === AppStep.HADITH) {
    return (
      <ScreenWrapper lang={lang} currentStep={step} nextStep={AppStep.AYAH} prevStep={AppStep.DESCRIPTION} setStep={setStep}>
        <div className="flex-1 flex flex-col justify-center py-8 animate-in space-y-8">
          <div className="w-16 h-16 bg-[#006B46]/10 rounded-full flex items-center justify-center text-[#006B46] mx-auto">
            <svg className="w-8 h-8" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5 13l4 4L19 7" /></svg>
          </div>
          <div className="glass-card p-10 w-full relative overflow-hidden shadow-xl">
            <div className="absolute top-0 right-0 p-4 opacity-5">
              <svg className="w-32 h-32" fill="currentColor" viewBox="0 0 24 24"><path d="M13 14.725c0-5.141 3.892-10.519 10-10.519l.716 2.185c-3.136 1.054-5.136 3.054-5.136 5.484 0 1.656.804 2.185 1.512 2.185 1.275 0 2.374 1.108 2.374 2.538 0 1.532-1.22 2.538-2.625 2.538-2.146 0-6.841-1.603-6.841-6.411zm-13 0c0-5.141 3.892-10.519 10-10.519l.716 2.185c-3.136 1.054-5.136 3.054-5.136 5.484 0 1.656.804 2.185 1.512 2.185 1.275 0 2.374 1.108 2.374 2.538 0 1.532-1.22 2.538-2.625 2.538-2.146 0-6.841-1.603-6.841-6.411z"/></svg>
            </div>
            <div className="arabic mb-8 text-center" dir="rtl">{t('hadith_arabic')}</div>
            <p className="text-center text-[#1E2E4F] font-bold text-lg leading-relaxed">
              {t('hadith_translation')}
            </p>
            <p className="mt-8 text-center text-slate-400 font-bold text-sm tracking-widest uppercase">{t('hadith_ref')}</p>
          </div>
        </div>
      </ScreenWrapper>
    );
  }

  if (step === AppStep.AYAH) {
    return (
      <ScreenWrapper lang={lang} currentStep={step} nextStep={AppStep.RULES} prevStep={AppStep.HADITH} setStep={setStep}>
        <div className="flex-1 flex flex-col justify-center py-8 animate-in space-y-8">
          <div className="w-16 h-16 bg-[#D89F37]/10 rounded-full flex items-center justify-center text-[#D89F37] mx-auto">
             <svg className="w-8 h-8" fill="currentColor" viewBox="0 0 24 24"><path d="M12 2L4.5 20.29l.71.71L12 18l6.79 3 .71-.71L12 2z"/></svg>
          </div>
          <div className="glass-card p-10 w-full shadow-xl">
            <div className="arabic mb-8 text-center" dir="rtl">{t('ayah_arabic')}</div>
            <p className="text-center text-[#1E2E4F] font-bold text-lg leading-relaxed">
              {t('ayah_translation')}
            </p>
            <p className="mt-8 text-center text-slate-400 font-bold text-sm tracking-widest uppercase">{t('ayah_ref')}</p>
          </div>
        </div>
      </ScreenWrapper>
    );
  }

  if (step === AppStep.RULES) {
    return (
      <ScreenWrapper lang={lang} currentStep={step} nextStep={AppStep.ASSETS} prevStep={AppStep.AYAH} setStep={setStep}>
        <header className="shrink-0 py-6 text-center space-y-2">
          <h2 className="text-3xl font-black text-[#1E2E4F]">{t('rules_title')}</h2>
          <p className="text-slate-500 font-bold">{t('rules_subtitle')}</p>
        </header>

        <div className="flex-1 overflow-y-auto scroll-container hide-scrollbar space-y-5 pb-8">
          <div className="glass-card p-6 space-y-3 shadow-md border-l-4 border-[#006B46]">
            <h3 className="font-black text-[#1E2E4F] text-lg">{t('fixed_shares_title')}</h3>
            <p className="text-slate-600 leading-relaxed text-sm">{t('fixed_shares_desc')}</p>
          </div>

          <div className="glass-card p-6 space-y-3 shadow-md border-l-4 border-[#D89F37]">
            <h3 className="font-black text-[#1E2E4F] text-lg">{t('asabah_title')}</h3>
            <p className="text-slate-600 leading-relaxed text-sm">{t('asabah_desc')}</p>
          </div>

          <div className="glass-card p-6 space-y-3 shadow-md border-l-4 border-rose-800">
            <h3 className="font-black text-[#1E2E4F] text-lg">{t('hijb_title')}</h3>
            <p className="text-slate-600 leading-relaxed text-sm">{t('hijb_desc')}</p>
          </div>

          <div className="p-4 text-center opacity-40">
            <div className="w-12 h-1 bg-slate-300 mx-auto rounded-full mb-2"></div>
            <p className="text-[10px] uppercase font-black tracking-widest">Al-Shafi'i Jurisprudence</p>
          </div>
        </div>
      </ScreenWrapper>
    );
  }

  if (step === AppStep.ASSETS) {
    return (
      <ScreenWrapper lang={lang} currentStep={step} nextStep={AppStep.GENDER} prevStep={AppStep.RULES} setStep={setStep}>
        <header className="shrink-0 py-6 text-center space-y-2">
          <h2 className="text-3xl font-black text-[#1E2E4F]">{t('estate_info')}</h2>
          <p className="text-slate-500 font-bold">{t('estate_subtitle')}</p>
        </header>

        <div className="flex-1 overflow-y-auto scroll-container hide-scrollbar space-y-5 pb-8">
          {[
            { label: t('total_assets'), key: 'totalAssets', icon: '💰' },
            { label: t('debts'), key: 'debts', icon: '📉' },
            { label: t('funeral_expenses'), key: 'funeral', icon: '🕯️' },
            { label: t('will_wasiyyah'), key: 'will', icon: '📜' }
          ].map(f => (
            <div key={f.key} className="glass-card p-6 space-y-3 shadow-md">
              <div className="flex items-center gap-3">
                <span className="text-xl">{f.icon}</span>
                <label className="text-xs font-bold text-slate-400 uppercase tracking-widest">{f.label}</label>
              </div>
              <div className="relative">
                <span className="absolute left-0 top-1/2 -translate-y-1/2 text-2xl font-black text-slate-300 ml-1">₹</span>
                <input 
                  type="number"
                  inputMode="numeric"
                  placeholder="0"
                  value={(estate as any)[f.key] || ''}
                  onChange={e => setEstate({...estate, [f.key]: Math.max(0, Number(e.target.value))})}
                  className={`w-full bg-transparent border-b-2 border-slate-100 py-3 ${lang === 'ar' ? 'pr-8 pl-0' : 'pl-8'} text-2xl font-black text-[#1E2E4F] outline-none focus:border-[#006B46] transition-colors`}
                />
              </div>
            </div>
          ))}
        </div>
      </ScreenWrapper>
    );
  }

  if (step === AppStep.GENDER) {
    return (
      <ScreenWrapper lang={lang} currentStep={step} nextStep={deceasedGender ? AppStep.SELECTION : undefined} prevStep={AppStep.ASSETS} setStep={setStep} disabled={!deceasedGender}>
